	struct LinuxMemoryHookRecord {
		LinuxMemoryHookRecord() noexcept;
		~LinuxMemoryHookRecord() noexcept {
			for (auto const& Page : m_vecPages) {
				if (Page.m_bOwnedMapping) {
					// Destruction cannot recover from an unmap failure.
					::munmap(reinterpret_cast<void*>(Page.m_unAddress), Page.m_unSize);
				}
			}
		}

		Detours::Hook::fnMemoryHookCallBack m_pCallBack;
		Detours::Hook::fnMemoryHookCallBack m_pPostCallBack;
		fnDetoursMemoryHookContextCallBack m_pContextCallBack;
		fnDetoursMemoryHookContextCallBack m_pContextPostCallBack;
		fnDetoursAbandonedMemoryHookCallBack m_fnAbandonedCallBack;
		void* m_pContext;
		void* m_pAddress;
		std::size_t m_unSize;
		bool m_bManualProtection;
		std::vector<LinuxMemoryHookPage> m_vecPages;
		std::atomic<bool> m_bInstalling;
		std::atomic<bool> m_bHooked;
		std::atomic<bool> m_bRearmGuard;
		std::atomic<bool> m_bPendingUnhook;
		std::atomic<bool> m_bDeferredUnhook;
		std::atomic<unsigned int> m_unActiveRearms;
		std::atomic<unsigned int> m_unOpenReferences;
		std::atomic<unsigned int> m_unUnhookReferences;
	};

