	static_assert(std::atomic<bool>::is_always_lock_free, "Linux private events require a lock-free atomic signal state");
	static_assert(std::atomic<LinuxPrivateEventState*>::is_always_lock_free, "Linux private events require a lock-free atomic state pointer");
	static_assert(std::atomic<pid_t>::is_always_lock_free, "Linux mutexes require lock-free process and thread ID atomics");
	static_assert(std::atomic<std::size_t>::is_always_lock_free, "Linux mutexes and thread suspension require lock-free size atomics");
	static_assert(std::atomic<std::uint64_t>::is_always_lock_free, "Linux mutexes require lock-free generation atomics");
	static_assert(std::atomic<int>::is_always_lock_free, "Linux shared semaphores require a lock-free atomic counter");
	static_assert(std::atomic<LinuxSemaphoreState*>::is_always_lock_free, "Linux private semaphores require a lock-free atomic state pointer");
	static_assert(std::atomic<LinuxPipeConnectionState*>::is_always_lock_free, "Linux pipes require a lock-free atomic connection state pointer");
	static_assert(std::is_same<pid_t, int>::value && (ATOMIC_INT_LOCK_FREE == 2), "Linux thread state requires lock-free process and thread IDs");
	static_assert(std::atomic<unsigned int>::is_always_lock_free, "Linux hook dispatch frames require lock-free states");
	static_assert(std::atomic<LinuxProtectedMemoryJournalState>::is_always_lock_free, "Linux Protected memory journals require lock-free states");
	static_assert(std::atomic<LinuxMemoryHookRecord*>::is_always_lock_free, "Linux memory hooks require lock-free signal-reference owners");
	static_assert(ATOMIC_POINTER_LOCK_FREE == 2, "Linux signal state requires lock-free snapshot pointers");
	static_assert(ATOMIC_BOOL_LOCK_FREE == 2, "Linux signal state requires lock-free hook flags");
	static_assert(ATOMIC_INT_LOCK_FREE == 2, "Linux cleanup notifications require lock-free descriptor references");

