	enum class WindowsHardwareRecordState : unsigned int {
		INSTALLING = 0,
		CANCEL_REQUESTED,
		ACTIVE
	};

	struct HardwareHookRecord final {
	public:
		HardwareHookRecord() noexcept;
		~HardwareHookRecord() noexcept;

	public:
		HardwareHookRecord(HardwareHookRecord const&) = delete;
		HardwareHookRecord& operator=(HardwareHookRecord const&) = delete;
		HardwareHookRecord(HardwareHookRecord&&) = delete;
		HardwareHookRecord& operator=(HardwareHookRecord&&) = delete;

	private:
		void Clear() noexcept;

	public:
		DWORD m_unThreadID;
		HANDLE m_hThread;
		HARDWARE_HOOK_REGISTER m_Register;
		fnHardwareHookCallBack m_pCallBack;
		void* m_pAddress;
		HARDWARE_HOOK_TYPE m_Type;
		unsigned char m_unSize;
		DWORD_PTR m_unPreviousAddress;
		DWORD_PTR m_unPreviousDR7Bits;
		std::atomic<bool> m_bOriginalTrapFlag;
		std::atomic<bool> m_bPendingRestore;
		std::atomic<bool> m_bPendingDeletion;
		std::atomic<bool> m_bCancelRestore;
		std::atomic<unsigned int> m_unPins;
		unsigned int m_unGeneration;
		std::atomic<unsigned long long> m_unOperationOwner;
		std::atomic<WindowsHardwareRecordState> m_State;
		bool m_bUnHookInProgress;
	};

	HardwareHookRecord::HardwareHookRecord() noexcept {
		m_unThreadID = 0;
		m_hThread = nullptr;
		m_Register = HARDWARE_HOOK_REGISTER::REGISTER_DR0;
		m_pCallBack = nullptr;
		m_pAddress = nullptr;
		m_Type = HARDWARE_HOOK_TYPE::TYPE_EXECUTE;
		m_unSize = 0;
		m_unPreviousAddress = 0;
		m_unPreviousDR7Bits = 0;
		m_bOriginalTrapFlag = false;
		m_bPendingRestore = false;
		m_bPendingDeletion = false;
		m_bCancelRestore = false;
		m_unPins = 0;
		m_unGeneration = 0;
		m_unOperationOwner = 0;
		m_State = WindowsHardwareRecordState::INSTALLING;
		m_bUnHookInProgress = false;
	}

	HardwareHookRecord::~HardwareHookRecord() noexcept {
		Clear();
	}

	void HardwareHookRecord::Clear() noexcept {
		if (m_hThread && (m_hThread != INVALID_HANDLE_VALUE)) {
			CloseHandle(m_hThread);
		}

		m_hThread = nullptr;
	}

