	static std::atomic<unsigned int> g_unWindowsHardwareHookRecordGeneration = 0;
	KUSER_SHARED_DATA const volatile& g_KUserSharedData = *reinterpret_cast<PKUSER_SHARED_DATA>(kKUserSharedDataAddress);
	KUSER_SHARED_DATA const volatile& KUserSharedData = g_KUserSharedData;
	// This breakpoint helper is copied into a writable Storage allocation and
	// switched to execute-read after copying, matching the pWrapper/trampoline
	// allocation lifecycle. All synchronization, thread, and memory operations
	// use documented Win32 APIs; the remote-TEB compatibility query below is the
	// only optional ntdll export and never depends on a syscall number or gate.
#if defined(DETOURS_ARCH_X64)
	using fnWindowsHardwareContextBreakpoint = void(__cdecl*)(void* pFrame);

	constexpr unsigned char kWindowsHardwareContextBreakpointCode[] = { 0xCC, 0xC3 };
#elif defined(DETOURS_ARCH_X86)
	using fnWindowsHardwareContextBreakpoint = void(__cdecl*)(void* pFrame);

	constexpr unsigned char kWindowsHardwareContextBreakpointCode[] = { 0x8B, 0x44, 0x24, 0x04, 0xCC, 0xC3 };
#endif

	constexpr std::size_t kWindowsEmbeddedHardwareBreakpointNoSizeAlignment = 1;
	constexpr std::size_t kWindowsEmbeddedHardwareBreakpointCodeAlignment = alignof(void*);
#if defined(DETOURS_ARCH_X64)
	constexpr std::size_t kWindowsHardwareContextBreakpointInstructionOffset = 0;
#elif defined(DETOURS_ARCH_X86)
	constexpr std::size_t kWindowsHardwareContextBreakpointInstructionOffset = 4;
#endif
	constexpr std::size_t kWindowsEmbeddedHardwareBreakpointCodeSize = sizeof(kWindowsHardwareContextBreakpointCode);

	struct WindowsEmbeddedHardwareBreakpointState final {
		WindowsEmbeddedHardwareBreakpointState() noexcept;

		WindowsEmbeddedHardwareBreakpointState(WindowsEmbeddedHardwareBreakpointState const&) = delete;
		WindowsEmbeddedHardwareBreakpointState& operator=(WindowsEmbeddedHardwareBreakpointState const&) = delete;
		WindowsEmbeddedHardwareBreakpointState(WindowsEmbeddedHardwareBreakpointState&&) = delete;
		WindowsEmbeddedHardwareBreakpointState& operator=(WindowsEmbeddedHardwareBreakpointState&&) = delete;

		Storage m_Storage;
		void* m_pCode;
		void const* m_pBreakpointInstruction;
		fnWindowsHardwareContextBreakpoint m_fnHardwareContextBreakpoint;
	};

	WindowsEmbeddedHardwareBreakpointState::WindowsEmbeddedHardwareBreakpointState() noexcept :
		m_Storage(kWindowsEmbeddedHardwareBreakpointCodeSize, kWindowsEmbeddedHardwareBreakpointCodeSize),
		m_pCode(nullptr),
		m_pBreakpointInstruction(nullptr),
		m_fnHardwareContextBreakpoint(nullptr)
	{
		unsigned char* const pCode = reinterpret_cast<unsigned char*>(m_Storage.Alloc(kWindowsEmbeddedHardwareBreakpointCodeSize, kWindowsEmbeddedHardwareBreakpointNoSizeAlignment, kWindowsEmbeddedHardwareBreakpointCodeAlignment));
		if (!pCode) {
			return;
		}

		std::size_t unOffset = 0;
		auto CopyCode = [&pCode, &unOffset](auto const& Code) noexcept -> unsigned char* {
			unsigned char* const pCodeEntry = pCode + unOffset;
			std::memcpy(pCodeEntry, Code, sizeof(Code));
			unOffset += sizeof(Code);
			return pCodeEntry;
		};

		unsigned char* const pBreakpoint = CopyCode(kWindowsHardwareContextBreakpointCode);
		m_fnHardwareContextBreakpoint = reinterpret_cast<fnWindowsHardwareContextBreakpoint>(pBreakpoint);
		m_pBreakpointInstruction = pBreakpoint + kWindowsHardwareContextBreakpointInstructionOffset;

		Protection CodeProtection(pCode, kWindowsEmbeddedHardwareBreakpointCodeSize, false);
		if (!CodeProtection.Change(PAGE_EXECUTE_READ)) {
			m_Storage.DeAllocAll();
			return;
		}

		m_pCode = pCode;
	}

	static WindowsEmbeddedHardwareBreakpointState* GetWindowsEmbeddedHardwareBreakpointState() noexcept {
		// Keep the executable allocation for the process lifetime; VEH and hook
		// teardown paths can still call these stubs during static destruction.
		static WindowsEmbeddedHardwareBreakpointState* const pState = []() noexcept -> WindowsEmbeddedHardwareBreakpointState* {
			try {
				return new WindowsEmbeddedHardwareBreakpointState();
			} catch (...) {
				return nullptr;
			}
		} ();

		return pState;
	}

	static WindowsEmbeddedHardwareBreakpointState* GetWindowsEmbeddedHardwareBreakpointReadyState() noexcept {
		WindowsEmbeddedHardwareBreakpointState* const pState = GetWindowsEmbeddedHardwareBreakpointState();
		return (pState && pState->m_pCode) ? pState : nullptr;
	}

	static void const* GetWindowsHardwareContextBreakpointAddress() noexcept {
		WindowsEmbeddedHardwareBreakpointState* const pState = GetWindowsEmbeddedHardwareBreakpointReadyState();
		return pState ? pState->m_pBreakpointInstruction : nullptr;
	}

	static void WindowsHardwareContextBreakpoint(void* pFrame) {
		WindowsEmbeddedHardwareBreakpointState* const pState = GetWindowsEmbeddedHardwareBreakpointReadyState();
		if (pState && pState->m_fnHardwareContextBreakpoint) {
			pState->m_fnHardwareContextBreakpoint(pFrame);
		}
	}

	static NTSTATUS EnumerateNextWindowsThread(HANDLE const hPreviousThread, HANDLE* const phThreadOut) noexcept {
		constexpr ACCESS_MASK kDesiredAccess =
			THREAD_QUERY_INFORMATION |
			THREAD_QUERY_LIMITED_INFORMATION |
			SYNCHRONIZE |
			THREAD_SUSPEND_RESUME |
			THREAD_GET_CONTEXT |
			THREAD_SET_CONTEXT;
		constexpr DWORD kThreadSnapshotFlags = TH32CS_SNAPTHREAD;

		if (!phThreadOut) {
			return kWindowsNativeCallNotAttempted;
		}

		*phThreadOut = nullptr;
		DWORD unPreviousThreadID = 0;
		if (hPreviousThread) {
			unPreviousThreadID = GetThreadId(hPreviousThread);
			if (!unPreviousThreadID) {
				return kWindowsNativeCallNotAttempted;
			}
		}

		HANDLE const hSnapshot = CreateToolhelp32Snapshot(kThreadSnapshotFlags, 0);
		if (hSnapshot == INVALID_HANDLE_VALUE) {
			return kWindowsNativeCallNotAttempted;
		}

		THREADENTRY32 ThreadEntry {};
		ThreadEntry.dwSize = sizeof(ThreadEntry);
		bool bAfterPreviousThread = !hPreviousThread;
		if (Thread32First(hSnapshot, &ThreadEntry)) {
			do {
				if (ThreadEntry.th32OwnerProcessID != GetCurrentProcessId()) {
					continue;
				}

				if (!bAfterPreviousThread) {
					if (ThreadEntry.th32ThreadID == unPreviousThreadID) {
						bAfterPreviousThread = true;
					}

					continue;
				}

				HANDLE const hThread = OpenThread(kDesiredAccess, FALSE, ThreadEntry.th32ThreadID);
				if (hThread) {
					CloseHandle(hSnapshot);
					*phThreadOut = hThread;
					return 0;
				}
			} while (Thread32Next(hSnapshot, &ThreadEntry));
		}

		CloseHandle(hSnapshot);
		return kWindowsNativeNoMoreEntries;
	}

	static DWORD GetCurrentWindowsThreadStateReaperThreadID() noexcept {
		PTEB const pTEB = GetTEB();
		if (!pTEB || !pTEB->ClientId.UniqueThread) {
			return 0;
		}

		const ULONG_PTR unThreadID = static_cast<ULONG_PTR>(pTEB->ClientId.UniqueThread);
		if (unThreadID > std::numeric_limits<DWORD>::max()) {
			return 0;
		}

		return static_cast<DWORD>(unThreadID);
	}

	// These two declarations are the minimum recursive exception/reaper interface:
	// Windows state recovery invokes the Exception namespace before its recovery
	// implementation, and the reaper implementation calls back into this state.
	namespace Exception {
		static bool EnsureWindowsThreadStateReaper() noexcept;
		static bool RecoverWindowsMemoryHookThreadState(WindowsMemoryHookThreadState* pThreadState) noexcept;
	} // namespace Exception

	static WindowsHookProcessState* GetHookProcessState() noexcept {
		return g_pPublishedWindowsHookProcessState.load(std::memory_order_acquire);
	}

	static WindowsHookProcessState* EnsureHookProcessState() noexcept {
		static WindowsHookProcessState* const s_pState = []() noexcept -> WindowsHookProcessState* {
			WindowsHookProcessState* const pNewState = new (std::nothrow) WindowsHookProcessState();
			if (!pNewState) {
				return nullptr;
			}

			// Published hook state intentionally lives until process termination.
			g_pPublishedWindowsHookProcessState.store(pNewState, std::memory_order_release);
			return pNewState;
		} ();

		return s_pState;
	}

	static unsigned long long GetWindowsThreadStateOwnerToken(WindowsMemoryHookThreadState const* const pThreadState, const unsigned int unGeneration) noexcept {
		constexpr std::size_t kThreadStateSlotSize = sizeof(WindowsMemoryHookThreadState);
		constexpr unsigned int kOwnerGenerationShift = std::numeric_limits<unsigned int>::digits;
		constexpr unsigned long long kOwnerSlotBias = 1;

		static_assert(kOwnerGenerationShift < std::numeric_limits<unsigned long long>::digits, "owner-token generation shift exceeds its representation");
		static_assert(kWindowsThreadStateSlotCapacity > 0, "thread-state slot capacity must be positive");
		static_assert(kWindowsThreadStateSlotCapacity <= std::numeric_limits<unsigned int>::max(), "thread-state slot index exceeds the owner-token field");

		WindowsHookProcessState* const pProcessState = GetHookProcessState();
		if (!pProcessState || !pThreadState || !unGeneration) {
			return 0;
		}

		const std::uintptr_t unThreadStateAddress = reinterpret_cast<std::uintptr_t>(pThreadState);
		const std::uintptr_t unThreadStateArrayAddress = reinterpret_cast<std::uintptr_t>(&pProcessState->m_arrMemoryHookThreadStates[0]);
		if (unThreadStateAddress < unThreadStateArrayAddress) {
			return 0;
		}

		const std::uintptr_t unThreadStateOffset = unThreadStateAddress - unThreadStateArrayAddress;
		const std::uintptr_t unSlotIndexValue = unThreadStateOffset / kThreadStateSlotSize;
		if (((unThreadStateOffset % kThreadStateSlotSize) != 0) ||
			(unSlotIndexValue >= kWindowsThreadStateSlotCapacity)) {
			return 0;
		}

		const std::size_t unSlotIndex = static_cast<std::size_t>(unSlotIndexValue);
		return (static_cast<unsigned long long>(unGeneration) << kOwnerGenerationShift) |
			(static_cast<unsigned long long>(unSlotIndex) + kOwnerSlotBias);
	}

	static WindowsThreadLiveness GetWindowsThreadLiveness(HANDLE const hThread) noexcept {
		if (!hThread || (hThread == INVALID_HANDLE_VALUE)) {
			return WindowsThreadLiveness::UNKNOWN;
		}

		const DWORD unWaitResult = WaitForSingleObject(hThread, 0);
		if (unWaitResult == WAIT_OBJECT_0) {
			return WindowsThreadLiveness::TERMINATED;
		}

		if (unWaitResult == WAIT_TIMEOUT) {
			return WindowsThreadLiveness::LIVE;
		}

		return WindowsThreadLiveness::UNKNOWN;
	}

	static HANDLE DuplicateCurrentWindowsThreadHandle() noexcept {
		constexpr DWORD kNoDuplicateOptions = 0;

		HANDLE hThread = nullptr;
		if (!DuplicateHandle(GetCurrentProcess(), GetCurrentThread(), GetCurrentProcess(), &hThread, SYNCHRONIZE, FALSE, kNoDuplicateOptions)) {
			return nullptr;
		}

		if (!hThread || (hThread == INVALID_HANDLE_VALUE)) {
			return nullptr;
		}

		return hThread;
	}

	static WindowsThreadStateSlotStatus GetWindowsThreadStateSlotStatus(const unsigned int unSlotState) noexcept {
		return static_cast<WindowsThreadStateSlotStatus>(unSlotState & kWindowsThreadStateSlotStatusMask);
	}

	static bool PinWindowsThreadStateSlot(std::atomic<unsigned int>& SlotState) noexcept {
		unsigned int unSlotState = SlotState.load(std::memory_order_acquire);
		for (;;) {
			if ((GetWindowsThreadStateSlotStatus(unSlotState) != WindowsThreadStateSlotStatus::ACTIVE) ||
				(unSlotState > (std::numeric_limits<unsigned int>::max() - kWindowsThreadStateSlotPinIncrement))) {
				return false;
			}

			if (SlotState.compare_exchange_weak(unSlotState, unSlotState + kWindowsThreadStateSlotPinIncrement, std::memory_order_acq_rel, std::memory_order_acquire)) {
				return true;
			}
		}
	}

	static bool PinWindowsThreadStateSlotForRecovery(std::atomic<unsigned int>& SlotState, WindowsThreadStateSlotStatus* const pStatusOut) noexcept {
		if (!pStatusOut) {
			return false;
		}

		unsigned int unSlotState = SlotState.load(std::memory_order_acquire);
		for (;;) {
			const WindowsThreadStateSlotStatus Status = GetWindowsThreadStateSlotStatus(unSlotState);
			if (((Status != WindowsThreadStateSlotStatus::INITIALIZING) &&
				(Status != WindowsThreadStateSlotStatus::ACTIVE)) ||
				(unSlotState > (std::numeric_limits<unsigned int>::max() - kWindowsThreadStateSlotPinIncrement))) {
				return false;
			}

			if (SlotState.compare_exchange_weak(unSlotState, unSlotState + kWindowsThreadStateSlotPinIncrement, std::memory_order_acq_rel, std::memory_order_acquire)) {
				*pStatusOut = Status;
				return true;
			}
		}
	}

	static void UnpinWindowsThreadStateSlot(std::atomic<unsigned int>& SlotState) noexcept {
		SlotState.fetch_sub(kWindowsThreadStateSlotPinIncrement, std::memory_order_release);
	}

	static bool TransitionWindowsThreadStateSlot(std::atomic<unsigned int>& SlotState, const WindowsThreadStateSlotStatus ExpectedStatus, const WindowsThreadStateSlotStatus DesiredStatus) noexcept {
		unsigned int unSlotState = SlotState.load(std::memory_order_acquire);
		for (;;) {
			if (GetWindowsThreadStateSlotStatus(unSlotState) != ExpectedStatus) {
				return false;
			}

			const unsigned int unDesiredSlotState = (unSlotState & ~kWindowsThreadStateSlotStatusMask) | static_cast<unsigned int>(DesiredStatus);
			if (SlotState.compare_exchange_weak(unSlotState, unDesiredSlotState, std::memory_order_acq_rel, std::memory_order_acquire)) {
				return true;
			}
		}
	}

	static void WaitForWindowsThreadStateSlotPins(std::atomic<unsigned int>& SlotState) noexcept {
		while ((SlotState.load(std::memory_order_acquire) & ~kWindowsThreadStateSlotStatusMask) != 0) {
			_mm_pause();
		}
	}

	template <typename ThreadStateType, std::size_t unCapacity>
	static bool HasBlockingWindowsThreadStateIdentity(ThreadStateType (&arrThreadStates)[unCapacity], const DWORD unThreadID, ThreadStateType const* const pExcludedThreadState = nullptr) noexcept {
		if (!unThreadID) {
			return true;
		}

		for (auto& ThreadState : arrThreadStates) {
			if (&ThreadState == pExcludedThreadState) {
				continue;
			}

			WindowsThreadStateSlotStatus Status = GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire));
			if ((Status == WindowsThreadStateSlotStatus::FREE) ||
				(ThreadState.m_unThreadID.load(std::memory_order_acquire) != unThreadID)) {
				continue;
			}

			if ((Status == WindowsThreadStateSlotStatus::RETIRING) ||
				(Status == WindowsThreadStateSlotStatus::RECOVERING)) {
				return true;
			}

			WindowsThreadStateSlotStatus PinnedStatus = WindowsThreadStateSlotStatus::FREE;
			if (!PinWindowsThreadStateSlotForRecovery(ThreadState.m_unSlotState, &PinnedStatus)) {
				Status = GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire));
				if ((Status != WindowsThreadStateSlotStatus::FREE) &&
					(ThreadState.m_unThreadID.load(std::memory_order_acquire) == unThreadID)) {
					return true;
				}

				continue;
			}

			const unsigned int unGeneration = ThreadState.m_unGeneration.load(std::memory_order_acquire);
			HANDLE const hThread = ThreadState.m_hThread.load(std::memory_order_acquire);
			const WindowsThreadLiveness Liveness = GetWindowsThreadLiveness(hThread);
			const bool bIdentityStable =
				(GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire)) == PinnedStatus) &&
				(ThreadState.m_unThreadID.load(std::memory_order_acquire) == unThreadID) &&
				(ThreadState.m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
				(ThreadState.m_hThread.load(std::memory_order_acquire) == hThread);
			UnpinWindowsThreadStateSlot(ThreadState.m_unSlotState);

			if ((!bIdentityStable) ||
				(Liveness != WindowsThreadLiveness::TERMINATED)) {
				return true;
			}
		}

		return false;
	}

	static unsigned int AdvanceWindowsThreadStateGeneration(std::atomic<unsigned int>& Generation) noexcept {
		constexpr unsigned int kGenerationStep = 1;

		unsigned int unGeneration = Generation.fetch_add(kGenerationStep, std::memory_order_acq_rel) + kGenerationStep;
		if (!unGeneration) {
			unGeneration = Generation.fetch_add(kGenerationStep, std::memory_order_acq_rel) + kGenerationStep;
		}

		return unGeneration;
	}

	static void ClearWindowsHardwareOperationFrame(WindowsHardwareOperationFrame* const pFrame) noexcept {
		if (!pFrame) {
			return;
		}

		pFrame->m_Type = WindowsHardwareOperationType::NONE;
		pFrame->m_Step.store(WindowsHardwareOperationStep::NONE, std::memory_order_relaxed);
		pFrame->m_pRecord = nullptr;
		pFrame->m_unOwnerToken = 0;
		pFrame->m_unThreadStateGeneration = 0;
		pFrame->m_unRecordGeneration = 0;
		pFrame->m_unOwnerThreadID = 0;
		pFrame->m_unTargetThreadID = 0;
		pFrame->m_unDRIndex = 0;
		pFrame->m_bCurrentTarget = false;
		pFrame->m_bForceRestore = false;
		pFrame->m_bRecordPinOwned.store(false, std::memory_order_relaxed);
		pFrame->m_bPreviousSlotCaptured = false;
		pFrame->m_bContextMutationSucceeded = false;
		pFrame->m_FinalSlotState = WindowsHardwareSlotState::UNKNOWN;
		pFrame->m_unPreviousSuspendCount = kWindowsHardwareOperationSuspendCountUnknown;
		pFrame->m_unPreviousResumeCount = kWindowsHardwareOperationSuspendCountUnknown;
		pFrame->m_nSuspendStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nGetContextStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nSetContextStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nVerificationStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nResumeStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_OriginalContext = {};
		pFrame->m_DesiredContext = {};
		pFrame->m_VerificationContext = {};
	}

	static void ClearWindowsSuspenderFrame(WindowsSuspenderFrame* const pFrame) noexcept {
		if (!pFrame) {
			return;
		}

		pFrame->m_Step.store(WindowsSuspenderFrameStep::NONE, std::memory_order_relaxed);
		pFrame->m_hTargetThread.store(nullptr, std::memory_order_relaxed);
		pFrame->m_unOwnerToken = 0;
		pFrame->m_unThreadStateGeneration = 0;
		pFrame->m_unTargetThreadID = 0;
		pFrame->m_unPreviousSuspendCount = kWindowsSuspenderCountUnknown;
		pFrame->m_unPreviousResumeCount = kWindowsSuspenderCountUnknown;
		pFrame->m_nSuspendStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nGetContextStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nSetContextStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_nResumeStatus = kWindowsNativeCallNotAttempted;
		pFrame->m_unDesiredInstructionPointer.store(0, std::memory_order_relaxed);
		pFrame->m_State.store(WindowsSuspenderFrameState::FREE, std::memory_order_release);
	}

	static WindowsMemoryHookThreadState* GetWindowsThreadStateFromOwnerToken(const unsigned long long unOwnerToken, unsigned int* const pGenerationOut) noexcept {
		constexpr unsigned int kOwnerGenerationShift = std::numeric_limits<unsigned int>::digits;
		constexpr unsigned int kOwnerSlotBias = 1;

		static_assert(kOwnerGenerationShift < std::numeric_limits<unsigned long long>::digits, "owner-token generation shift exceeds its representation");

		WindowsHookProcessState* const pProcessState = GetHookProcessState();
		const unsigned int unGeneration = static_cast<unsigned int>(unOwnerToken >> kOwnerGenerationShift);
		const unsigned int unEncodedSlot = static_cast<unsigned int>(unOwnerToken);
		if (!pProcessState || !unGeneration || !unEncodedSlot || (unEncodedSlot > kWindowsThreadStateSlotCapacity)) {
			return nullptr;
		}

		WindowsMemoryHookThreadState* const pThreadState = &pProcessState->m_arrMemoryHookThreadStates[unEncodedSlot - kOwnerSlotBias];
		if (pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration) {
			return nullptr;
		}

		if (pGenerationOut) {
			*pGenerationOut = unGeneration;
		}

		return pThreadState;
	}

	static WindowsSuspenderFrame* GetWindowsSuspenderFrame(const unsigned long long unOwnerToken, const std::size_t unFrameIndex) noexcept {
		if (unFrameIndex >= kWindowsSuspenderFrameCapacity) {
			return nullptr;
		}

		unsigned int unGeneration = 0;
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, &unGeneration);
		if (!pThreadState || (GetWindowsThreadStateOwnerToken(pThreadState, unGeneration) != unOwnerToken)) {
			return nullptr;
		}

		return &pThreadState->m_arrSuspenderFrames[unFrameIndex];
	}

	static WindowsSuspenderFrame* ReserveWindowsSuspenderFrame(const unsigned long long unOwnerToken, const DWORD unTargetThreadID, HANDLE const hTargetThread, std::size_t* const pFrameIndexOut) noexcept {
		if (!unOwnerToken || !unTargetThreadID || !hTargetThread || (hTargetThread == INVALID_HANDLE_VALUE) || !pFrameIndexOut) {
			return nullptr;
		}

		unsigned int unGeneration = 0;
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, &unGeneration);
		const DWORD unCurrentThreadID = GetCurrentWindowsThreadStateReaperThreadID();

		auto IsThreadStateReservationValid = [pThreadState, unGeneration, unOwnerToken, unCurrentThreadID]() noexcept -> bool {
			return (pThreadState != nullptr) &&
				(unCurrentThreadID != 0) &&
				(GetWindowsThreadStateSlotStatus(pThreadState->m_unSlotState.load(std::memory_order_acquire)) == WindowsThreadStateSlotStatus::ACTIVE) &&
				(pThreadState->m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
				(GetWindowsThreadStateOwnerToken(pThreadState, unGeneration) == unOwnerToken) &&
				(pThreadState->m_unThreadID.load(std::memory_order_acquire) == unCurrentThreadID) &&
				(pThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire) != 0);
		};

		if (!IsThreadStateReservationValid()) {
			return nullptr;
		}

		WindowsSuspenderFrame* pFrame = nullptr;
		for (std::size_t unIndex = 0; unIndex < kWindowsSuspenderFrameCapacity; ++unIndex) {
			WindowsSuspenderFrame& Candidate = pThreadState->m_arrSuspenderFrames[unIndex];
			WindowsSuspenderFrameState ExpectedState = WindowsSuspenderFrameState::FREE;
			if (!Candidate.m_State.compare_exchange_strong(ExpectedState, WindowsSuspenderFrameState::PREPARING, std::memory_order_acq_rel, std::memory_order_acquire)) {
				continue;
			}

			if (!IsThreadStateReservationValid()) {
				ClearWindowsSuspenderFrame(&Candidate);
				return nullptr;
			}

			Candidate.m_Step.store(WindowsSuspenderFrameStep::NONE, std::memory_order_relaxed);
			Candidate.m_hTargetThread.store(hTargetThread, std::memory_order_relaxed);
			Candidate.m_unOwnerToken = unOwnerToken;
			Candidate.m_unThreadStateGeneration = unGeneration;
			Candidate.m_unTargetThreadID = unTargetThreadID;
			Candidate.m_unPreviousSuspendCount = kWindowsSuspenderCountUnknown;
			Candidate.m_unPreviousResumeCount = kWindowsSuspenderCountUnknown;
			Candidate.m_nSuspendStatus = kWindowsNativeCallNotAttempted;
			Candidate.m_nGetContextStatus = kWindowsNativeCallNotAttempted;
			Candidate.m_nSetContextStatus = kWindowsNativeCallNotAttempted;
			Candidate.m_nResumeStatus = kWindowsNativeCallNotAttempted;
			Candidate.m_unDesiredInstructionPointer.store(0, std::memory_order_relaxed);
			Candidate.m_State.store(WindowsSuspenderFrameState::PUBLISHED, std::memory_order_release);
			*pFrameIndexOut = unIndex;
			pFrame = &Candidate;
			break;
		}

		return pFrame;
	}

	static bool SuspendWindowsSuspenderFrame(WindowsSuspenderFrame* const pFrame, CONTEXT* const pContextOut) noexcept {
		if (!pFrame || !pContextOut || (pFrame->m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::PUBLISHED)) {
			return false;
		}

		pFrame->m_unPreviousSuspendCount = kWindowsSuspenderCountUnknown;
		pFrame->m_Step.store(WindowsSuspenderFrameStep::SUSPENDING, std::memory_order_release);
		HANDLE const hTargetThread = pFrame->m_hTargetThread.load(std::memory_order_acquire);
		const DWORD unPreviousSuspendCount = SuspendThread(hTargetThread);
		pFrame->m_nSuspendStatus = unPreviousSuspendCount == kWindowsInvalidThreadSuspendCount ? kWindowsNativeCallNotAttempted : 0;
		if (pFrame->m_nSuspendStatus >= 0) {
			pFrame->m_unPreviousSuspendCount = unPreviousSuspendCount;
		}

		if (pFrame->m_nSuspendStatus < 0) {
			pFrame->m_unPreviousSuspendCount = kWindowsSuspenderCountUnknown;
			pFrame->m_Step.store(WindowsSuspenderFrameStep::NONE, std::memory_order_release);
			return false;
		}

		pFrame->m_Step.store(WindowsSuspenderFrameStep::TARGET_SUSPENDED, std::memory_order_release);

		*pContextOut = {};
		pContextOut->ContextFlags = CONTEXT_FULL;
		pFrame->m_nGetContextStatus = GetThreadContext(hTargetThread, pContextOut) ? 0 : kWindowsNativeCallNotAttempted;
		if (pFrame->m_nGetContextStatus < 0) {
			return false;
		}

		return true;
	}

	static bool ResumeWindowsSuspenderFrame(WindowsSuspenderFrame* const pFrame) noexcept {
		if (!pFrame) {
			return false;
		}

		WindowsSuspenderFrameStep Step = pFrame->m_Step.load(std::memory_order_acquire);
		if (Step == WindowsSuspenderFrameStep::SUSPENDING) {
			Step = (pFrame->m_unPreviousSuspendCount == kWindowsSuspenderCountUnknown) ? WindowsSuspenderFrameStep::NONE : WindowsSuspenderFrameStep::TARGET_SUSPENDED;
			pFrame->m_Step.store(Step, std::memory_order_release);
		} else if (Step == WindowsSuspenderFrameStep::RESUMING) {
			Step = (pFrame->m_unPreviousResumeCount == kWindowsSuspenderCountUnknown) ? WindowsSuspenderFrameStep::TARGET_SUSPENDED : WindowsSuspenderFrameStep::TARGET_RESUMED;
			pFrame->m_Step.store(Step, std::memory_order_release);
		}

		if ((Step == WindowsSuspenderFrameStep::NONE) || (Step == WindowsSuspenderFrameStep::TARGET_RESUMED)) {
			return true;
		}

		if (Step != WindowsSuspenderFrameStep::TARGET_SUSPENDED) {
			return false;
		}

		const std::uintptr_t unDesiredInstructionPointer = pFrame->m_unDesiredInstructionPointer.load(std::memory_order_acquire);
		if (unDesiredInstructionPointer) {
			CONTEXT CurrentContext {};
			CurrentContext.ContextFlags = CONTEXT_CONTROL;
			pFrame->m_nGetContextStatus = GetThreadContext(pFrame->m_hTargetThread.load(std::memory_order_acquire), &CurrentContext) ? 0 : kWindowsNativeCallNotAttempted;
			if (pFrame->m_nGetContextStatus < 0) {
				return false;
			}

#if defined(DETOURS_ARCH_X64)
			CurrentContext.Rip = static_cast<DWORD64>(unDesiredInstructionPointer);
#elif defined(DETOURS_ARCH_X86)
			CurrentContext.Eip = static_cast<DWORD>(unDesiredInstructionPointer);
#endif

			pFrame->m_nSetContextStatus = SetThreadContext(pFrame->m_hTargetThread.load(std::memory_order_acquire), &CurrentContext) ? 0 : kWindowsNativeCallNotAttempted;
			if (pFrame->m_nSetContextStatus < 0) {
				return false;
			}
		}

		pFrame->m_Step.store(WindowsSuspenderFrameStep::RESUMING, std::memory_order_release);
		HANDLE const hTargetThread = pFrame->m_hTargetThread.load(std::memory_order_acquire);
		const DWORD unPreviousResumeCount = ResumeThread(hTargetThread);
		pFrame->m_nResumeStatus = unPreviousResumeCount == kWindowsInvalidThreadSuspendCount ? kWindowsNativeCallNotAttempted : 0;
		if (pFrame->m_nResumeStatus >= 0) {
			pFrame->m_unPreviousResumeCount = unPreviousResumeCount;
		}

		if (pFrame->m_nResumeStatus < 0) {
			pFrame->m_unPreviousResumeCount = kWindowsSuspenderCountUnknown;
			pFrame->m_Step.store(WindowsSuspenderFrameStep::TARGET_SUSPENDED, std::memory_order_release);
			return false;
		}

		pFrame->m_Step.store(WindowsSuspenderFrameStep::TARGET_RESUMED, std::memory_order_release);

		return true;
	}

	static bool ReleaseWindowsSuspenderFrame(WindowsSuspenderFrame* const pFrame) noexcept {
		if ((!pFrame) ||
			((pFrame->m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::PUBLISHED) &&
				(pFrame->m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::RECOVERING))) {
			return false;
		}

		HANDLE hTargetThread = pFrame->m_hTargetThread.load(std::memory_order_acquire);
		while (hTargetThread && !pFrame->m_hTargetThread.compare_exchange_weak(hTargetThread, nullptr, std::memory_order_acq_rel, std::memory_order_acquire)) {
		}

		if (hTargetThread && (hTargetThread != INVALID_HANDLE_VALUE) && !CloseHandle(hTargetThread)) {
			HANDLE hExpectedTargetThread = nullptr;
			// Preserve a concurrent replacement and restore this handle only while the slot remains empty.
#pragma warning(suppress: 6001) // The handle was obtained from the atomic thread-state exchange above.
			pFrame->m_hTargetThread.compare_exchange_strong(hExpectedTargetThread, hTargetThread, std::memory_order_release, std::memory_order_relaxed);
			return false;
		}

		ClearWindowsSuspenderFrame(pFrame);

		return true;
	}

	static bool HasWindowsSuspenderPayload(WindowsMemoryHookThreadState const* const pThreadState) noexcept {
		if (!pThreadState) {
			return false;
		}

		for (auto const& Frame : pThreadState->m_arrSuspenderFrames) {
			if (Frame.m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::FREE) {
				return true;
			}
		}

		return false;
	}

	static bool ReleaseUnusedWindowsSuspenderFrames(const unsigned long long unOwnerToken) noexcept {
		unsigned int unGeneration = 0;
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, &unGeneration);
		if (!pThreadState || !PinWindowsThreadStateSlot(pThreadState->m_unSlotState)) {
			return false;
		}

		bool bSuccess = true;
		for (auto& Frame : pThreadState->m_arrSuspenderFrames) {
			if ((Frame.m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::PUBLISHED) ||
				(Frame.m_unOwnerToken != unOwnerToken) ||
				(Frame.m_unThreadStateGeneration != unGeneration) ||
				(Frame.m_Step.load(std::memory_order_acquire) != WindowsSuspenderFrameStep::NONE)) {
				continue;
			}

			if (!ReleaseWindowsSuspenderFrame(&Frame)) {
				bSuccess = false;
			}
		}

		UnpinWindowsThreadStateSlot(pThreadState->m_unSlotState);

		return bSuccess;
	}

	static bool RecoverTerminatedWindowsSuspenderFrames(WindowsMemoryHookThreadState* const pThreadState, const unsigned long long unOwnerToken) noexcept {
		if (!pThreadState || !unOwnerToken) {
			return false;
		}

		const unsigned int unGeneration = pThreadState->m_unGeneration.load(std::memory_order_acquire);
		if ((GetWindowsThreadStateOwnerToken(pThreadState, unGeneration) != unOwnerToken) ||
			(GetWindowsThreadLiveness(pThreadState->m_hThread.load(std::memory_order_acquire)) != WindowsThreadLiveness::TERMINATED)) {
			return false;
		}

		bool bSuccess = true;
		for (auto& Frame : pThreadState->m_arrSuspenderFrames) {
			WindowsSuspenderFrameState State = Frame.m_State.load(std::memory_order_acquire);
			if (State == WindowsSuspenderFrameState::FREE) {
				continue;
			}

			if (State == WindowsSuspenderFrameState::PREPARING) {
				HANDLE hTargetThread = Frame.m_hTargetThread.load(std::memory_order_acquire);
				while (hTargetThread && !Frame.m_hTargetThread.compare_exchange_weak(hTargetThread, nullptr, std::memory_order_acq_rel, std::memory_order_acquire)) {
				}

				if (hTargetThread && (hTargetThread != INVALID_HANDLE_VALUE) && !CloseHandle(hTargetThread)) {
					HANDLE hExpectedTargetThread = nullptr;
					// Preserve a concurrent replacement and restore this handle only while the slot remains empty.
#pragma warning(suppress: 6001) // The handle was obtained from the atomic thread-state exchange above.
					Frame.m_hTargetThread.compare_exchange_strong(hExpectedTargetThread, hTargetThread, std::memory_order_release, std::memory_order_relaxed);
					bSuccess = false;
					continue;
				}

				ClearWindowsSuspenderFrame(&Frame);
				continue;
			}

			if (State == WindowsSuspenderFrameState::PUBLISHED) {
				if ((!Frame.m_State.compare_exchange_strong(State, WindowsSuspenderFrameState::RECOVERING, std::memory_order_acq_rel, std::memory_order_acquire)) &&
					(State != WindowsSuspenderFrameState::RECOVERING)) {
					bSuccess = false;
					continue;
				}

			} else if (State != WindowsSuspenderFrameState::RECOVERING) {
				bSuccess = false;
				continue;
			}

			HANDLE const hTargetThread = Frame.m_hTargetThread.load(std::memory_order_acquire);
			if (!hTargetThread) {
				ClearWindowsSuspenderFrame(&Frame);
				continue;
			}

			if ((Frame.m_unOwnerToken != unOwnerToken) || (Frame.m_unThreadStateGeneration != unGeneration)) {
				bSuccess = false;
				continue;
			}

			const WindowsThreadLiveness TargetLiveness = GetWindowsThreadLiveness(hTargetThread);
			if (TargetLiveness == WindowsThreadLiveness::UNKNOWN) {
				bSuccess = false;
				continue;
			}

			if ((TargetLiveness == WindowsThreadLiveness::LIVE) && !ResumeWindowsSuspenderFrame(&Frame)) {
				bSuccess = false;
				continue;
			}

			if (!ReleaseWindowsSuspenderFrame(&Frame)) {
				bSuccess = false;
			}
		}

		return bSuccess;
	}

	static void ClearWindowsProtectedMemoryStateLockFrame(WindowsProtectedMemoryStateLockFrame* const pFrame) noexcept {
		if (!pFrame) {
			return;
		}

		pFrame->m_pState = nullptr;
		pFrame->m_pJournal = nullptr;
		pFrame->m_unOwnerToken = 0;
		pFrame->m_unThreadStateGeneration = 0;
		pFrame->m_unDepth.store(0, std::memory_order_relaxed);
		pFrame->m_Purpose = WindowsProtectedMemoryStateLockPurpose::NONE;
		pFrame->m_RecoverySourceState = WindowsProtectedMemoryStateLockFrameState::FREE;
		pFrame->m_bRecoveryQuarantined = false;
		pFrame->m_pContainmentAddress = nullptr;
		pFrame->m_unContainmentSize = 0;
		pFrame->m_pShadowContainmentAddress.store(nullptr, std::memory_order_release);
		pFrame->m_unShadowContainmentSize = 0;
		pFrame->m_State.store(WindowsProtectedMemoryStateLockFrameState::FREE, std::memory_order_release);
	}

	static void ClearWindowsProtectedMemoryRegistryLockFrame(WindowsProtectedMemoryRegistryLockFrame* const pFrame) noexcept {
		if (!pFrame) {
			return;
		}

		pFrame->m_unOwnerToken = 0;
		pFrame->m_unThreadStateGeneration = 0;
		pFrame->m_RecoverySourceState = WindowsProtectedMemoryRegistryLockFrameState::FREE;
		pFrame->m_State.store(WindowsProtectedMemoryRegistryLockFrameState::FREE, std::memory_order_release);
	}

	static void ClearWindowsMemoryHookThreadStatePayload(WindowsMemoryHookThreadState* const pThreadState) noexcept {
		if (!pThreadState) {
			return;
		}

		pThreadState->m_unHandlerDepth = 0;
		pThreadState->m_unCallBackDepth = 0;
		pThreadState->m_unOpenedCount = 0;
		pThreadState->m_unPostCount = 0;
		pThreadState->m_unHandlerReferenceCount = 0;
		pThreadState->m_unThreadStateReaperPauseDepth.store(0, std::memory_order_relaxed);

		for (auto& pRecord : pThreadState->m_arrOpened) {
			pRecord = nullptr;
		}

		for (auto& PostContext : pThreadState->m_arrPosts) {
			PostContext.Clear();
		}

		for (auto& pRecord : pThreadState->m_arrHandlerReferences) {
			pRecord = nullptr;
		}

		for (auto& FrameContext : pThreadState->m_arrFrames) {
			FrameContext = {};
		}

		ClearWindowsHardwareOperationFrame(&pThreadState->m_HardwareOperationFrame);
		pThreadState->m_HardwareOperationFrame.m_State.store(WindowsHardwareOperationState::FREE, std::memory_order_release);

		for (auto& Frame : pThreadState->m_arrSuspenderFrames) {
			ClearWindowsSuspenderFrame(&Frame);
		}

		for (auto& Frame : pThreadState->m_arrProtectedMemoryStateLockFrames) {
			ClearWindowsProtectedMemoryStateLockFrame(&Frame);
		}

		ClearWindowsProtectedMemoryRegistryLockFrame(&pThreadState->m_ProtectedMemoryRegistryLockFrame);
	}

	static bool IsWindowsMemoryHookThreadStateIdle(WindowsMemoryHookThreadState const* const pThreadState) noexcept {
		if (!pThreadState) {
			return false;
		}

		if ((pThreadState->m_unHandlerDepth != 0) ||
			(pThreadState->m_unCallBackDepth != 0) ||
			(pThreadState->m_unOpenedCount != 0) ||
			(pThreadState->m_unPostCount != 0) ||
			(pThreadState->m_unHandlerReferenceCount != 0) ||
			(pThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire) != 0) ||
			(pThreadState->m_bRecoveryPending.load(std::memory_order_acquire)) ||
			(pThreadState->m_HardwareOperationFrame.m_State.load(std::memory_order_acquire) != WindowsHardwareOperationState::FREE) ||
			(pThreadState->m_ProtectedMemoryRegistryLockFrame.m_State.load(std::memory_order_acquire) != WindowsProtectedMemoryRegistryLockFrameState::FREE)) {
			return false;
		}

		for (auto const& FrameContext : pThreadState->m_arrFrames) {
			if ((FrameContext.m_unOpenedBegin != 0) ||
				(FrameContext.m_unOpenedCount != 0) ||
				(FrameContext.m_unPostBegin != 0) ||
				(FrameContext.m_unPostCount != 0) ||
				(FrameContext.m_unHandlerReferenceBegin != 0) ||
				(FrameContext.m_unHandlerReferenceCount != 0) ||
				(FrameContext.m_bOriginalTrapFlag) ||
				(FrameContext.m_bArmed) ||
				(FrameContext.m_bPostFailed) ||
				(FrameContext.m_bRecoveryOnly)) {
				return false;
			}
		}

		for (auto const& PostContext : pThreadState->m_arrPosts) {
			if (PostContext.m_EntryState.load(std::memory_order_acquire) != WindowsMemoryHookEntryState::FREE) {
				return false;
			}
		}

		if (HasWindowsSuspenderPayload(pThreadState)) {
			return false;
		}

		for (auto const& Frame : pThreadState->m_arrProtectedMemoryStateLockFrames) {
			if (Frame.m_State.load(std::memory_order_acquire) != WindowsProtectedMemoryStateLockFrameState::FREE) {
				return false;
			}
		}

		return true;
	}

	static void FreeWindowsMemoryHookThreadState(WindowsMemoryHookThreadState* const pThreadState) noexcept {
		if (!pThreadState) {
			return;
		}

		const unsigned int unGeneration = pThreadState->m_unGeneration.load(std::memory_order_acquire);
		const unsigned long long unOwnerToken = GetWindowsThreadStateOwnerToken(pThreadState, unGeneration);
		if (unOwnerToken) {
			unsigned long long unExpectedOwnerToken = unOwnerToken;
			// Clear the control owner only while this thread state still owns it.
			g_unWindowsThreadStateReaperControlOwnerToken.compare_exchange_strong(unExpectedOwnerToken, 0, std::memory_order_acq_rel, std::memory_order_acquire);
		}

		ClearWindowsMemoryHookThreadStatePayload(pThreadState);
		pThreadState->m_unThreadID.store(0, std::memory_order_relaxed);
		pThreadState->m_unActiveLeases.store(0, std::memory_order_relaxed);
		pThreadState->m_bRecoveryPending.store(false, std::memory_order_relaxed);
		HANDLE const hThread = pThreadState->m_hThread.exchange(nullptr, std::memory_order_acq_rel);
		if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
			// Slot retirement cannot propagate cleanup status, so this close is intentionally best-effort.
			CloseHandle(hThread);
		}

		pThreadState->m_unSlotState.store(static_cast<unsigned int>(WindowsThreadStateSlotStatus::FREE), std::memory_order_release);
	}

	static void AbandonInitializingWindowsMemoryHookThreadState(WindowsMemoryHookThreadState* const pThreadState, const DWORD unThreadID, const unsigned int unGeneration, HANDLE const hThread) noexcept {
		if (!pThreadState || !unThreadID || !unGeneration || !hThread) {
			return;
		}

		WindowsThreadStateSlotStatus Status = WindowsThreadStateSlotStatus::FREE;
		if (!PinWindowsThreadStateSlotForRecovery(pThreadState->m_unSlotState, &Status)) {
			return;
		}

		const bool bIdentityMatches =
			(Status == WindowsThreadStateSlotStatus::INITIALIZING) &&
			(pThreadState->m_unThreadID.load(std::memory_order_acquire) == unThreadID) &&
			(pThreadState->m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
			(pThreadState->m_hThread.load(std::memory_order_acquire) == hThread);
		const bool bTransitioned = bIdentityMatches && TransitionWindowsThreadStateSlot(pThreadState->m_unSlotState, WindowsThreadStateSlotStatus::INITIALIZING, WindowsThreadStateSlotStatus::RETIRING);
		UnpinWindowsThreadStateSlot(pThreadState->m_unSlotState);

		if (!bTransitioned) {
			return;
		}

		WaitForWindowsThreadStateSlotPins(pThreadState->m_unSlotState);
		if ((GetWindowsThreadStateSlotStatus(pThreadState->m_unSlotState.load(std::memory_order_acquire)) != WindowsThreadStateSlotStatus::RETIRING) ||
			(pThreadState->m_unThreadID.load(std::memory_order_acquire) != unThreadID) ||
			(pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration) ||
			(pThreadState->m_hThread.load(std::memory_order_acquire) != hThread)) {
			return;
		}

		FreeWindowsMemoryHookThreadState(pThreadState);
	}

	static void RetireIdleWindowsMemoryHookThreadState(WindowsMemoryHookThreadState* const pThreadState, const unsigned int unGeneration) noexcept {
		if (!pThreadState || !unGeneration) {
			return;
		}

		if ((GetWindowsThreadStateSlotStatus(pThreadState->m_unSlotState.load(std::memory_order_acquire)) != WindowsThreadStateSlotStatus::ACTIVE) ||
			(pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration) ||
			(pThreadState->m_unActiveLeases.load(std::memory_order_acquire) != 0) ||
			(!IsWindowsMemoryHookThreadStateIdle(pThreadState))) {
			return;
		}

		if (!TransitionWindowsThreadStateSlot(pThreadState->m_unSlotState, WindowsThreadStateSlotStatus::ACTIVE, WindowsThreadStateSlotStatus::RETIRING)) {
			return;
		}

		WaitForWindowsThreadStateSlotPins(pThreadState->m_unSlotState);
		if ((pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration) ||
			(pThreadState->m_unActiveLeases.load(std::memory_order_acquire) != 0) ||
			(!IsWindowsMemoryHookThreadStateIdle(pThreadState))) {
			pThreadState->m_unSlotState.store(static_cast<unsigned int>(WindowsThreadStateSlotStatus::ACTIVE), std::memory_order_release);
			return;
		}

		FreeWindowsMemoryHookThreadState(pThreadState);
	}

	static void ReleaseWindowsMemoryHookThreadState(WindowsMemoryHookThreadState* const pThreadState, const unsigned int unGeneration) noexcept {
		constexpr unsigned int kReleasedLeaseCount = 1;

		if (!pThreadState || !unGeneration || (pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration)) {
			return;
		}

		unsigned int unActiveLeases = pThreadState->m_unActiveLeases.load(std::memory_order_acquire);
		for (;;) {
			if (unActiveLeases == 0) {
				return;
			}

			if (pThreadState->m_unActiveLeases.compare_exchange_weak(unActiveLeases, unActiveLeases - kReleasedLeaseCount, std::memory_order_acq_rel, std::memory_order_acquire)) {
				break;
			}
		}

		if (unActiveLeases == kReleasedLeaseCount) {
			RetireIdleWindowsMemoryHookThreadState(pThreadState, unGeneration);
		}
	}

	static WindowsMemoryHookThreadState* PinCurrentWindowsMemoryHookThreadState(WindowsHookProcessState* const pProcessState, const DWORD unThreadID, unsigned int* const pGenerationOut) noexcept {
		constexpr unsigned int kPinnedLeaseCount = 1;

		if (!pProcessState || !unThreadID || !pGenerationOut) {
			return nullptr;
		}

		for (auto& ThreadState : pProcessState->m_arrMemoryHookThreadStates) {
			if ((GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire)) != WindowsThreadStateSlotStatus::ACTIVE) ||
				(ThreadState.m_unThreadID.load(std::memory_order_acquire) != unThreadID)) {
				continue;
			}

			const unsigned int unGeneration = ThreadState.m_unGeneration.load(std::memory_order_acquire);
			if (!unGeneration) {
				continue;
			}

			if (!PinWindowsThreadStateSlot(ThreadState.m_unSlotState)) {
				continue;
			}

			unsigned int unActiveLeases = ThreadState.m_unActiveLeases.load(std::memory_order_acquire);
			bool bPinned = false;
			while (unActiveLeases != std::numeric_limits<unsigned int>::max()) {
				if (ThreadState.m_unActiveLeases.compare_exchange_weak(unActiveLeases, unActiveLeases + kPinnedLeaseCount, std::memory_order_acq_rel, std::memory_order_acquire)) {
					bPinned = true;
					break;
				}
			}

			if ((bPinned) &&
				(GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire)) == WindowsThreadStateSlotStatus::ACTIVE) &&
				(ThreadState.m_unThreadID.load(std::memory_order_acquire) == unThreadID) &&
				(ThreadState.m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
				(GetWindowsThreadLiveness(ThreadState.m_hThread.load(std::memory_order_acquire)) == WindowsThreadLiveness::LIVE)) {
				*pGenerationOut = unGeneration;
				UnpinWindowsThreadStateSlot(ThreadState.m_unSlotState);

				return &ThreadState;
			}

			if (bPinned) {
				ThreadState.m_unActiveLeases.fetch_sub(kPinnedLeaseCount, std::memory_order_release);
			}

			UnpinWindowsThreadStateSlot(ThreadState.m_unSlotState);
		}

		return nullptr;
	}

	static WindowsMemoryHookThreadState* AcquireCurrentWindowsMemoryHookThreadState(const bool bCreate, unsigned int* const pGenerationOut) noexcept {
		constexpr unsigned int kInitialActiveLeaseCount = 1;

		if (!pGenerationOut) {
			return nullptr;
		}

		*pGenerationOut = 0;

		auto* const pProcessState = bCreate ? EnsureHookProcessState() : GetHookProcessState();
		const DWORD unThreadID = GetCurrentWindowsThreadStateReaperThreadID();
		if (!pProcessState || !unThreadID) {
			return nullptr;
		}

		auto* pThreadState = PinCurrentWindowsMemoryHookThreadState(pProcessState, unThreadID, pGenerationOut);
		if (pThreadState || !bCreate) {
			return pThreadState;
		}

		if (HasBlockingWindowsThreadStateIdentity(pProcessState->m_arrMemoryHookThreadStates, unThreadID)) {
			return nullptr;
		}

		auto CloseThreadHandle = [](HANDLE const hThread) noexcept -> void {
			if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
				// Local ownership cleanup cannot propagate CloseHandle failure.
				CloseHandle(hThread);
			}
		};

		std::unique_ptr<void, decltype(CloseThreadHandle)> pThreadHandle(DuplicateCurrentWindowsThreadHandle(), CloseThreadHandle);
		if (!pThreadHandle) {
			return nullptr;
		}

		pThreadState = PinCurrentWindowsMemoryHookThreadState(pProcessState, unThreadID, pGenerationOut);
		if (pThreadState) {
			return pThreadState;
		}

		if (HasBlockingWindowsThreadStateIdentity(pProcessState->m_arrMemoryHookThreadStates, unThreadID)) {
			return nullptr;
		}

		for (auto& ThreadState : pProcessState->m_arrMemoryHookThreadStates) {
			if (GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire)) != WindowsThreadStateSlotStatus::FREE) {
				continue;
			}

			HANDLE hExpectedThread = nullptr;
			if (!ThreadState.m_hThread.compare_exchange_strong(hExpectedThread, pThreadHandle.get(), std::memory_order_acq_rel, std::memory_order_acquire)) {
				continue;
			}

			HANDLE const hPublishedThread = pThreadHandle.release();

			unsigned int unExpectedSlotState = static_cast<unsigned int>(WindowsThreadStateSlotStatus::FREE);
			if (!ThreadState.m_unSlotState.compare_exchange_strong(unExpectedSlotState, static_cast<unsigned int>(WindowsThreadStateSlotStatus::INITIALIZING), std::memory_order_acq_rel, std::memory_order_acquire)) {
				return nullptr;
			}

			if (ThreadState.m_hThread.load(std::memory_order_acquire) != hPublishedThread) {
				// A concurrent replacement owns subsequent recovery, so this rollback is best-effort.
				TransitionWindowsThreadStateSlot(ThreadState.m_unSlotState, WindowsThreadStateSlotStatus::INITIALIZING, WindowsThreadStateSlotStatus::FREE);
				return nullptr;
			}

			ClearWindowsMemoryHookThreadStatePayload(&ThreadState);
			const unsigned int unGeneration = AdvanceWindowsThreadStateGeneration(ThreadState.m_unGeneration);
			ThreadState.m_unThreadID.store(unThreadID, std::memory_order_release);
			ThreadState.m_unActiveLeases.store(kInitialActiveLeaseCount, std::memory_order_relaxed);
			ThreadState.m_bRecoveryPending.store(false, std::memory_order_relaxed);
			if (HasBlockingWindowsThreadStateIdentity(pProcessState->m_arrMemoryHookThreadStates, unThreadID, &ThreadState)) {
				AbandonInitializingWindowsMemoryHookThreadState(&ThreadState, unThreadID, unGeneration, hPublishedThread);
				return nullptr;
			}

			if (!TransitionWindowsThreadStateSlot(ThreadState.m_unSlotState, WindowsThreadStateSlotStatus::INITIALIZING, WindowsThreadStateSlotStatus::ACTIVE)) {
				AbandonInitializingWindowsMemoryHookThreadState(&ThreadState, unThreadID, unGeneration, hPublishedThread);
				return nullptr;
			}

			*pGenerationOut = unGeneration;
			return &ThreadState;
		}

		return nullptr;
	}

	static bool RecoverAbandonedWindowsThreadStateReaperControl(const unsigned long long unOwnerToken) noexcept {
		if (!unOwnerToken) {
			return true;
		}

		auto ReleaseControlOwner = [unOwnerToken]() noexcept -> bool {
			unsigned long long unExpectedOwnerToken = unOwnerToken;
			return g_unWindowsThreadStateReaperControlOwnerToken.compare_exchange_strong(unExpectedOwnerToken, 0, std::memory_order_acq_rel, std::memory_order_acquire) || (unExpectedOwnerToken == 0);
		};

		unsigned int unGeneration = 0;
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, &unGeneration);
		if (!pThreadState) {
			return ReleaseControlOwner();
		}

		WindowsThreadStateSlotStatus Status = GetWindowsThreadStateSlotStatus(pThreadState->m_unSlotState.load(std::memory_order_acquire));
		if ((Status == WindowsThreadStateSlotStatus::FREE) || (pThreadState->m_unGeneration.load(std::memory_order_acquire) != unGeneration)) {
			return ReleaseControlOwner();
		}

		if (!PinWindowsThreadStateSlotForRecovery(pThreadState->m_unSlotState, &Status)) {
			return false;
		}

		HANDLE const hThread = pThreadState->m_hThread.load(std::memory_order_acquire);
		const DWORD unThreadID = pThreadState->m_unThreadID.load(std::memory_order_acquire);
		const WindowsThreadLiveness Liveness = GetWindowsThreadLiveness(hThread);
		const bool bIdentityMatches =
			(pThreadState->m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
			(pThreadState->m_hThread.load(std::memory_order_acquire) == hThread) &&
			(pThreadState->m_unThreadID.load(std::memory_order_acquire) == unThreadID) &&
			(GetWindowsThreadStateSlotStatus(pThreadState->m_unSlotState.load(std::memory_order_acquire)) == Status);
		const bool bRecoverable = bIdentityMatches && (Liveness == WindowsThreadLiveness::TERMINATED);
		if (bRecoverable) {
			pThreadState->m_bRecoveryPending.store(true, std::memory_order_release);
		}

		UnpinWindowsThreadStateSlot(pThreadState->m_unSlotState);

		if (!bRecoverable) {
			return false;
		}

		return ReleaseControlOwner();
	}

	class WindowsThreadStateReaperControlLease final {
	public:
		WindowsThreadStateReaperControlLease() noexcept;
		~WindowsThreadStateReaperControlLease() noexcept;

	public:
		WindowsThreadStateReaperControlLease(WindowsThreadStateReaperControlLease const&) = delete;
		WindowsThreadStateReaperControlLease& operator=(WindowsThreadStateReaperControlLease const&) = delete;
		WindowsThreadStateReaperControlLease(WindowsThreadStateReaperControlLease&&) = delete;
		WindowsThreadStateReaperControlLease& operator=(WindowsThreadStateReaperControlLease&&) = delete;

	public:
		void Release() noexcept;

	public:
		bool IsOwned() const noexcept;

	private:
		WindowsMemoryHookThreadState* m_pThreadState;
		unsigned int m_unGeneration;
		unsigned long long m_unOwnerToken;
		bool m_bOwned;
	};

	void WindowsThreadStateReaperControlLease::Release() noexcept {
		if (m_bOwned) {
			unsigned long long unExpectedOwnerToken = m_unOwnerToken;
			// Clear the global owner only while this lease still owns it.
			g_unWindowsThreadStateReaperControlOwnerToken.compare_exchange_strong(unExpectedOwnerToken, 0, std::memory_order_release, std::memory_order_relaxed);
			m_bOwned = false;
		}

		if (m_pThreadState) {
			ReleaseWindowsMemoryHookThreadState(m_pThreadState, m_unGeneration);
			m_pThreadState = nullptr;
		}

		m_unGeneration = 0;
		m_unOwnerToken = 0;
	}

	WindowsThreadStateReaperControlLease::WindowsThreadStateReaperControlLease() noexcept {
		m_pThreadState = nullptr;
		m_unGeneration = 0;
		m_unOwnerToken = 0;
		m_bOwned = false;

		m_pThreadState = AcquireCurrentWindowsMemoryHookThreadState(true, &m_unGeneration);
		m_unOwnerToken = GetWindowsThreadStateOwnerToken(m_pThreadState, m_unGeneration);
		if (!m_unOwnerToken) {
			Release();
			return;
		}

		unsigned long long unObservedOwnerToken = 0;
		std::size_t unStallSpinCount = 0;
		while (unStallSpinCount < kWindowsThreadStateReaperControlStallSpinCount) {
			unsigned long long unExpectedOwnerToken = 0;
			if (g_unWindowsThreadStateReaperControlOwnerToken.compare_exchange_strong(unExpectedOwnerToken, m_unOwnerToken, std::memory_order_acq_rel, std::memory_order_acquire)) {
				m_bOwned = true;
				return;
			}

			if (unExpectedOwnerToken == m_unOwnerToken) {
				break;
			}

			if (unExpectedOwnerToken != unObservedOwnerToken) {
				unObservedOwnerToken = unExpectedOwnerToken;
				unStallSpinCount = 0;
			}

			if (((unStallSpinCount % kWindowsThreadStateReaperControlProbeInterval) == 0) && RecoverAbandonedWindowsThreadStateReaperControl(unExpectedOwnerToken)) {
				unObservedOwnerToken = 0;
				unStallSpinCount = 0;
				continue;
			}

			++unStallSpinCount;
			_mm_pause();
		}

		Release();
	}

	WindowsThreadStateReaperControlLease::~WindowsThreadStateReaperControlLease() noexcept {
		Release();
	}

	bool WindowsThreadStateReaperControlLease::IsOwned() const noexcept {
		return m_bOwned;
	}

	static bool HasWindowsThreadStateReaperPauseRequests() noexcept {
		auto* const pProcessState = GetHookProcessState();
		if (!pProcessState) {
			return false;
		}

		const DWORD unCurrentThreadID = GetCurrentWindowsThreadStateReaperThreadID();
		const DWORD unReaperThreadID = g_unWindowsThreadStateReaperThreadID.load(std::memory_order_acquire);
		const WindowsThreadStateReaperStatus ReaperStatus = g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire);
		const bool bCanRecover = ((unCurrentThreadID != 0) && (unCurrentThreadID == unReaperThreadID)) || (ReaperStatus == WindowsThreadStateReaperStatus::STOPPED);

		auto IsTerminatedThreadStateIdentityStable = [](WindowsMemoryHookThreadState& ThreadState, const WindowsThreadStateSlotStatus ExpectedStatus) noexcept -> bool {
			HANDLE const hThread = ThreadState.m_hThread.load(std::memory_order_acquire);
			const unsigned int unGeneration = ThreadState.m_unGeneration.load(std::memory_order_acquire);
			const DWORD unThreadID = ThreadState.m_unThreadID.load(std::memory_order_acquire);
			const WindowsThreadLiveness Liveness = GetWindowsThreadLiveness(hThread);

			return (ThreadState.m_hThread.load(std::memory_order_acquire) == hThread) &&
				(ThreadState.m_unGeneration.load(std::memory_order_acquire) == unGeneration) &&
				(ThreadState.m_unThreadID.load(std::memory_order_acquire) == unThreadID) &&
				(GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire)) == ExpectedStatus) &&
				(Liveness == WindowsThreadLiveness::TERMINATED);
		};

		bool bHasPauseRequests = false;
		for (auto& ThreadState : pProcessState->m_arrMemoryHookThreadStates) {
			if (ThreadState.m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire) == 0) {
				continue;
			}

			WindowsThreadStateSlotStatus Status = GetWindowsThreadStateSlotStatus(ThreadState.m_unSlotState.load(std::memory_order_acquire));
			if (Status == WindowsThreadStateSlotStatus::RECOVERING) {
				const bool bIdentityStable = IsTerminatedThreadStateIdentityStable(ThreadState, WindowsThreadStateSlotStatus::RECOVERING);
				if ((!bIdentityStable) || (!bCanRecover) || (!Exception::RecoverWindowsMemoryHookThreadState(&ThreadState))) {
					bHasPauseRequests = true;
				}

				continue;
			}

			if (!PinWindowsThreadStateSlotForRecovery(ThreadState.m_unSlotState, &Status)) {
				bHasPauseRequests = true;
				continue;
			}

			const bool bIdentityStable = IsTerminatedThreadStateIdentityStable(ThreadState, Status);
			UnpinWindowsThreadStateSlot(ThreadState.m_unSlotState);

			if ((!bIdentityStable) || (!bCanRecover) || (!Exception::RecoverWindowsMemoryHookThreadState(&ThreadState))) {
				bHasPauseRequests = true;
			}
		}

		return bHasPauseRequests;
	}

	static bool StartWindowsThreadStateReaper(LPTHREAD_START_ROUTINE const fnStartAddress) noexcept {
		constexpr unsigned int kCounterIncrement = 1;

		if (g_unWindowsThreadStateReaperThreadID.load(std::memory_order_acquire) == GetCurrentWindowsThreadStateReaperThreadID()) {
			return g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire) == WindowsThreadStateReaperStatus::RUNNING;
		}

		WindowsThreadStateReaperControlLease ControlLease;
		if (!ControlLease.IsOwned()) {
			return false;
		}

		if (fnStartAddress) {
			g_fnWindowsThreadStateReaperStartAddress = fnStartAddress;
			g_bWindowsThreadStateReaperConfigured.store(true, std::memory_order_release);
		}

		if (g_hWindowsThreadStateReaper) {
			const WindowsThreadStateReaperStatus CurrentStatus = g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire);
			const unsigned int unRunGeneration = g_unWindowsThreadStateReaperRunGeneration.load(std::memory_order_acquire);
			DWORD unWaitResult = WaitForSingleObject(g_hWindowsThreadStateReaper, 0);
			if ((CurrentStatus == WindowsThreadStateReaperStatus::STOPPING) &&
				(unWaitResult == WAIT_TIMEOUT)) {
				if ((ResumeThread(g_hWindowsThreadStateReaper) == kWindowsInvalidThreadSuspendCount) ||
					!SetEvent(g_hWindowsThreadStateReaperEvent)) {
					return false;
				}

				unWaitResult = WaitForSingleObject(g_hWindowsThreadStateReaper, kWindowsThreadStateReaperStopWaitMilliseconds);
			}

			if ((CurrentStatus == WindowsThreadStateReaperStatus::STARTING) &&
				(unWaitResult == WAIT_TIMEOUT) &&
				(ResumeThread(g_hWindowsThreadStateReaper) == kWindowsInvalidThreadSuspendCount)) {
				return false;
			}

			if (((CurrentStatus == WindowsThreadStateReaperStatus::STARTING) ||
				(CurrentStatus == WindowsThreadStateReaperStatus::RUNNING)) &&
				(unWaitResult == WAIT_TIMEOUT)) {
				return true;
			}

			if (!unRunGeneration || (unWaitResult != WAIT_OBJECT_0)) {
				return false;
			}

			g_unWindowsThreadStateReaperExitAcknowledgement.store(unRunGeneration, std::memory_order_release);

			HANDLE const hRetiredThread = g_hWindowsThreadStateReaper;
			g_unWindowsThreadStateReaperThreadID.store(0, std::memory_order_release);
			g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STOPPED, std::memory_order_release);
			if (!CloseHandle(hRetiredThread)) {
				return false;
			}

			g_hWindowsThreadStateReaper = nullptr;
			ControlLease.Release();

			return StartWindowsThreadStateReaper(nullptr);
		}

		if (g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire) == WindowsThreadStateReaperStatus::STOPPING) {
			g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STOPPED, std::memory_order_release);
		}

		if (HasWindowsThreadStateReaperPauseRequests() || !g_fnWindowsThreadStateReaperStartAddress) {
			return false;
		}

		g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STARTING, std::memory_order_release);

		if (!g_hWindowsThreadStateReaperEvent) {
			g_hWindowsThreadStateReaperEvent = CreateEventW(nullptr, FALSE, FALSE, nullptr);
			if (!g_hWindowsThreadStateReaperEvent) {
				g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STOPPED, std::memory_order_release);
				return false;
			}
		}

		unsigned int unRunGeneration = g_unWindowsThreadStateReaperRunGeneration.fetch_add(kCounterIncrement, std::memory_order_acq_rel) + kCounterIncrement;
		if (!unRunGeneration) {
			unRunGeneration = g_unWindowsThreadStateReaperRunGeneration.fetch_add(kCounterIncrement, std::memory_order_acq_rel) + kCounterIncrement;
		}

		g_unWindowsThreadStateReaperExitAcknowledgement.store(0, std::memory_order_release);
		HANDLE const hThread = CreateThread(nullptr, 0, g_fnWindowsThreadStateReaperStartAddress, nullptr, CREATE_SUSPENDED, nullptr);
		if (!hThread) {
			g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STOPPED, std::memory_order_release);
			return false;
		}

		g_hWindowsThreadStateReaper = hThread;
		g_unWindowsThreadStateReaperStartCount.fetch_add(kCounterIncrement, std::memory_order_acq_rel);
		if (ResumeThread(hThread) != kWindowsInvalidThreadSuspendCount) {
			return true;
		}

		g_hWindowsThreadStateReaper = nullptr;
		g_WindowsThreadStateReaperStatus.store(WindowsThreadStateReaperStatus::STOPPED, std::memory_order_release);
		// The thread handle is no longer published; cleanup failure cannot make
		// the failed reaper start usable.
		CloseHandle(hThread);
		return false;
	}

	static bool PrepareWindowsThreadStateReaperForSuspend() noexcept {
		if (g_unWindowsThreadStateReaperThreadID.load(std::memory_order_acquire) == GetCurrentWindowsThreadStateReaperThreadID()) {
			return false;
		}

		if (!Exception::EnsureWindowsThreadStateReaper()) {
			return false;
		}

		const WindowsThreadStateReaperStatus Status = g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire);
		return (Status == WindowsThreadStateReaperStatus::STARTING) || (Status == WindowsThreadStateReaperStatus::RUNNING);
	}

	static bool ReleaseWindowsThreadStateReaperPause(const unsigned long long unRequestedOwnerToken) noexcept {
		constexpr unsigned long long kCurrentThreadOwnerToken = 0;
		constexpr unsigned int kReleasedPauseDepth = 1;

		unsigned long long unOwnerToken = unRequestedOwnerToken;
		WindowsMemoryHookThreadState* pLeaseThreadState = nullptr;
		unsigned int unLeaseGeneration = 0;
		if (unOwnerToken == kCurrentThreadOwnerToken) {
			pLeaseThreadState = AcquireCurrentWindowsMemoryHookThreadState(false, &unLeaseGeneration);
			unOwnerToken = GetWindowsThreadStateOwnerToken(pLeaseThreadState, unLeaseGeneration);
			if (!unOwnerToken) {
				if (pLeaseThreadState) {
					ReleaseWindowsMemoryHookThreadState(pLeaseThreadState, unLeaseGeneration);
				}

				return false;
			}
		}

		unsigned int unGeneration = 0;
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, &unGeneration);
		if (!pThreadState || !PinWindowsThreadStateSlot(pThreadState->m_unSlotState)) {
			if (pLeaseThreadState) {
				ReleaseWindowsMemoryHookThreadState(pLeaseThreadState, unLeaseGeneration);
			}

			return false;
		}

		unsigned int unPauseDepth = pThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire);
		bool bReleased = false;
		while (unPauseDepth != 0) {
			if (pThreadState->m_unThreadStateReaperPauseDepth.compare_exchange_weak(unPauseDepth, unPauseDepth - kReleasedPauseDepth, std::memory_order_acq_rel, std::memory_order_acquire)) {
				bReleased = true;
				break;
			}
		}

		UnpinWindowsThreadStateSlot(pThreadState->m_unSlotState);

		if (bReleased) {
			AdvanceWindowsThreadStateGeneration(g_unWindowsThreadStateReaperPauseGeneration);
		}

		if (pLeaseThreadState) {
			ReleaseWindowsMemoryHookThreadState(pLeaseThreadState, unLeaseGeneration);

		} else if (bReleased) {
			RetireIdleWindowsMemoryHookThreadState(pThreadState, unGeneration);
		}

		return bReleased;
	}

	static bool IsWindowsThreadStateReaperPauseAcknowledged(const unsigned long long unOwnerToken) noexcept {
		auto* const pThreadState = GetWindowsThreadStateFromOwnerToken(unOwnerToken, nullptr);
		if (!pThreadState || (pThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire) == 0)) {
			return false;
		}

		const unsigned int unPauseGeneration = g_unWindowsThreadStateReaperPauseGeneration.load(std::memory_order_acquire);
		return g_unWindowsThreadStateReaperPauseAcknowledgement.load(std::memory_order_acquire) == unPauseGeneration;
	}

	static bool RequestWindowsThreadStateReaperPause(unsigned long long* const pOwnerTokenOut) noexcept {
		constexpr unsigned int kRequestedPauseDepth = 1;

		if (pOwnerTokenOut) {
			*pOwnerTokenOut = 0;
		}

		if (g_unWindowsThreadStateReaperThreadID.load(std::memory_order_acquire) == GetCurrentWindowsThreadStateReaperThreadID()) {
			return false;
		}

		WindowsThreadStateReaperControlLease ControlLease;
		if (!ControlLease.IsOwned()) {
			return false;
		}

		unsigned int unGeneration = 0;
		auto* const pThreadState = AcquireCurrentWindowsMemoryHookThreadState(true, &unGeneration);
		const unsigned long long unOwnerToken = GetWindowsThreadStateOwnerToken(pThreadState, unGeneration);
		if (!pThreadState || !unOwnerToken) {
			if (pThreadState) {
				ReleaseWindowsMemoryHookThreadState(pThreadState, unGeneration);
			}

			return false;
		}

		unsigned int unPauseDepth = pThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire);
		for (;;) {
			if (unPauseDepth == std::numeric_limits<unsigned int>::max()) {
				ReleaseWindowsMemoryHookThreadState(pThreadState, unGeneration);
				return false;
			}

			if (pThreadState->m_unThreadStateReaperPauseDepth.compare_exchange_weak(unPauseDepth, unPauseDepth + kRequestedPauseDepth, std::memory_order_acq_rel, std::memory_order_acquire)) {
				break;
			}
		}

		ReleaseWindowsMemoryHookThreadState(pThreadState, unGeneration);

		AdvanceWindowsThreadStateGeneration(g_unWindowsThreadStateReaperPauseGeneration);

		const WindowsThreadStateReaperStatus Status = g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire);
		if (Status == WindowsThreadStateReaperStatus::STOPPED) {
			if (!g_bWindowsThreadStateReaperConfigured.load(std::memory_order_acquire)) {
				if (pOwnerTokenOut) {
					*pOwnerTokenOut = unOwnerToken;
				}

				return true;
			}

			ReleaseWindowsThreadStateReaperPause(unOwnerToken);
			return false;
		}

		if (Status == WindowsThreadStateReaperStatus::STOPPING) {
			ReleaseWindowsThreadStateReaperPause(unOwnerToken);
			return false;
		}

		unsigned int unProgressCount = g_unWindowsThreadStateReaperProgressCount.load(std::memory_order_acquire);
		std::size_t unStallSpinCount = 0;
		while (unStallSpinCount < kWindowsThreadStateReaperPauseStallSpinCount) {
			if (IsWindowsThreadStateReaperPauseAcknowledged(unOwnerToken)) {
				if (pOwnerTokenOut) {
					*pOwnerTokenOut = unOwnerToken;
				}

				return true;
			}

			const WindowsThreadStateReaperStatus CurrentStatus = g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire);
			if ((CurrentStatus == WindowsThreadStateReaperStatus::STOPPED) || (CurrentStatus == WindowsThreadStateReaperStatus::STOPPING)) {
				break;
			}

			const unsigned int unCurrentProgressCount = g_unWindowsThreadStateReaperProgressCount.load(std::memory_order_acquire);
			if (unCurrentProgressCount != unProgressCount) {
				unProgressCount = unCurrentProgressCount;
				unStallSpinCount = 0;

			} else {
				++unStallSpinCount;
			}

			_mm_pause();
		}

		if (IsWindowsThreadStateReaperPauseAcknowledged(unOwnerToken)) {
			if (pOwnerTokenOut) {
				*pOwnerTokenOut = unOwnerToken;
			}

			return true;
		}

		ReleaseWindowsThreadStateReaperPause(unOwnerToken);
		return false;
	}

	static void ParkWindowsThreadStateReaper() noexcept {
		constexpr unsigned int kAcknowledgementCountIncrement = 1;
		constexpr unsigned int kNoAcknowledgedPauseGeneration = 0;

		while (g_WindowsThreadStateReaperStatus.load(std::memory_order_acquire) != WindowsThreadStateReaperStatus::STOPPING) {
			if (!HasWindowsThreadStateReaperPauseRequests()) {
				g_unWindowsThreadStateReaperPauseAcknowledgement.store(kNoAcknowledgedPauseGeneration, std::memory_order_release);
				return;
			}

			const unsigned int unPauseGeneration = g_unWindowsThreadStateReaperPauseGeneration.load(std::memory_order_acquire);
			if (g_unWindowsThreadStateReaperPauseAcknowledgement.load(std::memory_order_relaxed) != unPauseGeneration) {
				g_unWindowsThreadStateReaperPauseAcknowledgement.store(unPauseGeneration, std::memory_order_release);
				g_unWindowsThreadStateReaperAcknowledgementCount.fetch_add(kAcknowledgementCountIncrement, std::memory_order_acq_rel);
			}

			_mm_pause();
		}
	}

	static unsigned long long GetWindowsMemoryHookEntryToken(WindowsMemoryHookThreadState const* const pThreadState, const unsigned int unGeneration, const std::size_t unEntryIndex) noexcept {
		constexpr unsigned int kSlotShift = kWindowsMemoryHookEntryTokenIndexBitCount;
		constexpr unsigned int kGenerationShift = kSlotShift + kWindowsMemoryHookEntryTokenSlotBitCount;
		constexpr std::size_t kThreadStateSlotSize = sizeof(WindowsMemoryHookThreadState);
		constexpr unsigned long long kTokenFieldBias = 1;

		static_assert(kGenerationShift < std::numeric_limits<unsigned long long>::digits, "memory-hook entry-token generation shift exceeds its representation");

		auto* const pProcessState = GetHookProcessState();
		if (!pProcessState || !pThreadState || !unGeneration || (unEntryIndex >= kMemoryHookRecordCapacity)) {
			return 0;
		}

		const std::uintptr_t unThreadStateAddress = reinterpret_cast<std::uintptr_t>(pThreadState);
		const std::uintptr_t unThreadStateArrayAddress = reinterpret_cast<std::uintptr_t>(&pProcessState->m_arrMemoryHookThreadStates[0]);
		if (unThreadStateAddress < unThreadStateArrayAddress) {
			return 0;
		}

		const std::uintptr_t unThreadStateOffset = unThreadStateAddress - unThreadStateArrayAddress;
		const std::uintptr_t unSlotIndexValue = unThreadStateOffset / kThreadStateSlotSize;
		if (((unThreadStateOffset % kThreadStateSlotSize) != 0) || (unSlotIndexValue >= kWindowsThreadStateSlotCapacity)) {
			return 0;
		}

		const std::size_t unSlotIndex = static_cast<std::size_t>(unSlotIndexValue);
		const unsigned long long unGenerationToken = static_cast<unsigned long long>(unGeneration) << kGenerationShift;
		const unsigned long long unSlotToken = (static_cast<unsigned long long>(unSlotIndex) + kTokenFieldBias) << kSlotShift;
		const unsigned long long unEntryToken = static_cast<unsigned long long>(unEntryIndex) + kTokenFieldBias;

		return unGenerationToken | unSlotToken | unEntryToken;
	}

	static WindowsProtectedMemoryRegistryLockFrame* PrepareWindowsProtectedMemoryRegistryLockFrame(WindowsMemoryHookThreadState* const pThreadState, const unsigned int unGeneration) noexcept {
		if (!pThreadState || !unGeneration || pThreadState->m_bRecoveryPending.load(std::memory_order_acquire)) {
			return nullptr;
		}

		const unsigned long long unOwnerToken = GetWindowsThreadStateOwnerToken(pThreadState, unGeneration);
		if (!unOwnerToken) {
			return nullptr;
		}

		WindowsProtectedMemoryRegistryLockFrame& Frame = pThreadState->m_ProtectedMemoryRegistryLockFrame;
		WindowsProtectedMemoryRegistryLockFrameState ExpectedState = WindowsProtectedMemoryRegistryLockFrameState::FREE;
		if (!Frame.m_State.compare_exchange_strong(ExpectedState, WindowsProtectedMemoryRegistryLockFrameState::PREPARING, std::memory_order_acq_rel, std::memory_order_acquire)) {
			return nullptr;
		}

		Frame.m_unOwnerToken = unOwnerToken;
		Frame.m_unThreadStateGeneration = unGeneration;
		Frame.m_RecoverySourceState = WindowsProtectedMemoryRegistryLockFrameState::FREE;
		Frame.m_State.store(WindowsProtectedMemoryRegistryLockFrameState::PUBLISHED, std::memory_order_release);

		return &Frame;
	}

	static WindowsProtectedMemoryStateLockFrame* PrepareWindowsProtectedMemoryStateLockFrame(WindowsMemoryHookThreadState* const pThreadState, const unsigned int unGeneration, void const* const pState, const WindowsProtectedMemoryStateLockPurpose Purpose, MemoryHookPostContext* const pJournal) noexcept {
		constexpr unsigned int kInitialLockDepth = 1;

		if (!pThreadState || !unGeneration || !pState || pThreadState->m_bRecoveryPending.load(std::memory_order_acquire)) {
			return nullptr;
		}

		const unsigned long long unOwnerToken = GetWindowsThreadStateOwnerToken(pThreadState, unGeneration);
		if (!unOwnerToken) {
			return nullptr;
		}

		for (auto& Frame : pThreadState->m_arrProtectedMemoryStateLockFrames) {
			WindowsProtectedMemoryStateLockFrameState ExpectedState = WindowsProtectedMemoryStateLockFrameState::FREE;
			if (!Frame.m_State.compare_exchange_strong(ExpectedState, WindowsProtectedMemoryStateLockFrameState::PREPARING, std::memory_order_acq_rel, std::memory_order_acquire)) {
				continue;
			}

			Frame.m_pState = pState;
			Frame.m_pJournal = pJournal;
			Frame.m_unOwnerToken = unOwnerToken;
			Frame.m_unThreadStateGeneration = unGeneration;
			Frame.m_unDepth.store(kInitialLockDepth, std::memory_order_relaxed);
			Frame.m_Purpose = Purpose;
			Frame.m_State.store(WindowsProtectedMemoryStateLockFrameState::PUBLISHED, std::memory_order_release);

			return &Frame;
		}

		return nullptr;
	}

	class WindowsMemoryHookThreadStateLease final {
	public:
		explicit WindowsMemoryHookThreadStateLease(const bool bCreate) noexcept;
		~WindowsMemoryHookThreadStateLease() noexcept;

	public:
		WindowsMemoryHookThreadStateLease(WindowsMemoryHookThreadStateLease const&) = delete;
		WindowsMemoryHookThreadStateLease& operator=(WindowsMemoryHookThreadStateLease const&) = delete;
		WindowsMemoryHookThreadStateLease(WindowsMemoryHookThreadStateLease&&) = delete;
		WindowsMemoryHookThreadStateLease& operator=(WindowsMemoryHookThreadStateLease&&) = delete;

	public:
		void Release() noexcept;

	public:
		WindowsMemoryHookThreadState* GetState() const noexcept;
		unsigned int GetGeneration() const noexcept;
		unsigned long long GetOwnerToken() const noexcept;

	private:
		WindowsMemoryHookThreadState* m_pThreadState;
		unsigned int m_unGeneration;
	};

	WindowsMemoryHookThreadStateLease::WindowsMemoryHookThreadStateLease(const bool bCreate) noexcept {
		m_pThreadState = nullptr;
		m_unGeneration = 0;

		m_pThreadState = AcquireCurrentWindowsMemoryHookThreadState(bCreate, &m_unGeneration);
	}

	void WindowsMemoryHookThreadStateLease::Release() noexcept {
		if (m_pThreadState) {
			ReleaseWindowsMemoryHookThreadState(m_pThreadState, m_unGeneration);
			m_pThreadState = nullptr;
		}

		m_unGeneration = 0;
	}

	WindowsMemoryHookThreadStateLease::~WindowsMemoryHookThreadStateLease() noexcept {
		Release();
	}

	WindowsMemoryHookThreadState* WindowsMemoryHookThreadStateLease::GetState() const noexcept {
		return m_pThreadState;
	}

	unsigned int WindowsMemoryHookThreadStateLease::GetGeneration() const noexcept {
		return m_unGeneration;
	}

	unsigned long long WindowsMemoryHookThreadStateLease::GetOwnerToken() const noexcept {
		return GetWindowsThreadStateOwnerToken(m_pThreadState, m_unGeneration);
	}

	static WindowsHardwareOperationFrame* PrepareWindowsHardwareOperationFrame(WindowsMemoryHookThreadState* const pThreadState, const unsigned int unGeneration, const WindowsHardwareOperationType Type, const DWORD unTargetThreadID, const unsigned char unDRIndex) noexcept {
		if ((!pThreadState) ||
			(!unGeneration) ||
			(Type == WindowsHardwareOperationType::NONE) ||
			(unDRIndex >= kHardwareDebugRegisterCount)) {
			return nullptr;
		}

		auto* const pFrame = &pThreadState->m_HardwareOperationFrame;
		WindowsHardwareOperationState ExpectedState = WindowsHardwareOperationState::FREE;
		if (!pFrame->m_State.compare_exchange_strong(ExpectedState, WindowsHardwareOperationState::PREPARING, std::memory_order_acq_rel, std::memory_order_acquire)) {
			return nullptr;
		}

		ClearWindowsHardwareOperationFrame(pFrame);

		const unsigned long long unOwnerToken = GetWindowsThreadStateOwnerToken(pThreadState, unGeneration);
		pFrame->m_Type = Type;
		pFrame->m_unOwnerToken = unOwnerToken;
		pFrame->m_unThreadStateGeneration = unGeneration;
		pFrame->m_unOwnerThreadID = GetCurrentWindowsThreadStateReaperThreadID();
		pFrame->m_unTargetThreadID = unTargetThreadID;
		pFrame->m_unDRIndex = unDRIndex;
		pFrame->m_bCurrentTarget = pFrame->m_unOwnerThreadID == unTargetThreadID;

		bool bOwnerAcquired = false;
		if (unOwnerToken && pFrame->m_unOwnerThreadID) {
			for (std::size_t unSpin = 0; unSpin < kWindowsHardwareOperationStallSpinCount; ++unSpin) {
				unsigned long long unExpectedOwnerToken = 0;
				if (g_unWindowsHardwareOperationOwner.compare_exchange_weak(unExpectedOwnerToken, unOwnerToken, std::memory_order_acq_rel, std::memory_order_acquire)) {
					bOwnerAcquired = true;
					break;
				}

				if (unExpectedOwnerToken == unOwnerToken) {
					break;
				}

				_mm_pause();
			}
		}

		if (!bOwnerAcquired) {
			ClearWindowsHardwareOperationFrame(pFrame);
			pFrame->m_State.store(WindowsHardwareOperationState::FREE, std::memory_order_release);
			return nullptr;
		}

		return pFrame;
	}

	static bool PublishWindowsHardwareOperationFrameLocked(WindowsHardwareOperationFrame* const pFrame, HardwareHookRecord* const pRecord) noexcept {
		if ((!pFrame) ||
			(!pRecord) ||
			(!pFrame->m_unOwnerToken) ||
			(pFrame->m_State.load(std::memory_order_acquire) != WindowsHardwareOperationState::PREPARING)) {
			return false;
		}

		unsigned long long unExpectedOwnerToken = 0;
		if (!pRecord->m_unOperationOwner.compare_exchange_strong(unExpectedOwnerToken, pFrame->m_unOwnerToken, std::memory_order_acq_rel, std::memory_order_acquire)) {
			return false;
		}

		pRecord->m_unPins.fetch_add(1, std::memory_order_acq_rel);
		pFrame->m_pRecord = pRecord;
		pFrame->m_unRecordGeneration = pRecord->m_unGeneration;
		pFrame->m_bRecordPinOwned.store(true, std::memory_order_relaxed);
		pFrame->m_Step.store(WindowsHardwareOperationStep::RECORD_PINNED, std::memory_order_release);
		pFrame->m_State.store(WindowsHardwareOperationState::PUBLISHED, std::memory_order_release);

		return true;
	}

	static void AbandonPreparedWindowsHardwareOperationFrame(WindowsHardwareOperationFrame* const pFrame) noexcept {
		constexpr unsigned long long kNoOwnerToken = 0;

		if (!pFrame) {
			return;
		}

		// A recovery path may already have replaced the owner token; never clear a different owner.
		unsigned long long unExpectedOwnerToken = pFrame->m_unOwnerToken;
		g_unWindowsHardwareOperationOwner.compare_exchange_strong(unExpectedOwnerToken, kNoOwnerToken, std::memory_order_acq_rel, std::memory_order_acquire);

		ClearWindowsHardwareOperationFrame(pFrame);
		pFrame->m_State.store(WindowsHardwareOperationState::FREE, std::memory_order_release);
	}

	static bool IsWindowsMemoryHookHandlerActiveForCurrentThread() noexcept {
		WindowsMemoryHookThreadStateLease ThreadStateLease(false);
		auto* const pThreadState = ThreadStateLease.GetState();
		return pThreadState && (pThreadState->m_unHandlerDepth || pThreadState->m_unCallBackDepth);
	}

	static bool GetHardwareHookRegisterIndex(const HARDWARE_HOOK_REGISTER Register, unsigned char* const pIndexOut) noexcept {
		if (!pIndexOut) {
			return false;
		}

		const unsigned int unRegisterIndex = static_cast<unsigned int>(Register);
		if (unRegisterIndex >= kHardwareDebugRegisterCount) {
			return false;
		}

		*pIndexOut = static_cast<unsigned char>(unRegisterIndex);

		return true;
	}

	static bool GetHardwareHookTypeValue(const HARDWARE_HOOK_TYPE Type, unsigned char* const pValueOut) noexcept {
		constexpr unsigned char kExecuteTypeValue = 0;
		constexpr unsigned char kWriteTypeValue = 1;
		constexpr unsigned char kAccessTypeValue = 3;

		if (!pValueOut) {
			return false;
		}

		switch (Type) {
			case HARDWARE_HOOK_TYPE::TYPE_EXECUTE:
				*pValueOut = kExecuteTypeValue;
				return true;

			case HARDWARE_HOOK_TYPE::TYPE_WRITE:
				*pValueOut = kWriteTypeValue;
				return true;

			case HARDWARE_HOOK_TYPE::TYPE_ACCESS:
				*pValueOut = kAccessTypeValue;
				return true;

			default:
				return false;
		}
	}

	static bool GetHardwareHookSizeValue(const unsigned char unSize, unsigned char* const pValueOut) noexcept {
		constexpr unsigned char kOneByteSize = 1;
		constexpr unsigned char kOneByteValue = 0;
		constexpr unsigned char kTwoByteSize = 2;
		constexpr unsigned char kTwoByteValue = 1;
		constexpr unsigned char kFourByteSize = 4;
		constexpr unsigned char kFourByteValue = 3;
#if defined(DETOURS_ARCH_X64)
		constexpr unsigned char kEightByteSize = 8;
		constexpr unsigned char kEightByteValue = 2;
#endif

		if (!pValueOut) {
			return false;
		}

		switch (unSize) {
			case kOneByteSize:
				*pValueOut = kOneByteValue;
				return true;

			case kTwoByteSize:
				*pValueOut = kTwoByteValue;
				return true;

			case kFourByteSize:
				*pValueOut = kFourByteValue;
				return true;

#if defined(DETOURS_ARCH_X64)
			case kEightByteSize:
				*pValueOut = kEightByteValue;
				return true;
#endif

			default:
				return false;
		}
	}

	static DWORD_PTR GetDebugRegisterEnableMask(const unsigned char unRegisterIndex) noexcept {
		constexpr DWORD_PTR kDebugRegisterEnableMask = 0b11;
		constexpr unsigned int kBitsPerDebugRegister = 2;

		static_assert(kHardwareDebugRegisterCount <= (std::numeric_limits<DWORD_PTR>::digits / kBitsPerDebugRegister), "debug-register enable fields exceed the DR7 width");

		if (unRegisterIndex >= kHardwareDebugRegisterCount) {
			return 0;
		}

		const unsigned int unShift = static_cast<unsigned int>(unRegisterIndex) * kBitsPerDebugRegister;
		return kDebugRegisterEnableMask << unShift;
	}

	static DWORD_PTR GetDebugRegisterLocalEnableMask(const unsigned char unRegisterIndex) noexcept {
		constexpr DWORD_PTR kDebugRegisterLocalEnableMask = 0b01;
		constexpr unsigned int kBitsPerDebugRegister = 2;

		static_assert(kHardwareDebugRegisterCount <= (std::numeric_limits<DWORD_PTR>::digits / kBitsPerDebugRegister), "debug-register enable fields exceed the DR7 width");

		if (unRegisterIndex >= kHardwareDebugRegisterCount) {
			return 0;
		}

		const unsigned int unShift = static_cast<unsigned int>(unRegisterIndex) * kBitsPerDebugRegister;
		return kDebugRegisterLocalEnableMask << unShift;
	}

	static DWORD_PTR GetDebugRegisterControlMask(const unsigned char unRegisterIndex) noexcept {
		constexpr unsigned int kControlFieldOffset = 16;
		constexpr unsigned int kBitsPerDebugRegisterControl = 4;

		static_assert(
			(std::numeric_limits<DWORD_PTR>::digits >= kControlFieldOffset) &&
			(kHardwareDebugRegisterCount <= ((std::numeric_limits<DWORD_PTR>::digits - kControlFieldOffset) / kBitsPerDebugRegisterControl)),
			"debug-register control fields exceed the DR7 width");

		if (unRegisterIndex >= kHardwareDebugRegisterCount) {
			return 0;
		}

		const unsigned int unShift = kControlFieldOffset + static_cast<unsigned int>(unRegisterIndex) * kBitsPerDebugRegisterControl;
		return kDebugRegisterControlFieldMask << unShift;
	}

	static DWORD_PTR GetDebugRegisterSlotMask(const unsigned char unRegisterIndex) noexcept {
		return GetDebugRegisterEnableMask(unRegisterIndex) | GetDebugRegisterControlMask(unRegisterIndex);
	}

	static DWORD_PTR GetHardwareHookDR7Bits(const unsigned char unRegisterIndex, const HARDWARE_HOOK_TYPE Type, const unsigned char unSize) noexcept {
		constexpr unsigned int kSizeValueOffset = 2;
		constexpr unsigned int kControlFieldOffset = 16;
		constexpr unsigned int kBitsPerDebugRegisterControl = 4;

		static_assert(
			(std::numeric_limits<DWORD_PTR>::digits >= kControlFieldOffset) &&
			(kHardwareDebugRegisterCount <= ((std::numeric_limits<DWORD_PTR>::digits - kControlFieldOffset) / kBitsPerDebugRegisterControl)),
			"debug-register control fields exceed the DR7 width");

		unsigned char unTypeValue = 0;
		unsigned char unSizeValue = 0;
		if ((unRegisterIndex >= kHardwareDebugRegisterCount) ||
			(!GetHardwareHookTypeValue(Type, &unTypeValue)) ||
			(!GetHardwareHookSizeValue(unSize, &unSizeValue))) {
			return 0;
		}

		const unsigned int unTypeBits = static_cast<unsigned int>(unTypeValue);
		const unsigned int unSizeBits = static_cast<unsigned int>(unSizeValue) << kSizeValueOffset;
		const DWORD_PTR unControlValue = static_cast<DWORD_PTR>(unTypeBits | unSizeBits);
		const unsigned int unRegisterControlOffset = static_cast<unsigned int>(unRegisterIndex) * kBitsPerDebugRegisterControl;
		const unsigned int unControlShift = kControlFieldOffset + unRegisterControlOffset;
		return GetDebugRegisterLocalEnableMask(unRegisterIndex) | (unControlValue << unControlShift);
	}

	static DWORD_PTR GetDebugRegisterAddress(CONTEXT const& WindowsContext, const unsigned char unRegisterIndex) noexcept {
		constexpr unsigned char kDR0Index = 0;
		constexpr unsigned char kDR1Index = 1;
		constexpr unsigned char kDR2Index = 2;
		constexpr unsigned char kDR3Index = 3;

		static_assert(kHardwareDebugRegisterCount == (static_cast<std::size_t>(kDR3Index) + 1), "debug-register address switch must cover every hardware slot");

		switch (unRegisterIndex) {
			case kDR0Index:
				return static_cast<DWORD_PTR>(WindowsContext.Dr0);

			case kDR1Index:
				return static_cast<DWORD_PTR>(WindowsContext.Dr1);

			case kDR2Index:
				return static_cast<DWORD_PTR>(WindowsContext.Dr2);

			case kDR3Index:
				return static_cast<DWORD_PTR>(WindowsContext.Dr3);

			default:
				return 0;
		}
	}

	static void SetDebugRegisterAddress(CONTEXT* const pWindowsContext, const unsigned char unRegisterIndex, const DWORD_PTR unAddress) noexcept {
		constexpr unsigned char kDR0Index = 0;
		constexpr unsigned char kDR1Index = 1;
		constexpr unsigned char kDR2Index = 2;
		constexpr unsigned char kDR3Index = 3;

		static_assert(kHardwareDebugRegisterCount == (static_cast<std::size_t>(kDR3Index) + 1), "debug-register address switch must cover every hardware slot");

		if (!pWindowsContext) {
			return;
		}

		switch (unRegisterIndex) {
			case kDR0Index:
				pWindowsContext->Dr0 = unAddress;
				return;

			case kDR1Index:
				pWindowsContext->Dr1 = unAddress;
				return;

			case kDR2Index:
				pWindowsContext->Dr2 = unAddress;
				return;

			case kDR3Index:
				pWindowsContext->Dr3 = unAddress;
				return;

			default:
				return;
		}
	}

	static void SetDebugRegisterSlot(CONTEXT* const pWindowsContext, const unsigned char unRegisterIndex, const DWORD_PTR unAddress, const DWORD_PTR unDR7Bits) noexcept {
		if (!pWindowsContext || (unRegisterIndex >= kHardwareDebugRegisterCount)) {
			return;
		}

		SetDebugRegisterAddress(pWindowsContext, unRegisterIndex, unAddress);

		const DWORD_PTR unSlotMask = GetDebugRegisterSlotMask(unRegisterIndex);
		const DWORD_PTR unCurrentDR7 = static_cast<DWORD_PTR>(pWindowsContext->Dr7);
		const DWORD_PTR unClearedDR7 = unCurrentDR7 & ~unSlotMask;
		const DWORD_PTR unSlotBits = unDR7Bits & unSlotMask;
		pWindowsContext->Dr7 = unClearedDR7 | unSlotBits;
	}

	static WindowsHardwareSlotState GetWindowsHardwareOperationSlotState(CONTEXT const& WindowsContext, HardwareHookRecord const* const pRecord, const unsigned char unRegisterIndex) noexcept {
		if (!pRecord || (unRegisterIndex >= kHardwareDebugRegisterCount)) {
			return WindowsHardwareSlotState::UNKNOWN;
		}

		const DWORD_PTR unSlotMask = GetDebugRegisterSlotMask(unRegisterIndex);
		const DWORD_PTR unAddress = GetDebugRegisterAddress(WindowsContext, unRegisterIndex);
		const DWORD_PTR unDR7Bits = static_cast<DWORD_PTR>(WindowsContext.Dr7) & unSlotMask;
		const DWORD_PTR unInstalledDR7Bits = GetHardwareHookDR7Bits(unRegisterIndex, pRecord->m_Type, pRecord->m_unSize) & unSlotMask;

		if ((unAddress == reinterpret_cast<DWORD_PTR>(pRecord->m_pAddress)) &&
			(unDR7Bits == unInstalledDR7Bits)) {
			return WindowsHardwareSlotState::DESIRED;
		}

		if ((unAddress == pRecord->m_unPreviousAddress) &&
			(unDR7Bits == (pRecord->m_unPreviousDR7Bits & unSlotMask))) {
			return WindowsHardwareSlotState::ORIGINAL;
		}

		return WindowsHardwareSlotState::UNKNOWN;
	}

	static bool ResumeWindowsHardwareOperationTarget(WindowsHardwareOperationFrame* const pFrame) noexcept {
		if (!pFrame) {
			return false;
		}

		if ((pFrame->m_bCurrentTarget) ||
			(pFrame->m_unPreviousSuspendCount == kWindowsHardwareOperationSuspendCountUnknown) ||
			(pFrame->m_unPreviousResumeCount != kWindowsHardwareOperationSuspendCountUnknown)) {
			return true;
		}

		if (!pFrame->m_pRecord) {
			return false;
		}

		pFrame->m_Step.store(WindowsHardwareOperationStep::RESUMING_TARGET, std::memory_order_release);
		const DWORD unPreviousResumeCount = ResumeThread(pFrame->m_pRecord->m_hThread);
		pFrame->m_nResumeStatus = unPreviousResumeCount == kWindowsInvalidThreadSuspendCount ? kWindowsNativeCallNotAttempted : 0;
		if (pFrame->m_nResumeStatus >= 0) {
			pFrame->m_unPreviousResumeCount = unPreviousResumeCount;
		}

		if (pFrame->m_nResumeStatus < 0) {
			return false;
		}

		pFrame->m_Step.store(WindowsHardwareOperationStep::TARGET_RESUMED, std::memory_order_release);

		return true;
	}

	static bool ExecuteWindowsHardwareOperationFrame(WindowsHardwareOperationFrame* const pFrame, const bool bForceRestore) noexcept {
		if ((!pFrame) ||
			(!pFrame->m_pRecord) ||
			(pFrame->m_State.load(std::memory_order_acquire) == WindowsHardwareOperationState::FREE)) {
			return false;
		}

		auto* const pRecord = pFrame->m_pRecord;
		pFrame->m_bForceRestore = bForceRestore;

		if (pFrame->m_bCurrentTarget) {
			pFrame->m_Step.store(WindowsHardwareOperationStep::SETTING_CONTEXT, std::memory_order_release);

			WindowsHardwareContextBreakpoint(pFrame);

			pFrame->m_Step.store(WindowsHardwareOperationStep::TARGET_RESUMED, std::memory_order_release);

			return pFrame->m_bContextMutationSucceeded;
		}

		if ((pFrame->m_unPreviousSuspendCount == kWindowsHardwareOperationSuspendCountUnknown) ||
			(pFrame->m_unPreviousResumeCount != kWindowsHardwareOperationSuspendCountUnknown)) {
			pFrame->m_unPreviousSuspendCount = kWindowsHardwareOperationSuspendCountUnknown;
			pFrame->m_unPreviousResumeCount = kWindowsHardwareOperationSuspendCountUnknown;

			pFrame->m_Step.store(WindowsHardwareOperationStep::SUSPENDING_TARGET, std::memory_order_release);

			const DWORD unPreviousSuspendCount = SuspendThread(pRecord->m_hThread);
			pFrame->m_nSuspendStatus = unPreviousSuspendCount == kWindowsInvalidThreadSuspendCount ? kWindowsNativeCallNotAttempted : 0;
			if (pFrame->m_nSuspendStatus >= 0) {
				pFrame->m_unPreviousSuspendCount = unPreviousSuspendCount;
			}

			if (pFrame->m_nSuspendStatus < 0) {
				return false;
			}

			pFrame->m_Step.store(WindowsHardwareOperationStep::TARGET_SUSPENDED, std::memory_order_release);
		}

		pFrame->m_OriginalContext = {};
		pFrame->m_OriginalContext.ContextFlags = CONTEXT_DEBUG_REGISTERS;

		pFrame->m_Step.store(WindowsHardwareOperationStep::READING_CONTEXT, std::memory_order_release);

		pFrame->m_nGetContextStatus = GetThreadContext(pRecord->m_hThread, &pFrame->m_OriginalContext) ? 0 : kWindowsNativeCallNotAttempted;
		if (pFrame->m_nGetContextStatus < 0) {
			// The context read already failed; resuming the target is best-effort cleanup.
			ResumeWindowsHardwareOperationTarget(pFrame);
			return false;
		}

		pFrame->m_DesiredContext = pFrame->m_OriginalContext;
		const bool bInstall = (pFrame->m_Type == WindowsHardwareOperationType::INSTALLING) && !bForceRestore;
		if (bInstall) {
			if ((pRecord->m_State.load(std::memory_order_acquire) != WindowsHardwareRecordState::INSTALLING) ||
				((static_cast<DWORD_PTR>(pFrame->m_OriginalContext.Dr7) & GetDebugRegisterEnableMask(pFrame->m_unDRIndex)) != 0)) {
				pFrame->m_FinalSlotState = WindowsHardwareSlotState::ORIGINAL;
				// The install precondition failed; resuming the target is best-effort cleanup.
				ResumeWindowsHardwareOperationTarget(pFrame);
				return false;
			}

			const DWORD_PTR unSlotMask = GetDebugRegisterSlotMask(pFrame->m_unDRIndex);
			pRecord->m_unPreviousAddress = GetDebugRegisterAddress(pFrame->m_OriginalContext, pFrame->m_unDRIndex);
			pRecord->m_unPreviousDR7Bits = static_cast<DWORD_PTR>(pFrame->m_OriginalContext.Dr7) & unSlotMask;
			pFrame->m_bPreviousSlotCaptured = true;

			const DWORD_PTR unDR7Bits = GetHardwareHookDR7Bits(pFrame->m_unDRIndex, pRecord->m_Type, pRecord->m_unSize);
			SetDebugRegisterSlot(&pFrame->m_DesiredContext, pFrame->m_unDRIndex, reinterpret_cast<DWORD_PTR>(pRecord->m_pAddress), unDR7Bits);
		} else {
			if (!pFrame->m_bPreviousSlotCaptured) {
				pFrame->m_FinalSlotState = WindowsHardwareSlotState::ORIGINAL;
				const bool bResumed = ResumeWindowsHardwareOperationTarget(pFrame);
				pFrame->m_bContextMutationSucceeded = bResumed;

				return bResumed;
			}

			SetDebugRegisterSlot(&pFrame->m_DesiredContext, pFrame->m_unDRIndex, pRecord->m_unPreviousAddress, pRecord->m_unPreviousDR7Bits);
		}

		pFrame->m_Step.store(WindowsHardwareOperationStep::SETTING_CONTEXT, std::memory_order_release);

		pFrame->m_nSetContextStatus = SetThreadContext(pRecord->m_hThread, &pFrame->m_DesiredContext) ? 0 : kWindowsNativeCallNotAttempted;

		pFrame->m_VerificationContext = {};
		pFrame->m_VerificationContext.ContextFlags = CONTEXT_DEBUG_REGISTERS;

		pFrame->m_Step.store(WindowsHardwareOperationStep::VERIFYING_CONTEXT, std::memory_order_release);

		pFrame->m_nVerificationStatus = GetThreadContext(pRecord->m_hThread, &pFrame->m_VerificationContext) ? 0 : kWindowsNativeCallNotAttempted;
		if (pFrame->m_nVerificationStatus >= 0) {
			pFrame->m_FinalSlotState = GetWindowsHardwareOperationSlotState(pFrame->m_VerificationContext, pRecord, pFrame->m_unDRIndex);
		} else {
			pFrame->m_FinalSlotState = WindowsHardwareSlotState::UNKNOWN;
		}

		if (bInstall && (pFrame->m_FinalSlotState != WindowsHardwareSlotState::ORIGINAL)) {
			pFrame->m_bContextMutationSucceeded = pFrame->m_FinalSlotState == WindowsHardwareSlotState::DESIRED;

			return pFrame->m_bContextMutationSucceeded;
		}

		const bool bResumed = ResumeWindowsHardwareOperationTarget(pFrame);
		const WindowsHardwareSlotState ExpectedSlotState = bInstall ? WindowsHardwareSlotState::DESIRED : WindowsHardwareSlotState::ORIGINAL;
		pFrame->m_bContextMutationSucceeded = bResumed && (pFrame->m_FinalSlotState == ExpectedSlotState);

		return pFrame->m_bContextMutationSucceeded;
	}

	static bool HandleWindowsHardwareContextBreakpoint(EXCEPTION_RECORD const* const pExceptionRecord, CONTEXT* const pWindowsContext) noexcept {
		if ((!pExceptionRecord) ||
			(!pWindowsContext) ||
			(pExceptionRecord->ExceptionCode != EXCEPTION_BREAKPOINT) ||
			(pExceptionRecord->ExceptionAddress != GetWindowsHardwareContextBreakpointAddress())) {
			return false;
		}

#if defined(DETOURS_ARCH_X64)
		auto* const pFrame = reinterpret_cast<WindowsHardwareOperationFrame*>(pWindowsContext->Rcx);
#elif defined(DETOURS_ARCH_X86)
		auto* const pFrame = reinterpret_cast<WindowsHardwareOperationFrame*>(pWindowsContext->Eax);
#endif
		auto* const pProcessState = GetHookProcessState();
		const DWORD unThreadID = GetCurrentWindowsThreadStateReaperThreadID();
		if (!pFrame || !pProcessState || !unThreadID) {
			return false;
		}

		WindowsMemoryHookThreadState const* pOwnerThreadState = nullptr;
		for (auto const& ThreadState : pProcessState->m_arrMemoryHookThreadStates) {
			if (&ThreadState.m_HardwareOperationFrame != pFrame) {
				continue;
			}

			pOwnerThreadState = &ThreadState;
			break;
		}

		if ((!pOwnerThreadState) ||
			(!pFrame->m_bCurrentTarget) ||
			(pFrame->m_unOwnerThreadID != unThreadID) ||
			(pFrame->m_unTargetThreadID != unThreadID) ||
			(pFrame->m_State.load(std::memory_order_acquire) != WindowsHardwareOperationState::PUBLISHED) ||
			(pOwnerThreadState->m_unThreadID.load(std::memory_order_acquire) != unThreadID) ||
			(GetWindowsThreadStateSlotStatus(pOwnerThreadState->m_unSlotState.load(std::memory_order_acquire)) != WindowsThreadStateSlotStatus::ACTIVE) ||
			(pOwnerThreadState->m_unGeneration.load(std::memory_order_acquire) != pFrame->m_unThreadStateGeneration)) {
			return false;
		}

		auto* const pRecord = pFrame->m_pRecord;
		if ((!pRecord) ||
			(pRecord->m_unGeneration != pFrame->m_unRecordGeneration) ||
			(pRecord->m_unOperationOwner.load(std::memory_order_acquire) != pFrame->m_unOwnerToken) ||
			(g_unWindowsHardwareOperationOwner.load(std::memory_order_acquire) != pFrame->m_unOwnerToken)) {
			return false;
		}

		pFrame->m_OriginalContext = *pWindowsContext;
		pFrame->m_DesiredContext = *pWindowsContext;
		bool bHandled = false;

		if ((pFrame->m_Type == WindowsHardwareOperationType::INSTALLING) && !pFrame->m_bForceRestore) {
			if ((pRecord->m_State.load(std::memory_order_acquire) != WindowsHardwareRecordState::INSTALLING) ||
				((static_cast<DWORD_PTR>(pWindowsContext->Dr7) & GetDebugRegisterEnableMask(pFrame->m_unDRIndex)) != 0)) {
				pFrame->m_FinalSlotState = WindowsHardwareSlotState::ORIGINAL;
				pFrame->m_bContextMutationSucceeded = false;
				bHandled = true;
			} else {
				const DWORD_PTR unSlotMask = GetDebugRegisterSlotMask(pFrame->m_unDRIndex);
				pRecord->m_unPreviousAddress = GetDebugRegisterAddress(*pWindowsContext, pFrame->m_unDRIndex);
				pRecord->m_unPreviousDR7Bits = static_cast<DWORD_PTR>(pWindowsContext->Dr7) & unSlotMask;
				pFrame->m_bPreviousSlotCaptured = true;

				const DWORD_PTR unDR7Bits = GetHardwareHookDR7Bits(pFrame->m_unDRIndex, pRecord->m_Type, pRecord->m_unSize);
				SetDebugRegisterSlot(pWindowsContext, pFrame->m_unDRIndex, reinterpret_cast<DWORD_PTR>(pRecord->m_pAddress), unDR7Bits);

				pFrame->m_DesiredContext = *pWindowsContext;
				pFrame->m_FinalSlotState = WindowsHardwareSlotState::DESIRED;
				pFrame->m_bContextMutationSucceeded = true;
				bHandled = true;
			}

		} else if ((pFrame->m_Type == WindowsHardwareOperationType::UNHOOKING) ||
			((pFrame->m_Type == WindowsHardwareOperationType::INSTALLING) && (pFrame->m_bForceRestore))) {
			if (pFrame->m_bPreviousSlotCaptured) {
				SetDebugRegisterSlot(pWindowsContext, pFrame->m_unDRIndex, pRecord->m_unPreviousAddress, pRecord->m_unPreviousDR7Bits);
				pFrame->m_DesiredContext = *pWindowsContext;
			}

			pFrame->m_FinalSlotState = WindowsHardwareSlotState::ORIGINAL;
			pFrame->m_bContextMutationSucceeded = true;
			bHandled = true;
		}

		if (bHandled) {
#if defined(DETOURS_ARCH_X64)
			pWindowsContext->Rip += kWindowsHardwareContextBreakpointInstructionSize;
#elif defined(DETOURS_ARCH_X86)
			pWindowsContext->Eip += kWindowsHardwareContextBreakpointInstructionSize;
#endif
		}

		return bHandled;
	}

	static void ReclaimInterruptHookSnapshots() noexcept {
		auto* const pProcessState = GetHookProcessState();
		if (!pProcessState) {
			return;
		}

		for (auto const& ReaderCount : pProcessState->m_arrInterruptHookSnapshotReaders) {
			if (ReaderCount.load(std::memory_order_seq_cst) != 0) {
				return;
			}
		}

		std::unique_ptr<InterruptHookSnapshot>* const pSnapshotHolder = &pProcessState->m_pRetiredInterruptHookSnapshots;
		while (*pSnapshotHolder) {
			auto* const pSnapshot = pSnapshotHolder->get();
			*pSnapshotHolder = std::move(pSnapshot->m_pNextRetired);
		}
	}

	static void PublishInterruptHookSnapshot(InterruptHookRecord const* const pExcludedRecord) {
		constexpr std::size_t kInitialEpoch = 0;
		constexpr std::size_t kAlternateEpochMask = 1;

		static_assert(kInterruptHookSnapshotEpochCount == (kAlternateEpochMask + 1), "interrupt-hook snapshot epoch toggle requires exactly two epochs");

		auto* const pProcessState = GetHookProcessState();
		if (!pProcessState) {
			return;
		}

		std::unique_ptr<InterruptHookSnapshot> pSnapshot = std::make_unique<InterruptHookSnapshot>();
		auto* const pCurrentSnapshot = pProcessState->m_pInterruptHookSnapshot.get();
		pSnapshot->m_unEpoch = pCurrentSnapshot ? (pCurrentSnapshot->m_unEpoch ^ kAlternateEpochMask) : kInitialEpoch;
		pSnapshot->m_vecRecords.reserve(pProcessState->m_deqInterruptHookRecords.size());
		for (auto const& pRecord : pProcessState->m_deqInterruptHookRecords) {
			if (pRecord && (pRecord.get() != pExcludedRecord)) {
				pSnapshot->m_vecRecords.push_back({pRecord->m_fnCallBack, pRecord->m_unInterrupt});
			}
		}

		std::unique_ptr<InterruptHookSnapshot> pPreviousSnapshot = std::move(pProcessState->m_pInterruptHookSnapshot);
		pProcessState->m_pInterruptHookSnapshot = std::move(pSnapshot);
		pProcessState->m_pPublishedInterruptHookSnapshot.store(pProcessState->m_pInterruptHookSnapshot.get(), std::memory_order_seq_cst);
		pProcessState->m_unPublishedInterruptHookSnapshotEpoch.store(pProcessState->m_pInterruptHookSnapshot->m_unEpoch, std::memory_order_seq_cst);

		if (pPreviousSnapshot) {
			pPreviousSnapshot->m_pNextRetired = std::move(pProcessState->m_pRetiredInterruptHookSnapshots);
			pProcessState->m_pRetiredInterruptHookSnapshots = std::move(pPreviousSnapshot);
		}

		ReclaimInterruptHookSnapshots();
	}

	static InterruptHookSnapshot* AcquireInterruptHookSnapshot(unsigned int* const pEpochOut) noexcept {
		constexpr unsigned int kReaderReferenceCount = 1;
		constexpr unsigned int kMaxReaderCount = std::numeric_limits<unsigned int>::max();

		if (!pEpochOut) {
			return nullptr;
		}

		auto* const pProcessState = GetHookProcessState();
		if (!pProcessState) {
			return nullptr;
		}

		for (;;) {
			const unsigned int unEpoch = pProcessState->m_unPublishedInterruptHookSnapshotEpoch.load(std::memory_order_seq_cst);
			if (unEpoch >= kInterruptHookSnapshotEpochCount) {
				return nullptr;
			}

			auto& ReaderCount = pProcessState->m_arrInterruptHookSnapshotReaders[unEpoch];
			unsigned int unReaderCount = ReaderCount.load(std::memory_order_seq_cst);
			for (;;) {
				if (unReaderCount == kMaxReaderCount) {
					return nullptr;
				}

				const unsigned int unIncrementedReaderCount = unReaderCount + kReaderReferenceCount;
				if (ReaderCount.compare_exchange_weak(unReaderCount, unIncrementedReaderCount, std::memory_order_seq_cst, std::memory_order_seq_cst)) {
					break;
				}
			}

			auto* const pSnapshot = pProcessState->m_pPublishedInterruptHookSnapshot.load(std::memory_order_seq_cst);
			if ((pProcessState->m_unPublishedInterruptHookSnapshotEpoch.load(std::memory_order_seq_cst) == unEpoch) &&
				((!pSnapshot) || (pSnapshot->m_unEpoch == unEpoch))) {
				*pEpochOut = unEpoch;
				return pSnapshot;
			}

			ReaderCount.fetch_sub(kReaderReferenceCount, std::memory_order_seq_cst);
		}
	}

