		// FindData (Native)
		// ----------------------------------------------------------------

		void const* FindDataNative(void const* const pAddress, const std::size_t unSize, unsigned char const* const pPattern, const std::size_t unPatternSize) noexcept {
			if (!IsScanRangeValid(pAddress, unSize) || !IsScanRangeValid(pPattern, unPatternSize) || (unSize < unPatternSize)) {
				return nullptr;
			}

			// Object storage may be inspected through an unsigned-character view.
			unsigned char const* const pSourceBytes = static_cast<unsigned char const*>(pAddress);
			const std::size_t unLastStartIndex = unSize - unPatternSize;

			for (std::size_t unStartIndex = 0; unStartIndex <= unLastStartIndex; ++unStartIndex) {
				bool bMatches = true;

				for (std::size_t unPatternIndex = 0; unPatternIndex < unPatternSize; ++unPatternIndex) {
					if (pSourceBytes[unStartIndex + unPatternIndex] != pPattern[unPatternIndex]) {
						bMatches = false;
						break;
					}
				}

				if (bMatches) {
					return pSourceBytes + unStartIndex;
				}
			}

			return nullptr;
		}

		void const* FindDataNative(HMODULE const hModule, unsigned char const* const pPattern, const std::size_t unPatternSize) noexcept {
			PEImageInfo ImageInformation {};
			if (!IsScanRangeValid(pPattern, unPatternSize) || !GetPEImageInfo(hModule, &ImageInformation)) {
				return nullptr;
			}

			auto ScanRange = [pPattern, unPatternSize](void const* const pAddress, const std::size_t unSize) noexcept -> void const* {
				return FindDataNative(pAddress, unSize, pPattern, unPatternSize);
			};
			return ScanReadablePEImage(ImageInformation, ScanRange);
		}

