		// ----------------------------------------------------------------
		// FindSignature (Native)
		// ----------------------------------------------------------------

		void const* FindSignatureNative(void const* const pAddress, const std::size_t unSize, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			if (!IsScanRangeValid(pAddress, unSize) || !pszSignature) {
				return nullptr;
			}

			const std::size_t unSignatureLength = ::strnlen(pszSignature, kMaximumTextLength);
			if (!unSignatureLength || (unSignatureLength == kMaximumTextLength) || (unSize < unSignatureLength)) {
				return nullptr;
			}

			unsigned char const* const pSourceData = static_cast<unsigned char const*>(pAddress);
			// Compare the signature through its unsigned byte representation.
			unsigned char const* const pSignatureBytes = reinterpret_cast<unsigned char const*>(pszSignature);

			const std::size_t unLastMatchOffset = unSize - unSignatureLength;
			for (std::size_t unMatchOffset = 0; unMatchOffset <= unLastMatchOffset; ++unMatchOffset) {
				bool bMatched = true;

				for (std::size_t unSignatureIndex = 0; unSignatureIndex < unSignatureLength; ++unSignatureIndex) {
					const unsigned char unSignatureByte = pSignatureBytes[unSignatureIndex];
					if ((unSignatureByte != unIgnoredByte) && (pSourceData[unMatchOffset + unSignatureIndex] != unSignatureByte)) {
						bMatched = false;
						break;
					}
				}

				if (bMatched) {
					return ApplyScanOffset(pSourceData, unSize, unMatchOffset, unOffset);
				}
			}

			return nullptr;
		}

		void const* FindSignatureNative(void* const hModule, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			return FindSignatureInModule(hModule, pszSignature, unIgnoredByte, unOffset, static_cast<fnSignatureScanner>(&FindSignatureNative));
		}

