		// ----------------------------------------------------------------
		// FindSignature (SSE2)
		// ----------------------------------------------------------------

		__attribute__((target("sse2"))) void const* FindSignatureSSE2(void const* const pAddress, const std::size_t unSize, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			constexpr std::size_t kVectorByteCount = 16;
			constexpr std::size_t kVectorLastByteIndex = kVectorByteCount - 1;
			constexpr std::size_t kPrefetchDistance = 64;
			constexpr unsigned short kAllCandidateBits = 0xFFFF;

			static_assert(kVectorByteCount <= std::numeric_limits<unsigned short>::digits, "SSE2 candidate mask is too narrow");

			if (!IsScanRangeValid(pAddress, unSize) || !pszSignature) {
				return nullptr;
			}

			const std::size_t unSignatureLength = ::strnlen(pszSignature, kMaximumTextLength);
			if (!unSignatureLength || (unSignatureLength == kMaximumTextLength) || (unSize < unSignatureLength)) {
				return nullptr;
			}

			unsigned char const* const pSourceData = static_cast<unsigned char const*>(pAddress);
			// Compare the signature through its unsigned byte representation.
			unsigned char const* const pSignatureBytes = reinterpret_cast<unsigned char const*>(pszSignature);

			const std::size_t unLastMatchOffset = unSize - unSignatureLength;
			if (unLastMatchOffset < kVectorLastByteIndex) {
				return FindSignatureNative(pSourceData, unSize, pszSignature, unIgnoredByte, unOffset);
			}

			const std::size_t unVectorEnd = unLastMatchOffset - kVectorLastByteIndex;
			const std::size_t unAlignedVectorEnd = unVectorEnd & ~kVectorLastByteIndex;
			const std::size_t unVectorCycleCount = (unAlignedVectorEnd / kVectorByteCount) + 1;

			for (std::size_t unCycleIndex = 0; unCycleIndex < unVectorCycleCount; ++unCycleIndex) {
				const std::size_t unCycleOffset = unCycleIndex * kVectorByteCount;

				if (kPrefetchDistance < (unSize - unCycleOffset)) {
					const std::size_t unPrefetchOffset = unCycleOffset + kPrefetchDistance;
					_mm_prefetch(reinterpret_cast<char const*>(pSourceData + unPrefetchOffset), _MM_HINT_T0);
				}

				unsigned short unCandidateBits = kAllCandidateBits;

				for (std::size_t unSignatureIndex = 0; (unSignatureIndex < unSignatureLength) && (unCandidateBits != 0); ++unSignatureIndex) {
					const unsigned char unSignatureByte = pSignatureBytes[unSignatureIndex];
					if (unSignatureByte == unIgnoredByte) {
						continue;
					}

					__m128i const SourceVector = _mm_loadu_si128(reinterpret_cast<__m128i const*>(pSourceData + unCycleOffset + unSignatureIndex));
					__m128i const SignatureVector = _mm_set1_epi8(static_cast<char>(unSignatureByte));
					__m128i const ComparisonVector = _mm_cmpeq_epi8(SourceVector, SignatureVector);

					unCandidateBits &= static_cast<unsigned short>(_mm_movemask_epi8(ComparisonVector));
				}

				if (unCandidateBits != 0) {
					const std::size_t unBitIndex = static_cast<std::size_t>(BitScanForward(unCandidateBits));
					const std::size_t unMatchOffset = unCycleOffset + unBitIndex;

					return ApplyScanOffset(pSourceData, unSize, unMatchOffset, unOffset);
				}
			}

			const std::size_t unCoveredMatchOffset = unAlignedVectorEnd + kVectorLastByteIndex;
			if (unCoveredMatchOffset < unLastMatchOffset) {
				unsigned char const* const pTailData = pSourceData + (unCoveredMatchOffset + 1);
				const std::size_t unTailSize = unSize - (unCoveredMatchOffset + 1);
				return FindSignatureNative(pTailData, unTailSize, pszSignature, unIgnoredByte, unOffset);
			}

			return nullptr;
		}

