		// ----------------------------------------------------------------
		// FindSignature (AVX2)
		// ----------------------------------------------------------------

		__attribute__((target("avx2"))) void const* FindSignatureAVX2(void const* const pAddress, const std::size_t unSize, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			constexpr std::size_t kVectorByteCount = 32;
			constexpr std::size_t kLastVectorByteIndex = kVectorByteCount - 1;
			constexpr std::size_t kPrefetchDistance = 64;
			constexpr unsigned int kAllCandidateBits = std::numeric_limits<unsigned int>::max();

			static_assert(std::numeric_limits<unsigned int>::digits == kVectorByteCount, "candidate mask must contain one bit per AVX2 byte");

			if (!IsScanRangeValid(pAddress, unSize) || !pszSignature) {
				return nullptr;
			}

			const std::size_t unSignatureLength = ::strnlen(pszSignature, kMaximumTextLength);
			if (!unSignatureLength || (unSignatureLength == kMaximumTextLength) || (unSize < unSignatureLength)) {
				return nullptr;
			}

			// Object storage and character data may be inspected through unsigned-character views.
			unsigned char const* const pBytes = static_cast<unsigned char const*>(pAddress);
			unsigned char const* const pSignatureBytes = reinterpret_cast<unsigned char const*>(pszSignature);

			const std::size_t unLastStartIndex = unSize - unSignatureLength;
			if (unLastStartIndex < kLastVectorByteIndex) {
				return FindSignatureSSE2(pBytes, unSize, pszSignature, unIgnoredByte, unOffset);
			}

			const std::size_t unLastVectorStartIndex = unLastStartIndex - kLastVectorByteIndex;
			const std::size_t unLastAlignedVectorStartIndex = unLastVectorStartIndex & ~(kVectorByteCount - 1);
			const std::size_t unVectorCycleCount = (unLastAlignedVectorStartIndex / kVectorByteCount) + 1;

			for (std::size_t unCycleIndex = 0; unCycleIndex < unVectorCycleCount; ++unCycleIndex) {
				const std::size_t unCycleOffset = unCycleIndex * kVectorByteCount;

				if (kPrefetchDistance < (unSize - unCycleOffset)) {
					const std::size_t unPrefetchIndex = unCycleOffset + kPrefetchDistance;
					_mm_prefetch(reinterpret_cast<char const*>(pBytes + unPrefetchIndex), _MM_HINT_T0);
				}

				unsigned int unCandidateMask = kAllCandidateBits;

				for (std::size_t unSignatureIndex = 0; (unSignatureIndex < unSignatureLength) && unCandidateMask; ++unSignatureIndex) {
					const unsigned char unSignatureByte = pSignatureBytes[unSignatureIndex];
					if (unSignatureByte == unIgnoredByte) {
						continue;
					}

					__m256i const DataVector = _mm256_loadu_si256(reinterpret_cast<__m256i const*>(pBytes + unCycleOffset + unSignatureIndex));
					__m256i const SignatureByteVector = _mm256_set1_epi8(static_cast<char>(unSignatureByte));
					__m256i const ComparisonVector = _mm256_cmpeq_epi8(DataVector, SignatureByteVector);

					unCandidateMask &= static_cast<unsigned int>(_mm256_movemask_epi8(ComparisonVector));
				}

				if (unCandidateMask) {
					const std::size_t unCandidateIndex = static_cast<std::size_t>(BitScanForward(unCandidateMask));
					const std::size_t unMatchIndex = unCycleOffset + unCandidateIndex;

					return ApplyScanOffset(pBytes, unSize, unMatchIndex, unOffset);
				}
			}

			const std::size_t unLastCoveredStartIndex = unLastAlignedVectorStartIndex + kLastVectorByteIndex;
			if (unLastCoveredStartIndex < unLastStartIndex) {
				const std::size_t unTailStartIndex = unLastCoveredStartIndex + 1;
				unsigned char const* const pTailBytes = pBytes + unTailStartIndex;
				const std::size_t unTailSize = unSize - unTailStartIndex;
				return FindSignatureSSE2(pTailBytes, unTailSize, pszSignature, unIgnoredByte, unOffset);
			}

			return nullptr;
		}

		void const* FindSignatureAVX2(void* const hModule, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			return FindSignatureInModule(hModule, pszSignature, unIgnoredByte, unOffset, static_cast<fnSignatureScanner>(&FindSignatureAVX2));
		}

