		static void InitializeScanFeaturesInternal() noexcept {
			constexpr std::size_t kEAXRegisterIndex = 0;
			constexpr std::size_t kEBXRegisterIndex = 1;
			constexpr std::size_t kECXRegisterIndex = 2;
			constexpr std::size_t kEDXRegisterIndex = 3;
			constexpr unsigned int kHighestBasicCPUIDLeafQuery = 0;
			constexpr unsigned int kFeatureInformationLeaf = 1;
			constexpr unsigned int kExtendedFeatureInformationLeaf = 7;
			constexpr unsigned int kDefaultCPUIDSubLeaf = 0;
			constexpr std::uint32_t kSSE2FeatureMask = std::uint32_t(1) << 26;
			constexpr std::uint32_t kOSXSAVEFeatureMask = std::uint32_t(1) << 27;
			constexpr std::uint32_t kAVXFeatureMask = std::uint32_t(1) << 28;
			constexpr std::uint32_t kAVX2FeatureMask = std::uint32_t(1) << 5;
			constexpr std::uint32_t kAVX512FFeatureMask = std::uint32_t(1) << 16;
			constexpr std::uint32_t kAVX512BWFeatureMask = std::uint32_t(1) << 30;
			constexpr std::uint64_t kAVXStateMask = 0x6;
			constexpr std::uint64_t kAVX512StateMask = 0xE6;

			static_assert(sizeof(int) == sizeof(std::uint32_t), "CPUID registers must be 32 bits");
			static_assert(kCPUIDRegisterCount > kEDXRegisterIndex, "CPUID register storage must include EDX");

			int arrCPUIDRegisters[kCPUIDRegisterCount] {};
			GetLinuxCPUID(arrCPUIDRegisters, kHighestBasicCPUIDLeafQuery, kDefaultCPUIDSubLeaf);
			const unsigned int unMaximumCPUIDLeaf = static_cast<unsigned int>(arrCPUIDRegisters[kEAXRegisterIndex]);
			if (unMaximumCPUIDLeaf < kFeatureInformationLeaf) {
				return;
			}

			GetLinuxCPUID(arrCPUIDRegisters, kFeatureInformationLeaf, kDefaultCPUIDSubLeaf);
			const std::uint32_t unFeatureECX = static_cast<std::uint32_t>(arrCPUIDRegisters[kECXRegisterIndex]);
			const std::uint32_t unFeatureEDX = static_cast<std::uint32_t>(arrCPUIDRegisters[kEDXRegisterIndex]);

			g_bFeatureSSE2.store((unFeatureEDX & kSSE2FeatureMask) != 0, std::memory_order_release);

			const bool bHasOSXSAVE = (unFeatureECX & kOSXSAVEFeatureMask) != 0;
			const bool bHasAVX = (unFeatureECX & kAVXFeatureMask) != 0;
			const std::uint64_t unXCR0 = (bHasOSXSAVE && bHasAVX) ? GetLinuxXCR0() : 0;
			const bool bHasYMMState = (unXCR0 & kAVXStateMask) == kAVXStateMask;
			const bool bHasZMMState = (unXCR0 & kAVX512StateMask) == kAVX512StateMask;

			if (unMaximumCPUIDLeaf < kExtendedFeatureInformationLeaf) {
				return;
			}

			GetLinuxCPUID(arrCPUIDRegisters, kExtendedFeatureInformationLeaf, kDefaultCPUIDSubLeaf);
			const std::uint32_t unExtendedFeatureEBX = static_cast<std::uint32_t>(arrCPUIDRegisters[kEBXRegisterIndex]);
			const bool bHasAVX512F = (unExtendedFeatureEBX & kAVX512FFeatureMask) != 0;

			g_bFeatureAVX2.store(bHasYMMState && ((unExtendedFeatureEBX & kAVX2FeatureMask) != 0), std::memory_order_release);
			g_bFeatureAVX512BW.store(bHasZMMState && bHasAVX512F && ((unExtendedFeatureEBX & kAVX512BWFeatureMask) != 0), std::memory_order_release);
		}

		static void InitializeScanFeatures() noexcept {
			try {
				std::call_once(g_ScanFeaturesOnce, InitializeScanFeaturesInternal);
			} catch (...) {
				// Feature flags retain their conservative false defaults if one-time initialization fails.
			}
		}

		// ----------------------------------------------------------------
		// FindSignature (Auto)
		// ----------------------------------------------------------------

		void const* FindSignature(void const* const pAddress, const std::size_t unSize, char const* const pszSignature, const unsigned char unIgnoredByte, const std::size_t unOffset) noexcept {
			if (!IsScanRangeValid(pAddress, unSize) || !pszSignature) {
				return nullptr;
			}

			InitializeScanFeatures();

			if (g_bFeatureAVX512BW.load(std::memory_order_acquire)) {
				return FindSignatureAVX512(pAddress, unSize, pszSignature, unIgnoredByte, unOffset);
			}

			if (g_bFeatureAVX2.load(std::memory_order_acquire)) {
				return FindSignatureAVX2(pAddress, unSize, pszSignature, unIgnoredByte, unOffset);
			}

			if (g_bFeatureSSE2.load(std::memory_order_acquire)) {
				return FindSignatureSSE2(pAddress, unSize, pszSignature, unIgnoredByte, unOffset);
			}

			return FindSignatureNative(pAddress, unSize, pszSignature, unIgnoredByte, unOffset);
		}

