		// FindData (AVX2)
		// ----------------------------------------------------------------

		__attribute__((target("avx2"))) void const* FindDataAVX2(void const* const pAddress, const std::size_t unSize, unsigned char const* const pPattern, const std::size_t unPatternSize) noexcept {
			constexpr std::size_t kVectorWidth = 32;
			constexpr std::size_t kLastVectorByteIndex = kVectorWidth - 1;
			constexpr std::size_t kPrefetchDistance = 64;
			constexpr unsigned int kAllCandidateBits = std::numeric_limits<unsigned int>::max();

			static_assert(static_cast<std::size_t>(std::numeric_limits<unsigned int>::digits) == kVectorWidth, "AVX2 candidate mask must contain one bit per byte");
			static_assert(sizeof(__m256i) == kVectorWidth, "unexpected AVX2 vector width");

			if (!IsScanRangeValid(pAddress, unSize) || !IsScanRangeValid(pPattern, unPatternSize) || (unSize < unPatternSize)) {
				return nullptr;
			}

			// Object representation may be inspected through an unsigned-character byte view.
			unsigned char const* const pSourceBytes = reinterpret_cast<unsigned char const*>(pAddress);

			const std::size_t unLastStartIndex = unSize - unPatternSize;
			if (unLastStartIndex < kLastVectorByteIndex) {
				return FindDataSSE2(pSourceBytes, unSize, pPattern, unPatternSize);
			}

			const std::size_t unLastVectorStartIndex = unLastStartIndex - kLastVectorByteIndex;
			const std::size_t unLastAlignedStartIndex = unLastVectorStartIndex & ~kLastVectorByteIndex;
			const std::size_t unVectorCount = (unLastAlignedStartIndex / kVectorWidth) + 1;

			for (std::size_t unVectorIndex = 0; unVectorIndex < unVectorCount; ++unVectorIndex) {
				const std::size_t unVectorOffset = unVectorIndex * kVectorWidth;

				if (kPrefetchDistance < (unSize - unVectorOffset)) {
					_mm_prefetch(reinterpret_cast<char const*>(pSourceBytes + unVectorOffset + kPrefetchDistance), _MM_HINT_T0);
				}

				unsigned int unCandidateMask = kAllCandidateBits;

				for (std::size_t unPatternIndex = 0; (unPatternIndex < unPatternSize) && (unCandidateMask != 0); ++unPatternIndex) {
					__m256i const SourceVector = _mm256_loadu_si256(reinterpret_cast<__m256i const*>(pSourceBytes + unVectorOffset + unPatternIndex));
					__m256i const PatternVector = _mm256_set1_epi8(static_cast<char>(pPattern[unPatternIndex]));
					__m256i const MatchVector = _mm256_cmpeq_epi8(SourceVector, PatternVector);

					unCandidateMask &= static_cast<unsigned int>(_mm256_movemask_epi8(MatchVector));
				}

				if (unCandidateMask != 0) {
					const std::size_t unCandidateIndex = static_cast<std::size_t>(BitScanForward(unCandidateMask));
					const std::size_t unStartIndex = unVectorOffset + unCandidateIndex;

					unsigned char const* const pFoundAddress = pSourceBytes + unStartIndex;
					return pFoundAddress;
				}
			}

			const std::size_t unCoveredEndIndex = unLastAlignedStartIndex + kLastVectorByteIndex;
			if (unCoveredEndIndex < unLastStartIndex) {
				const std::size_t unTailOffset = unCoveredEndIndex + 1;
				unsigned char const* const pTailBytes = pSourceBytes + unTailOffset;
				const std::size_t unTailSize = unSize - unTailOffset;
				return FindDataSSE2(pTailBytes, unTailSize, pPattern, unPatternSize);
			}

			return nullptr;
		}

