		// ----------------------------------------------------------------
		// FindData (Auto)
		// ----------------------------------------------------------------

		void const* FindData(void const* const pAddress, const std::size_t unSize, unsigned char const* const pPattern, const std::size_t unPatternSize) noexcept {
			if (!IsScanRangeValid(pAddress, unSize) || !IsScanRangeValid(pPattern, unPatternSize) || (unSize < unPatternSize)) {
				return nullptr;
			}

			InitializeScanFeatures();

			if (g_bFeatureAVX512BW.load(std::memory_order_acquire)) {
				return FindDataAVX512(pAddress, unSize, pPattern, unPatternSize);
			}

			if (g_bFeatureAVX2.load(std::memory_order_acquire)) {
				return FindDataAVX2(pAddress, unSize, pPattern, unPatternSize);
			}

			if (g_bFeatureSSE2.load(std::memory_order_acquire)) {
				return FindDataSSE2(pAddress, unSize, pPattern, unPatternSize);
			}

			return FindDataNative(pAddress, unSize, pPattern, unPatternSize);
		}

