		constexpr std::size_t kWindowsStackScanChunkEntries = 1024;
		constexpr std::size_t kWindowsStackScanByteLimit = 8 * 1024 * 1024;
		constexpr std::size_t kWindowsStackScanTotalByteLimit = 64 * 1024 * 1024;
