		// ----------------------------------------------------------------

		Event::Event(const bool bManualReset, const bool bInitialState) :
			m_hEvent(CreateEvent(nullptr, bManualReset, bInitialState, nullptr))
		{
		}

		Event::~Event() noexcept {
			if (m_hEvent && (m_hEvent != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hEvent);
			}
		}

		Event::Event(Event&& Other) noexcept :
			m_hEvent(Other.m_hEvent)
		{
			Other.m_hEvent = nullptr;
		}

		Event& Event::operator=(Event&& Other) noexcept {
			if (this == &Other) {
				return *this;
			}

			if (m_hEvent && (m_hEvent != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hEvent);
			}

			m_hEvent = Other.m_hEvent;
			Other.m_hEvent = nullptr;

			return *this;
		}

		HANDLE Event::GetEvent() const noexcept {
			return m_hEvent;
		}

		bool Event::Signal() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!SetEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool Event::Reset() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!ResetEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool Event::Pulse() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!PulseEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool Event::Wait(const DWORD unMilliseconds) {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (WaitForSingleObject(m_hEvent, unMilliseconds) != WAIT_OBJECT_0) {
				return false;
			}

			return true;
		}

		// ----------------------------------------------------------------
		// EventServer
		// ----------------------------------------------------------------

		EventServer::EventServer(const bool bIsGlobal, const bool bManualReset, const bool bInitialState) :
			m_szEventName {}
		{
			constexpr DWORD kLowDWORDMask = 0xFFFF'FFFF;
			constexpr unsigned int kHighDWORDShift = 32;
			constexpr int kFormatFailure = -1;

			m_hEvent = nullptr;

			PTEB const pTEB = GetTEB();
			if (!pTEB) {
				return;
			}

			const std::uintptr_t unProcessIDValue = static_cast<std::uintptr_t>(pTEB->ClientId.UniqueProcess);
			const std::uintptr_t unThreadIDValue = static_cast<std::uintptr_t>(pTEB->ClientId.UniqueThread);
			const DWORD unProcessID = static_cast<DWORD>(unProcessIDValue & kLowDWORDMask);
			const DWORD unThreadID = static_cast<DWORD>(unThreadIDValue & kLowDWORDMask);
			const DWORD64 unCycleCount = __rdtsc();
			if (_stprintf_s(
				m_szEventName, _T("EVENT:%08X:%08X:%08X%08X"),
				kLowDWORDMask - unProcessID, kLowDWORDMask - unThreadID,
				static_cast<DWORD>(unCycleCount & kLowDWORDMask),
				static_cast<DWORD>((unCycleCount >> kHighDWORDShift) & kLowDWORDMask)) == kFormatFailure) {
				memset(m_szEventName, 0, sizeof(m_szEventName));
				return;
			}

			TCHAR szEvent[kNamedObjectNameCapacity] {};
			if (bIsGlobal) {
				if (_stprintf_s(szEvent, _T("Global\\%s"), m_szEventName) == kFormatFailure) {
					memset(m_szEventName, 0, sizeof(m_szEventName));
					return;
				}

			} else {
				if (_stprintf_s(szEvent, _T("Local\\%s"), m_szEventName) == kFormatFailure) {
					memset(m_szEventName, 0, sizeof(m_szEventName));
					return;
				}
			}

			m_hEvent = CreateEvent(nullptr, bManualReset, bInitialState, szEvent);
		}

		EventServer::~EventServer() noexcept {
			if (m_hEvent && (m_hEvent != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hEvent);
			}
		}

		EventServer::EventServer(EventServer&& Other) noexcept :
			m_hEvent(Other.m_hEvent)
		{
			std::memcpy(m_szEventName, Other.m_szEventName, sizeof(m_szEventName));

			std::memset(Other.m_szEventName, 0, sizeof(Other.m_szEventName));
			Other.m_hEvent = nullptr;
		}

		EventServer& EventServer::operator=(EventServer&& Other) noexcept {
			if (this == &Other) {
				return *this;
			}

			if (m_hEvent && (m_hEvent != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hEvent);
			}

			std::memcpy(m_szEventName, Other.m_szEventName, sizeof(m_szEventName));
			m_hEvent = Other.m_hEvent;

			std::memset(Other.m_szEventName, 0, sizeof(Other.m_szEventName));
			Other.m_hEvent = nullptr;

			return *this;
		}

		bool EventServer::GetEventName(TCHAR* const pszEventNameOut, const std::size_t unCapacity) {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			return CopyNamedObjectName(pszEventNameOut, unCapacity, m_szEventName, kNamedObjectNameCapacity);
		}

		HANDLE EventServer::GetEvent() const noexcept {
			return m_hEvent;
		}

		bool EventServer::Signal() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!SetEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool EventServer::Reset() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!ResetEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool EventServer::Pulse() {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!PulseEvent(m_hEvent)) {
				return false;
			}

			return true;
		}

		bool EventServer::Wait(const DWORD unMilliseconds) {
			if (!m_hEvent || (m_hEvent == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (WaitForSingleObject(m_hEvent, unMilliseconds) != WAIT_OBJECT_0) {
				return false;
			}

			return true;
		}

		// ----------------------------------------------------------------
		// EventClient
		// ----------------------------------------------------------------

		EventClient::EventClient(TCHAR const* const pszEventName, const std::size_t unCapacity, const bool bIsGlobal) {
			constexpr int kFormatFailure = -1;

			m_hEvent = nullptr;

			TCHAR szValidatedEventName[kNamedObjectNameCapacity] {};
			if (!CopyNamedObjectName(szValidatedEventName, kNamedObjectNameCapacity, pszEventName, unCapacity)) {
				return;
			}

			TCHAR szEvent[kNamedObjectNameCapacity] {};
			if (bIsGlobal) {
				if (_stprintf_s(szEvent, _T("Global\\%s"), szValidatedEventName) == kFormatFailure) {
					return;
				}

			} else {
				if (_stprintf_s(szEvent, _T("Local\\%s"), szValidatedEventName) == kFormatFailure) {
					return;
				}
			}

			m_hEvent = OpenEvent(EVENT_ALL_ACCESS, FALSE, szEvent);
		}

