		// ----------------------------------------------------------------
		// MutexServer
		// ----------------------------------------------------------------

		MutexServer::MutexServer(const bool bIsGlobal, const bool bInitialState) :
			m_szMutexName {}
		{
			constexpr DWORD kLowDWORDMask = 0xFFFF'FFFF;
			constexpr unsigned int kHighDWORDShift = 32;
			constexpr int kFormatFailure = -1;

			m_hMutex = nullptr;

			PTEB const pTEB = GetTEB();
			if (!pTEB) {
				return;
			}

			const std::uintptr_t unProcessIDValue = static_cast<std::uintptr_t>(pTEB->ClientId.UniqueProcess);
			const std::uintptr_t unThreadIDValue = static_cast<std::uintptr_t>(pTEB->ClientId.UniqueThread);
			const DWORD unProcessID = static_cast<DWORD>(unProcessIDValue & kLowDWORDMask);
			const DWORD unThreadID = static_cast<DWORD>(unThreadIDValue & kLowDWORDMask);
			const DWORD64 unCycleCount = __rdtsc();
			if (_stprintf_s(
				m_szMutexName, _T("MUTEX:%08X:%08X:%08X%08X"),
				kLowDWORDMask - unProcessID, kLowDWORDMask - unThreadID,
				static_cast<DWORD>(unCycleCount & kLowDWORDMask),
				static_cast<DWORD>((unCycleCount >> kHighDWORDShift) & kLowDWORDMask)) == kFormatFailure) {
				memset(m_szMutexName, 0, sizeof(m_szMutexName));
				return;
			}

			TCHAR szMutex[kNamedObjectNameCapacity] {};
			if (bIsGlobal) {
				if (_stprintf_s(szMutex, _T("Global\\%s"), m_szMutexName) == kFormatFailure) {
					memset(m_szMutexName, 0, sizeof(m_szMutexName));
					return;
				}

			} else {
				if (_stprintf_s(szMutex, _T("Local\\%s"), m_szMutexName) == kFormatFailure) {
					memset(m_szMutexName, 0, sizeof(m_szMutexName));
					return;
				}
			}

			m_hMutex = CreateMutex(nullptr, bInitialState, szMutex);
		}

		MutexServer::~MutexServer() noexcept {
			if (m_hMutex && (m_hMutex != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hMutex);
			}
		}

		MutexServer::MutexServer(MutexServer&& Other) noexcept :
			m_hMutex(Other.m_hMutex)
		{
			std::memcpy(m_szMutexName, Other.m_szMutexName, sizeof(m_szMutexName));

			std::memset(Other.m_szMutexName, 0, sizeof(Other.m_szMutexName));
			Other.m_hMutex = nullptr;
		}

		MutexServer& MutexServer::operator=(MutexServer&& Other) noexcept {
			if (this == &Other) {
				return *this;
			}

			if (m_hMutex && (m_hMutex != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hMutex);
			}

			std::memcpy(m_szMutexName, Other.m_szMutexName, sizeof(m_szMutexName));
			m_hMutex = Other.m_hMutex;

			std::memset(Other.m_szMutexName, 0, sizeof(Other.m_szMutexName));
			Other.m_hMutex = nullptr;

			return *this;
		}

