		// ----------------------------------------------------------------
		// Suspender
		// ----------------------------------------------------------------

		static bool IsWindowsStackProtectionReadable(const DWORD unProtection) noexcept {
			return IsWindowsMemoryProtectionReadable(unProtection);
		}

		static bool IsWindowsThreadContextReferencingRange(CONTEXT const& WindowsContext, void const* const pAddress, const std::size_t unSize) noexcept {
#if defined(DETOURS_ARCH_X64)
			const DWORD64 arrRegisters[] = {
				WindowsContext.Rax, WindowsContext.Rbx, WindowsContext.Rcx,
				WindowsContext.Rdx, WindowsContext.Rsi, WindowsContext.Rdi,
				WindowsContext.Rbp, WindowsContext.Rsp, WindowsContext.R8,
				WindowsContext.R9, WindowsContext.R10, WindowsContext.R11,
				WindowsContext.R12, WindowsContext.R13, WindowsContext.R14,
				WindowsContext.R15, WindowsContext.Rip
			};
#elif defined(DETOURS_ARCH_X86)
			const DWORD arrRegisters[] = {
				WindowsContext.Eax, WindowsContext.Ebx, WindowsContext.Ecx,
				WindowsContext.Edx, WindowsContext.Esi, WindowsContext.Edi,
				WindowsContext.Ebp, WindowsContext.Esp, WindowsContext.Eip
			};
#endif

			for (auto const& unRegister : arrRegisters) {
				if (IsInRange(pAddress, unSize, reinterpret_cast<void*>(static_cast<std::uintptr_t>(unRegister)))) {
					return true;
				}
			}

			return false;
		}

		static bool IsWindowsThreadStackReferencingRange(HANDLE const hThread, CONTEXT const& WindowsContext, void const* const pAddress, const std::size_t unSize, const bool bCheckContextRegisters, std::size_t* const pRemainingBytesOut) noexcept {
			// A failed stack inspection cannot prove that patching the target is safe.
			// Treat every inspection failure as a live reference.
			if (!pAddress || !unSize || !pRemainingBytesOut) {
				return true;
			}

			const std::uintptr_t unRangeAddress = reinterpret_cast<std::uintptr_t>(pAddress);
			if (unSize > (std::numeric_limits<std::uintptr_t>::max() - unRangeAddress)) {
				return true;
			}

			if (bCheckContextRegisters && IsWindowsThreadContextReferencingRange(WindowsContext, pAddress, unSize)) {
				return true;
			}

			PTEB const pTEB = GetTEB(hThread);
			if (!pTEB) {
				return true;
			}

			NT_TIB ThreadInformation {};
			if (!ReadCurrentWindowsMemory(pTEB, &ThreadInformation, sizeof(ThreadInformation))) {
				return true;
			}

#if defined(DETOURS_ARCH_X64)
			std::uintptr_t unStackCursorAddress = static_cast<std::uintptr_t>(WindowsContext.Rsp);
#elif defined(DETOURS_ARCH_X86)
			std::uintptr_t unStackCursorAddress = static_cast<std::uintptr_t>(WindowsContext.Esp);
#endif
			const std::uintptr_t unStackBeginAddress = reinterpret_cast<std::uintptr_t>(ThreadInformation.StackLimit);
			const std::uintptr_t unStackEndAddress = reinterpret_cast<std::uintptr_t>(ThreadInformation.StackBase);

			if (!unStackBeginAddress || !unStackCursorAddress) {
				return true;
			}

			if ((unStackBeginAddress > unStackCursorAddress) || (unStackCursorAddress >= unStackEndAddress)) {
				return true;
			}

			const std::size_t unStackByteCount = static_cast<std::size_t>(unStackEndAddress - unStackCursorAddress);
			if ((unStackByteCount > kWindowsStackScanByteLimit) || (unStackByteCount > *pRemainingBytesOut)) {
				return true;
			}

			*pRemainingBytesOut -= unStackByteCount;

			std::uintptr_t arrCandidateAddresses[kWindowsStackScanChunkEntries] {};

			while (unStackCursorAddress < unStackEndAddress) {
				MEMORY_BASIC_INFORMATION MemoryInformation {};
				if (VirtualQuery(reinterpret_cast<void const*>(unStackCursorAddress), &MemoryInformation, sizeof(MemoryInformation)) < sizeof(MemoryInformation)) {
					return true;
				}

				const std::uintptr_t unRegionBeginAddress = reinterpret_cast<std::uintptr_t>(MemoryInformation.BaseAddress);
				if (!MemoryInformation.RegionSize || (MemoryInformation.RegionSize > (std::numeric_limits<std::uintptr_t>::max() - unRegionBeginAddress))) {
					return true;
				}

				const std::uintptr_t unRegionEndAddress = std::min(unStackEndAddress, unRegionBeginAddress + static_cast<std::uintptr_t>(MemoryInformation.RegionSize));
				if (unRegionEndAddress <= unStackCursorAddress) {
					return true;
				}

				if ((MemoryInformation.State != MEM_COMMIT) || !IsWindowsStackProtectionReadable(MemoryInformation.Protect)) {
					return true;
				}

				unStackCursorAddress = AlignUp<std::uintptr_t>(unStackCursorAddress, alignof(std::uintptr_t));
				if (!unStackCursorAddress || (unStackCursorAddress >= unRegionEndAddress)) {
					unStackCursorAddress = unRegionEndAddress;
					continue;
				}

				while ((unRegionEndAddress - unStackCursorAddress) >= sizeof(std::uintptr_t)) {
					const std::size_t unReadableEntryCount = static_cast<std::size_t>((unRegionEndAddress - unStackCursorAddress) / sizeof(std::uintptr_t));
					const std::size_t unReadSize = std::min(sizeof(arrCandidateAddresses), unReadableEntryCount * sizeof(std::uintptr_t));
					if (!ReadCurrentWindowsMemory(reinterpret_cast<void const*>(unStackCursorAddress), arrCandidateAddresses, unReadSize)) {
						return true;
					}

					const std::size_t unEntryCount = unReadSize / sizeof(std::uintptr_t);
					for (std::size_t unIndex = 0; unIndex < unEntryCount; ++unIndex) {
						if (!IsInRange(pAddress, unSize, reinterpret_cast<void*>(arrCandidateAddresses[unIndex]))) {
							continue;
						}

						const std::size_t unCandidateOffset = static_cast<std::size_t>(arrCandidateAddresses[unIndex] - unRangeAddress);
						auto ReadCode = [unRangeAddress](const std::size_t unOffset, unsigned char* const pCodeOut, const std::size_t unCodeSize) noexcept -> bool {
							return (unOffset <= (std::numeric_limits<std::uintptr_t>::max() - unRangeAddress)) &&
								ReadCurrentWindowsMemory(reinterpret_cast<void const*>(unRangeAddress + unOffset), pCodeOut, unCodeSize);
						};
						const StackReturnAddressValidationResult ValidationResult = ValidateDecodedStackReturnAddress(unCandidateOffset, unSize, ReadCode);
						if (ValidationResult != StackReturnAddressValidationResult::NOT_RETURN_ADDRESS) {
							return true;
						}
					}

					unStackCursorAddress += unEntryCount * sizeof(std::uintptr_t);
				}

				unStackCursorAddress = unRegionEndAddress;
			}

			return false;
		}

		static bool ResumeWindowsThread(const unsigned long long unOwnerToken, const std::size_t unFrameIndex, const DWORD unThreadID, HANDLE const hThread, CONTEXT const* const pContext) noexcept {
			auto* const pFrame = GetWindowsSuspenderFrame(unOwnerToken, unFrameIndex);
			if (!pFrame || !unThreadID || !hThread || (hThread == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if ((pFrame->m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::PUBLISHED) ||
				(pFrame->m_unOwnerToken != unOwnerToken) ||
				(pFrame->m_unTargetThreadID != unThreadID) ||
				(pFrame->m_hTargetThread.load(std::memory_order_acquire) != hThread)) {
				return false;
			}

			if (pFrame->m_Step.load(std::memory_order_acquire) == WindowsSuspenderFrameStep::TARGET_RESUMED) {
				return ReleaseWindowsSuspenderFrame(pFrame);
			}

			const WindowsThreadLiveness ThreadLiveness = GetWindowsThreadLiveness(hThread);
			if ((ThreadLiveness == WindowsThreadLiveness::UNKNOWN) || (ThreadLiveness == WindowsThreadLiveness::TERMINATED)) {
				return (ThreadLiveness == WindowsThreadLiveness::TERMINATED) && ReleaseWindowsSuspenderFrame(pFrame);
			}

			if (pContext) {
#if defined(DETOURS_ARCH_X64)
				const std::uintptr_t unInstructionPointer = static_cast<std::uintptr_t>(pContext->Rip);
#elif defined(DETOURS_ARCH_X86)
				const std::uintptr_t unInstructionPointer = static_cast<std::uintptr_t>(pContext->Eip);
#endif
				pFrame->m_unDesiredInstructionPointer.store(unInstructionPointer, std::memory_order_release);
			}

			if (!ResumeWindowsSuspenderFrame(pFrame)) {
				if (GetWindowsThreadLiveness(hThread) == WindowsThreadLiveness::TERMINATED) {
					return ReleaseWindowsSuspenderFrame(pFrame);
				}

				return false;
			}

			return ReleaseWindowsSuspenderFrame(pFrame);
		}

		Suspender::Suspender() {
			static_assert(kWindowsSuspenderThreadCapacity == kWindowsSuspenderFrameCapacity, "Windows suspender thread and frame capacities must match");

			m_pThreads.reset(new (std::nothrow) SUSPENDER_DATA[kWindowsSuspenderThreadCapacity]);
			m_unThreadCount = 0;
			m_unSuspendDepth = 0;
			m_unThreadStateReaperPauseOwnerToken = 0;
			m_bCleanupPending = false;
		}

		Suspender::~Suspender() noexcept {
			while (GetSuspendDepth() != 0) {
				if (!Resume()) {
					_mm_pause();
				}
			}
		}

		bool Suspender::ReconcileWindowsState() {
			constexpr bool kDoNotCreateThreadState = false;

			if (!m_unThreadStateReaperPauseOwnerToken) {
				return m_unSuspendDepth == 0;
			}

			unsigned int unCurrentGeneration = 0;
			auto* const pCurrentThreadState = AcquireCurrentWindowsMemoryHookThreadState(kDoNotCreateThreadState, &unCurrentGeneration);
			const unsigned long long unCurrentOwnerToken = GetWindowsThreadStateOwnerToken(pCurrentThreadState, unCurrentGeneration);
			if (pCurrentThreadState) {
				ReleaseWindowsMemoryHookThreadState(pCurrentThreadState, unCurrentGeneration);
			}

			if (unCurrentOwnerToken == m_unThreadStateReaperPauseOwnerToken) {
				return true;
			}

			auto* const pPreviousThreadState = GetWindowsThreadStateFromOwnerToken(m_unThreadStateReaperPauseOwnerToken, nullptr);
			if (pPreviousThreadState) {
				const WindowsThreadStateSlotStatus PreviousStatus = GetWindowsThreadStateSlotStatus(pPreviousThreadState->m_unSlotState.load(std::memory_order_acquire));
				if (PreviousStatus != WindowsThreadStateSlotStatus::FREE) {
					const WindowsThreadLiveness PreviousThreadLiveness = GetWindowsThreadLiveness(pPreviousThreadState->m_hThread.load(std::memory_order_acquire));
					if ((PreviousThreadLiveness != WindowsThreadLiveness::TERMINATED) ||
						pPreviousThreadState->m_unThreadStateReaperPauseDepth.load(std::memory_order_acquire) ||
						HasWindowsSuspenderPayload(pPreviousThreadState)) {
						return false;
					}
				}
			}

			if (!m_pThreads) {
				return false;
			}

			for (std::size_t unIndex = 0; unIndex < kWindowsSuspenderThreadCapacity; ++unIndex) {
				m_pThreads[unIndex] = {};
			}

			m_unThreadCount = 0;
			m_unSuspendDepth = 0;
			m_unThreadStateReaperPauseOwnerToken = 0;
			m_bCleanupPending = false;

			return true;
		}

		bool Suspender::IsWindowsThreadPrepared(const DWORD unThreadID, bool* const pIdentityKnownOut) const noexcept {
			if (!pIdentityKnownOut) {
				return false;
			}

			*pIdentityKnownOut = false;

			if (!unThreadID || !m_pThreads) {
				return false;
			}

			*pIdentityKnownOut = true;

			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				SUSPENDER_DATA const& SuspendedThread = m_pThreads[unIndex];
				if (SuspendedThread.m_unThreadID != unThreadID) {
					continue;
				}

				const WindowsThreadLiveness ThreadLiveness = GetWindowsThreadLiveness(SuspendedThread.m_hHandle);
				if (ThreadLiveness == WindowsThreadLiveness::LIVE) {
					return true;
				}

				if (ThreadLiveness == WindowsThreadLiveness::UNKNOWN) {
					*pIdentityKnownOut = false;
					return false;
				}
			}

			return false;
		}

		void Suspender::CompactWindowsThreads() noexcept {
			if (!m_pThreads) {
				m_unThreadCount = 0;
				return;
			}

			std::size_t unRetainedCount = 0;
			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				if (!m_pThreads[unIndex].m_unThreadID) {
					continue;
				}

				if (unRetainedCount != unIndex) {
					m_pThreads[unRetainedCount] = m_pThreads[unIndex];
					m_pThreads[unIndex] = {};
				}

				++unRetainedCount;
			}

			m_unThreadCount = unRetainedCount;
		}

		bool Suspender::CompleteWindowsCleanup() {
			if (!m_bCleanupPending) {
				return true;
			}

			if (!ResumeSuspendedThreads() || !ReleaseWindowsThreadStateReaperPause(m_unThreadStateReaperPauseOwnerToken)) {
				return false;
			}

			m_unThreadStateReaperPauseOwnerToken = 0;
			m_bCleanupPending = false;

			return true;
		}

		bool Suspender::PrepareWindowsThread(const DWORD unThreadID, HANDLE const hThread, bool* const pAddedOut) {
			if (!pAddedOut) {
				if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
					CloseHandle(hThread);
				}

				return false;
			}

			*pAddedOut = false;

			if (!unThreadID || !hThread || (hThread == INVALID_HANDLE_VALUE) ||
				!m_pThreads ||
				!m_unThreadStateReaperPauseOwnerToken ||
				(m_unThreadCount >= kWindowsSuspenderThreadCapacity)) {
				if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
					CloseHandle(hThread);
				}

				return false;
			}

			std::size_t unFrameIndex = 0;
			auto* const pFrame = ReserveWindowsSuspenderFrame(m_unThreadStateReaperPauseOwnerToken, unThreadID, hThread, &unFrameIndex);
			if (!pFrame) {
				if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
					CloseHandle(hThread);
				}

				return false;
			}

			SUSPENDER_DATA SuspendedThread {};
			SuspendedThread.m_unThreadID = unThreadID;
			SuspendedThread.m_hHandle = hThread;
			SuspendedThread.m_unOwnerToken = m_unThreadStateReaperPauseOwnerToken;
			SuspendedThread.m_unFrameIndex = unFrameIndex;
			SuspendedThread.m_bContextCaptured = false;

			m_pThreads[m_unThreadCount] = SuspendedThread;
			++m_unThreadCount;
			*pAddedOut = true;

			return true;
		}

		bool Suspender::SuspendPreparedWindowsThreads(const std::size_t unBeginIndex) {
			if (unBeginIndex > m_unThreadCount) {
				return false;
			}

			bool bSuccess = true;
			std::size_t unIndex = unBeginIndex;
			while (unIndex < m_unThreadCount) {
				SUSPENDER_DATA& SuspendedThread = m_pThreads[unIndex];
				if (SuspendedThread.m_bContextCaptured) {
					++unIndex;
					continue;
				}

				auto* const pFrame = GetWindowsSuspenderFrame(SuspendedThread.m_unOwnerToken, SuspendedThread.m_unFrameIndex);
				if (!pFrame || !SuspendWindowsSuspenderFrame(pFrame, &SuspendedThread.m_Context)) {
					if ((GetWindowsThreadLiveness(SuspendedThread.m_hHandle) == WindowsThreadLiveness::TERMINATED) &&
						ResumeWindowsThread(SuspendedThread.m_unOwnerToken, SuspendedThread.m_unFrameIndex, SuspendedThread.m_unThreadID, SuspendedThread.m_hHandle, nullptr)) {
						SuspendedThread = {};
						++unIndex;
						continue;
					}

					bSuccess = false;
					break;
				}

				SuspendedThread.m_bContextCaptured = true;
				++unIndex;
			}

			CompactWindowsThreads();

			return bSuccess;
		}

		bool Suspender::ResumeSuspendedThreads() {
			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				SUSPENDER_DATA& SuspendedThread = m_pThreads[unIndex];
				if (ResumeWindowsThread(SuspendedThread.m_unOwnerToken, SuspendedThread.m_unFrameIndex, SuspendedThread.m_unThreadID, SuspendedThread.m_hHandle, SuspendedThread.m_bContextCaptured ? &SuspendedThread.m_Context : nullptr)) {
					SuspendedThread = {};
				}
			}

			CompactWindowsThreads();

			if (!m_unThreadCount && m_unThreadStateReaperPauseOwnerToken && !ReleaseUnusedWindowsSuspenderFrames(m_unThreadStateReaperPauseOwnerToken)) {
				return false;
			}

			return !m_unThreadCount;
		}

		bool Suspender::Suspend(const bool bSweepThreads) {
			if (!PrepareWindowsThreadStateReaperForSuspend()) {
				return false;
			}

			const bool bLocked = m_Mutex.Lock();

			if (!bLocked) {
				return false;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return false;
			}

			if (!m_pThreads) {
				m_Mutex.UnLock();
				return false;
			}

			if (m_bCleanupPending) {
				CompleteWindowsCleanup();
				m_Mutex.UnLock();
				return false;
			}

			if (m_unSuspendDepth > 0) {
				if (m_unSuspendDepth == std::numeric_limits<std::size_t>::max()) {
					m_Mutex.UnLock();
					return false;
				}

				++m_unSuspendDepth;
				return true;
			}

			if (m_unThreadCount) {
				m_Mutex.UnLock();
				return false;
			}

			if (!RequestWindowsThreadStateReaperPause(&m_unThreadStateReaperPauseOwnerToken)) {
				m_Mutex.UnLock();
				return false;
			}

			auto FailSuspension = [this]() noexcept -> bool {
				const bool bResourcesReleased = ResumeSuspendedThreads();
				if (bResourcesReleased && ReleaseWindowsThreadStateReaperPause(m_unThreadStateReaperPauseOwnerToken)) {
					m_unThreadStateReaperPauseOwnerToken = 0;
					m_bCleanupPending = false;

				} else {
					m_bCleanupPending = true;
				}

				m_Mutex.UnLock();
				return false;
			};

			const std::size_t unInitialAdded = SuspendNewThreadsSnapshot();
			if (unInitialAdded == kSuspendSnapshotFailure) {
				return FailSuspension();
			}

			if (bSweepThreads) {
				bool bSweepStable = false;
				for (std::size_t unSweepIndex = 0; unSweepIndex < kWindowsSuspenderSweepLimit; ++unSweepIndex) {
					const std::size_t unAdded = SuspendNewThreadsSnapshot();
					if (unAdded == kSuspendSnapshotFailure) {
						return FailSuspension();
					}

					if (unAdded == 0) {
						bSweepStable = true;
						break;
					}
				}

				if (!bSweepStable) {
					return FailSuspension();
				}
			}

			m_unSuspendDepth = 1;

			return true;
		}

		bool Suspender::Resume() {
			if (!m_Mutex.Lock()) {
				return false;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return false;
			}

			if (m_bCleanupPending) {
				const bool bCleanupCompleted = CompleteWindowsCleanup();
				m_Mutex.UnLock();
				return bCleanupCompleted;
			}

			if (m_unSuspendDepth == 0) {
				m_Mutex.UnLock();
				return false;
			}

			if (m_unSuspendDepth > 1) {
				--m_unSuspendDepth;
				m_Mutex.UnLock();
				m_Mutex.UnLock();
				return true;
			}

			if (!ResumeSuspendedThreads()) {
				m_Mutex.UnLock();
				return false;
			}

			if (!ReleaseWindowsThreadStateReaperPause(m_unThreadStateReaperPauseOwnerToken)) {
				m_Mutex.UnLock();
				return false;
			}

			m_unSuspendDepth = 0;
			m_unThreadStateReaperPauseOwnerToken = 0;
			m_Mutex.UnLock();
			m_Mutex.UnLock();

			return true;
		}

		bool Suspender::IsSuspended() {
			if (!m_Mutex.Lock()) {
				return false;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return true;
			}

			const bool bSuspended = m_bCleanupPending || (m_unSuspendDepth > 0);
			m_Mutex.UnLock();
			return bSuspended;
		}

		std::size_t Suspender::GetSuspendDepth() {
			if (!m_Mutex.Lock()) {
				return 0;
			}

			if (!ReconcileWindowsState()) {
				const std::size_t unDepth = m_unSuspendDepth ? m_unSuspendDepth : 1;
				m_Mutex.UnLock();
				return unDepth;
			}

			const std::size_t unDepth = m_bCleanupPending ? 1 : m_unSuspendDepth;
			m_Mutex.UnLock();
			return unDepth;
		}

		bool Suspender::IsRegionExecuting(void const* const pAddress, const std::size_t unSize) {
			if (!pAddress || !unSize) {
				return false;
			}

			const bool bLocked = m_Mutex.Lock();

			if (!bLocked) {
				return true;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return true;
			}

			bool bExecuting = false;
			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				SUSPENDER_DATA const& SuspendedThread = m_pThreads[unIndex];
#if defined(DETOURS_ARCH_X64)
				void* const pInstructionPointer = reinterpret_cast<void*>(static_cast<std::uintptr_t>(SuspendedThread.m_Context.Rip));
#elif defined(DETOURS_ARCH_X86)
				void* const pInstructionPointer = reinterpret_cast<void*>(static_cast<std::uintptr_t>(SuspendedThread.m_Context.Eip));
#endif
				if (IsInRange(pAddress, unSize, pInstructionPointer)) {
					bExecuting = true;
					break;
				}
			}

			const bool bUnlocked = m_Mutex.UnLock();
			return !bUnlocked || bExecuting;
		}

		bool Suspender::IsRegionInCallStacks(void const* const pAddress, const std::size_t unSize) noexcept {
			constexpr bool kCheckContextRegisters = true;

			if (!pAddress || !unSize) {
				return false;
			}

			const bool bLocked = m_Mutex.Lock();

			if (!bLocked) {
				return true;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return true;
			}

			bool bReferenced = false;
			std::size_t unRemainingBytes = kWindowsStackScanTotalByteLimit;
			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				SUSPENDER_DATA const& SuspendedThread = m_pThreads[unIndex];
				bReferenced = !SuspendedThread.m_bContextCaptured ||
					IsWindowsThreadStackReferencingRange(SuspendedThread.m_hHandle, SuspendedThread.m_Context, pAddress, unSize, kCheckContextRegisters, &unRemainingBytes);
				if (bReferenced) {
					break;
				}
			}

			const bool bUnlocked = m_Mutex.UnLock();
			return !bUnlocked || bReferenced;
		}

		bool Suspender::FixExecutionAddress(void const* const pAddress, void const* const pNewAddress) {
			if (!pAddress || !pNewAddress) {
				return false;
			}

			const bool bLocked = m_Mutex.Lock();

			if (!bLocked) {
				return false;
			}

			if (!ReconcileWindowsState()) {
				m_Mutex.UnLock();
				return false;
			}

			for (std::size_t unIndex = 0; unIndex < m_unThreadCount; ++unIndex) {
				SUSPENDER_DATA& SuspendedThread = m_pThreads[unIndex];
#if defined(DETOURS_ARCH_X64)
				std::uintptr_t unInstructionPointer = static_cast<std::uintptr_t>(SuspendedThread.m_Context.Rip);
#elif defined(DETOURS_ARCH_X86)
				std::uintptr_t unInstructionPointer = static_cast<std::uintptr_t>(SuspendedThread.m_Context.Eip);
#endif
				if (reinterpret_cast<void*>(unInstructionPointer) == pAddress) {
					unInstructionPointer = reinterpret_cast<std::uintptr_t>(pNewAddress);

					auto* const pFrame = GetWindowsSuspenderFrame(SuspendedThread.m_unOwnerToken, SuspendedThread.m_unFrameIndex);
					if (!pFrame ||
						(pFrame->m_State.load(std::memory_order_acquire) != WindowsSuspenderFrameState::PUBLISHED) ||
						(pFrame->m_unOwnerToken != SuspendedThread.m_unOwnerToken) ||
						(pFrame->m_unTargetThreadID != SuspendedThread.m_unThreadID) ||
						(pFrame->m_hTargetThread.load(std::memory_order_acquire) != SuspendedThread.m_hHandle)) {
						m_Mutex.UnLock();
						return false;
					}

					pFrame->m_unDesiredInstructionPointer.store(unInstructionPointer, std::memory_order_release);
				}

#if defined(DETOURS_ARCH_X64)
				SuspendedThread.m_Context.Rip = static_cast<DWORD64>(unInstructionPointer);
#elif defined(DETOURS_ARCH_X86)
				SuspendedThread.m_Context.Eip = static_cast<DWORD>(unInstructionPointer);
#endif
			}

			return m_Mutex.UnLock();
		}

		std::size_t Suspender::SuspendNewThreadsSnapshot() {
			constexpr std::size_t kFirstPreparedThreadIndex = 0;

			if (!m_unThreadStateReaperPauseOwnerToken) {
				return kSuspendSnapshotFailure;
			}

			std::size_t unAddedCount = 0;
			HANDLE hPreviousThread = nullptr;
			bool bPreviousThreadOwnedByFrame = false;
			for (;;) {
				HANDLE hThread = nullptr;
				const NTSTATUS nStatus = EnumerateNextWindowsThread(hPreviousThread, &hThread);
				if (hPreviousThread && !bPreviousThreadOwnedByFrame && !CloseHandle(hPreviousThread)) {
					if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
#pragma warning(suppress: 6001) // EnumerateNextWindowsThread initializes the output handle before returning.
						CloseHandle(hThread);
					}

					return kSuspendSnapshotFailure;
				}

				hPreviousThread = nullptr;
				bPreviousThreadOwnedByFrame = false;

				if (nStatus == kWindowsNativeNoMoreEntries) {
					if (hThread) {
						CloseHandle(hThread);
						return kSuspendSnapshotFailure;
					}

					break;
				}

				if ((nStatus < 0) || !hThread) {
					if (hThread) {
						CloseHandle(hThread);
					}

					return kSuspendSnapshotFailure;
				}

				const DWORD unThreadID = GetThreadId(hThread);
				if (!unThreadID) {
					CloseHandle(hThread);
					return kSuspendSnapshotFailure;
				}

				const DWORD unCurrentThreadID = GetCurrentWindowsThreadStateReaperThreadID();
				const DWORD unReaperThreadID = g_unWindowsThreadStateReaperThreadID.load(std::memory_order_acquire);
				if ((unThreadID == unCurrentThreadID) || (unThreadID == unReaperThreadID)) {
					hPreviousThread = hThread;
					bPreviousThreadOwnedByFrame = false;
					continue;
				}

				const WindowsThreadLiveness ThreadLiveness = GetWindowsThreadLiveness(hThread);
				if (ThreadLiveness == WindowsThreadLiveness::UNKNOWN) {
					CloseHandle(hThread);
					return kSuspendSnapshotFailure;
				}

				if (ThreadLiveness == WindowsThreadLiveness::TERMINATED) {
					hPreviousThread = hThread;
					bPreviousThreadOwnedByFrame = false;
					continue;
				}

				bool bIdentityKnown = false;
				const bool bPrepared = IsWindowsThreadPrepared(unThreadID, &bIdentityKnown);
				if (!bIdentityKnown) {
					CloseHandle(hThread);
					return kSuspendSnapshotFailure;
				}

				if (bPrepared) {
					hPreviousThread = hThread;
					bPreviousThreadOwnedByFrame = false;
					continue;
				}

				bool bAdded = false;
				if (!PrepareWindowsThread(unThreadID, hThread, &bAdded)) {
					return kSuspendSnapshotFailure;
				}

				if (bAdded) {
					++unAddedCount;
					hPreviousThread = hThread;
					bPreviousThreadOwnedByFrame = true;
				} else {
					hPreviousThread = nullptr;
					bPreviousThreadOwnedByFrame = false;
				}
			}

			if (hPreviousThread && !bPreviousThreadOwnedByFrame && !CloseHandle(hPreviousThread)) {
				return kSuspendSnapshotFailure;
			}

			if (!SuspendPreparedWindowsThreads(kFirstPreparedThreadIndex)) {
				return kSuspendSnapshotFailure;
			}

			return unAddedCount;
		}

		SuspendTransaction::SuspendTransaction(Suspender& SuspenderReference, const bool bSweepThreads) :
			m_pSuspender(&SuspenderReference)
		{
			m_unBeginDepth = 0;
			m_bActive = false;

			if (!m_pSuspender || !PrepareWindowsThreadStateReaperForSuspend()) {
				return;
			}

			m_unBeginDepth = m_pSuspender->GetSuspendDepth();
			m_bActive = m_pSuspender->Suspend(bSweepThreads);
		}

		SuspendTransaction::~SuspendTransaction() noexcept {
			EndNoFail();
		}

		bool SuspendTransaction::Begin(const bool bSweepThreads) {
			if (!m_pSuspender || m_bActive) {
				return false;
			}

			if (!PrepareWindowsThreadStateReaperForSuspend()) {
				return false;
			}

			m_unBeginDepth = m_pSuspender->GetSuspendDepth();
			m_bActive = m_pSuspender->Suspend(bSweepThreads);
			return m_bActive;
		}

		bool SuspendTransaction::End() {
			if (!m_pSuspender || !m_bActive) {
				return false;
			}

			if ((m_pSuspender->GetSuspendDepth() > m_unBeginDepth) && !m_pSuspender->Resume()) {
				return false;
			}

			m_bActive = false;

			return true;
		}

		bool SuspendTransaction::IsActive() const noexcept {
			return m_bActive;
		}

		SuspendTransaction::operator bool() const noexcept {
			return m_bActive;
		}
