		CriticalSection::CriticalSection() {
			constexpr bool kForkStatePending = false;

			m_pCriticalSection = nullptr;

			std::unique_ptr<LinuxMutexHandle, void(*)(LinuxMutexHandle*)> pCriticalSection(new (std::nothrow) LinuxMutexHandle(), MutexDestroy);
			if (!pCriticalSection) {
				throw std::bad_alloc();
			}

			auto* const pPrivateState = CreateLinuxPrivateMutexState(kForkStatePending);
			if (!pPrivateState) {
				throw std::bad_alloc();
			}

			pCriticalSection->m_pPrivateState.store(pPrivateState, std::memory_order_release);

			m_pCriticalSection = pCriticalSection.release();
		}

		CriticalSection::~CriticalSection() noexcept {
			MutexDestroy(static_cast<LinuxMutexHandle*>(m_pCriticalSection));
			m_pCriticalSection = nullptr;
		}

		pthread_mutex_t* CriticalSection::GetCriticalSection() {
			auto* const pPrivateState = GetLinuxPrivateMutexState(static_cast<LinuxMutexHandle*>(m_pCriticalSection));
			return pPrivateState ? &pPrivateState->m_Mutex : nullptr;
		}

		void CriticalSection::Enter() {
			pthread_mutex_t* const pCriticalSection = GetCriticalSection();
			if (pCriticalSection) {
				// The compatibility API cannot report failure; robust-owner recovery remains best-effort.
				AcceptRobustMutexResult(pCriticalSection, ::pthread_mutex_lock(pCriticalSection));
			}
		}

		void CriticalSection::Leave() {
			pthread_mutex_t* const pCriticalSection = GetCriticalSection();
			if (pCriticalSection) {
				// The compatibility API cannot report a native unlock failure.
				::pthread_mutex_unlock(pCriticalSection);
			}
		}

		template <std::size_t unCapacity>
		bool ResumeLinuxSuspendedThreads(std::array<unsigned int, unCapacity>* const pSuspendedThreadIDsInOut, std::size_t* const pSuspendedThreadCountInOut, LinuxThreadSuspendProcessState* const pProcessState) {
			if ((!pSuspendedThreadIDsInOut) ||
				(!pSuspendedThreadCountInOut) ||
				(!pProcessState) ||
				(*pSuspendedThreadCountInOut > pSuspendedThreadIDsInOut->size())) {
				return false;
			}

			for (std::size_t unIndex = 0; unIndex < *pSuspendedThreadCountInOut;) {
				const unsigned int unThreadID = (*pSuspendedThreadIDsInOut)[unIndex];
				if (static_cast<std::uintmax_t>(unThreadID) > static_cast<std::uintmax_t>(std::numeric_limits<pid_t>::max())) {
					++unIndex;
					continue;
				}

				if (!ResumeThreadByIDLocked(static_cast<pid_t>(unThreadID), pProcessState)) {
					++unIndex;
					continue;
				}

				--(*pSuspendedThreadCountInOut);
				(*pSuspendedThreadIDsInOut)[unIndex] = (*pSuspendedThreadIDsInOut)[*pSuspendedThreadCountInOut];
				(*pSuspendedThreadIDsInOut)[*pSuspendedThreadCountInOut] = 0;
			}

			return *pSuspendedThreadCountInOut == 0;
		}

		template <std::size_t unCapacity>
		std::size_t SuspendLinuxThreadsSnapshot(std::array<unsigned int, unCapacity>* const pSuspendedThreadIDsInOut, std::size_t* const pSuspendedThreadCountInOut, LinuxThreadSuspendProcessState* const pProcessState) {
			if ((!pSuspendedThreadIDsInOut) ||
				(!pSuspendedThreadCountInOut) ||
				(!pProcessState) ||
				(*pSuspendedThreadCountInOut > pSuspendedThreadIDsInOut->size())) {
				return kSuspendSnapshotFailure;
			}

			std::size_t unSuspendedThreadCount = 0;
			const pid_t nCurrentThreadID = GetCurrentThreadID();
			LinuxThreadIDSnapshot const Snapshot = EnumerateProcessThreadIDs();
			if (!Snapshot.m_bSucceeded) {
				errno = Snapshot.m_nError ? Snapshot.m_nError : EIO;
				return kSuspendSnapshotFailure;
			}

			for (std::size_t unIndex = 0; unIndex < Snapshot.m_unThreadCount; ++unIndex) {
				const pid_t nThreadID = Snapshot.m_arrThreadIDs[unIndex];
				if ((nThreadID == nCurrentThreadID) ||
					(IsSuspendedThreadOwned(pSuspendedThreadIDsInOut->data(), *pSuspendedThreadCountInOut, nThreadID))) {
					continue;
				}

				if ((nThreadID <= 0) ||
					(static_cast<std::uintmax_t>(nThreadID) > std::numeric_limits<unsigned int>::max())) {
					return kSuspendSnapshotFailure;
				}

				if (*pSuspendedThreadCountInOut >= pSuspendedThreadIDsInOut->size()) {
					errno = 0;
					if ((::syscall(SYS_tgkill, ::getpid(), nThreadID, 0) != 0) && (errno == ESRCH)) {
						continue;
					}

					return kSuspendSnapshotFailure;
				}

				if (!SuspendThreadByIDLocked(nThreadID, pProcessState)) {
					errno = 0;
					if ((::syscall(SYS_tgkill, ::getpid(), nThreadID, 0) == 0) || (errno != ESRCH)) {
						return kSuspendSnapshotFailure;
					}

					continue;
				}

				(*pSuspendedThreadIDsInOut)[*pSuspendedThreadCountInOut] = static_cast<unsigned int>(nThreadID);
				++(*pSuspendedThreadCountInOut);
				++unSuspendedThreadCount;
			}

			return unSuspendedThreadCount;
		}

		Suspender::Suspender() :
			m_arrSuspendedThreadIDs {}
		{
			m_unSuspendDepth = 0;
			m_unSuspendedThreadCount = 0;
		}

		Suspender::~Suspender() noexcept {
			LinuxCancellationDisableGuard CancellationGuard;
			while (GetSuspendDepth() != 0) {
				if (!Resume()) {
					std::this_thread::yield();
				}
			}
		}

		bool Suspender::LockAndRefreshForkState() {
			bool bLocked = false;
			bLocked = m_Mutex.Lock();

			if (!bLocked) {
				return false;
			}

			if (ConsumeLinuxMutexForkState(static_cast<LinuxMutexHandle*>(m_Mutex.GetMutex()))) {
				m_unSuspendDepth = 0;
				m_unSuspendedThreadCount = 0;
			}

			return true;
		}

		bool Suspender::Suspend(const bool bSweepThreads) {
			constexpr std::size_t kInitialSuspendDepth = 1;
			constexpr std::chrono::milliseconds kThreadSweepRetryDelay = std::chrono::milliseconds(1);
			constexpr std::chrono::milliseconds kThreadSweepTimeout = std::chrono::milliseconds(100);

			if (!LockAndRefreshForkState()) {
				return false;
			}

			SuspenderMutexUnlockGuard MutexGuard(m_Mutex);

			if (m_unSuspendDepth > 0) {
				if (m_unSuspendDepth == std::numeric_limits<std::size_t>::max()) {
					return false;
				}

				++m_unSuspendDepth;
				MutexGuard.Release();

				return true;
			}

			if (!InstallThreadSuspendSignal()) {
				return false;
			}

			auto* const pProcessState = GetThreadSuspendProcessState();
			if (!pProcessState) {
				return false;
			}

			std::unique_lock<std::mutex> RequestLock(pProcessState->m_RequestMutex, std::try_to_lock);
			if (!RequestLock.owns_lock()) {
				return false;
			}

			auto RollBackSuspendedThreads = [this, pProcessState]() noexcept {
				LinuxCancellationDisableGuard CancellationGuard;
				while (!ResumeLinuxSuspendedThreads(&m_arrSuspendedThreadIDs, &m_unSuspendedThreadCount, pProcessState)) {
					std::this_thread::yield();
				}
			};
			auto RollBackGuard = MakeLinuxScopeExitGuard(RollBackSuspendedThreads);

			std::chrono::steady_clock::time_point const StartTime = std::chrono::steady_clock::now();
			while (true) {
				const std::size_t unAddedThreadCount = SuspendLinuxThreadsSnapshot(&m_arrSuspendedThreadIDs, &m_unSuspendedThreadCount, pProcessState);
				if (unAddedThreadCount == kSuspendSnapshotFailure) {
					return false;
				}

				if (!bSweepThreads || (unAddedThreadCount == 0)) {
					break;
				}

				if ((std::chrono::steady_clock::now() - StartTime) >= kThreadSweepTimeout) {
					return false;
				}

				std::this_thread::sleep_for(kThreadSweepRetryDelay);
			}

			m_unSuspendDepth = kInitialSuspendDepth;
			RollBackGuard.Release();
			MutexGuard.Release();

			return true;
		}

		bool Suspender::Resume() {
			constexpr std::size_t kInitialSuspendDepth = 1;

			if (!LockAndRefreshForkState()) {
				return false;
			}

			SuspenderMutexUnlockGuard MutexGuard(m_Mutex);

			if (m_unSuspendDepth == 0) {
				return false;
			}

			if (m_unSuspendDepth > kInitialSuspendDepth) {
				if (!m_Mutex.UnLock()) {
					return false;
				}

				--m_unSuspendDepth;

				return true;
			}

			auto* const pProcessState = GetThreadSuspendProcessState();
			if (!pProcessState) {
				return false;
			}

			std::unique_lock<std::mutex> RequestLock(pProcessState->m_RequestMutex, std::try_to_lock);
			if (!RequestLock.owns_lock()) {
				return false;
			}

			auto RollBackResume = [this, pProcessState]() noexcept {
				LinuxCancellationDisableGuard CancellationGuard;
				while (!ResumeLinuxSuspendedThreads(&m_arrSuspendedThreadIDs, &m_unSuspendedThreadCount, pProcessState)) {
					std::this_thread::yield();
				}

				if (m_Mutex.UnLock()) {
					m_unSuspendDepth = 0;
				}
			};
			auto RollBackGuard = MakeLinuxScopeExitGuard(RollBackResume);

			if (!ResumeLinuxSuspendedThreads(&m_arrSuspendedThreadIDs, &m_unSuspendedThreadCount, pProcessState)) {
				RollBackGuard.Release();

				return false;
			}

			RollBackGuard.Release();

			if (!m_Mutex.UnLock()) {
				return false;
			}

			m_unSuspendDepth = 0;

			return true;
		}

		bool Suspender::IsSuspended() {
			return GetSuspendDepth() != 0;
		}

		std::size_t Suspender::GetSuspendDepth() {
			if (!LockAndRefreshForkState()) {
				return 0;
			}

			SuspenderMutexUnlockGuard MutexGuard(m_Mutex);
			const std::size_t unDepth = m_unSuspendDepth;

			if (!m_Mutex.UnLock()) {
				return 0;
			}

			MutexGuard.Release();

			return unDepth;
		}

		bool Suspender::IsRegionExecuting(void const* const pAddress, const std::size_t unSize) {
			if (!pAddress || !unSize) {
				return false;
			}

			const bool bMutexAlreadyOwned = IsLinuxMutexOwnedByCurrentThread(static_cast<LinuxMutexHandle*>(m_Mutex.GetMutex()));
			if (!bMutexAlreadyOwned && !LockAndRefreshForkState()) {
				return true;
			}

			bool bExecuting = false;

			if (m_unSuspendDepth != 0) {
				auto* const pProcessState = GetThreadSuspendProcessState();
				if (!pProcessState) {
					bExecuting = m_unSuspendedThreadCount != 0;

				} else {
					try {
						std::lock_guard<std::mutex> RequestLock(pProcessState->m_RequestMutex);
						bExecuting = IsSuspendedInstructionPointerInRange(pProcessState, m_arrSuspendedThreadIDs.data(), m_unSuspendedThreadCount, pAddress, unSize);
					} catch (...) {
						bExecuting = true;
					}
				}
			}

			const bool bMutexStateRestored = bMutexAlreadyOwned || m_Mutex.UnLock();
			return !bMutexStateRestored || bExecuting;
		}

		bool Suspender::IsRegionInCallStacks(void const* const pAddress, const std::size_t unSize) noexcept {
			if (!pAddress || !unSize) {
				return false;
			}

			const bool bMutexAlreadyOwned = IsLinuxMutexOwnedByCurrentThread(static_cast<LinuxMutexHandle*>(m_Mutex.GetMutex()));
			if (!bMutexAlreadyOwned && !LockAndRefreshForkState()) {
				return true;
			}

			bool bReferenced = false;

			try {
				if (m_unSuspendDepth != 0) {
					auto* const pProcessState = GetThreadSuspendProcessState();
					if (!pProcessState) {
						bReferenced = m_unSuspendedThreadCount != 0;

					} else {
						std::lock_guard<std::mutex> RequestLock(pProcessState->m_RequestMutex);
						bReferenced =
							(IsSuspendedInstructionPointerInRange(pProcessState, m_arrSuspendedThreadIDs.data(), m_unSuspendedThreadCount, pAddress, unSize)) ||
							(IsSuspendedStackReferencingRange(pProcessState, m_arrSuspendedThreadIDs.data(), m_unSuspendedThreadCount, pAddress, unSize));
					}
				}
			} catch (...) {
				bReferenced = true;
			}

			const bool bMutexStateRestored = bMutexAlreadyOwned || m_Mutex.UnLock();
			return !bMutexStateRestored || bReferenced;
		}

		bool Suspender::FixExecutionAddress(void const* const pAddress, void const* const pNewAddress) {
			if (!pAddress || !pNewAddress) {
				return false;
			}

			const std::uintptr_t unAddress = reinterpret_cast<std::uintptr_t>(pAddress);
			const std::uintptr_t unNewAddress = reinterpret_cast<std::uintptr_t>(pNewAddress);

			const bool bMutexAlreadyOwned = IsLinuxMutexOwnedByCurrentThread(static_cast<LinuxMutexHandle*>(m_Mutex.GetMutex()));
			if (!bMutexAlreadyOwned && !LockAndRefreshForkState()) {
				return false;
			}

			bool bScanSucceeded = false;

			if (m_unSuspendDepth != 0) {
				auto* const pProcessState = GetThreadSuspendProcessState();
				if (pProcessState) {
					try {
						std::lock_guard<std::mutex> RequestLock(pProcessState->m_RequestMutex);
						for (auto& SuspendedThreadSlot : pProcessState->m_SuspendedThreadSlots) {
							const std::size_t unRequestState = SuspendedThreadSlot.m_unRequestState.load(std::memory_order_acquire);
							if (GetThreadSuspendState(unRequestState) != kLinuxThreadSuspendStateSuspended) {
								continue;
							}

							const pid_t nThreadID = SuspendedThreadSlot.m_nThreadID.load(std::memory_order_relaxed);
							if (!IsSuspendedThreadOwned(m_arrSuspendedThreadIDs.data(), m_unSuspendedThreadCount, nThreadID)) {
								continue;
							}

							if (SuspendedThreadSlot.m_unInstructionPointer.load(std::memory_order_relaxed) != unAddress) {
								continue;
							}

							SuspendedThreadSlot.m_unInstructionPointer.store(unNewAddress, std::memory_order_relaxed);
							SuspendedThreadSlot.m_unNewInstructionPointer.store(unNewAddress, std::memory_order_relaxed);
							SuspendedThreadSlot.m_bHasNewInstructionPointer.store(true, std::memory_order_release);
						}

						bScanSucceeded = true;
					} catch (...) {
						bScanSucceeded = false;
					}
				}
			}

			const bool bMutexStateRestored = bMutexAlreadyOwned || m_Mutex.UnLock();
			return bMutexStateRestored && bScanSucceeded;
		}

		SuspendTransaction::SuspendTransaction(Suspender& SuspenderReference, const bool bSweepThreads) :
			m_pSuspender(&SuspenderReference)
		{
			m_unBeginDepth = 0;
			m_nProcessID = ::getpid();
			m_bActive = false;

			// Begin records the result in m_bActive for the query and conversion contracts.
			Begin(bSweepThreads);
		}

		SuspendTransaction::~SuspendTransaction() noexcept {
			EndNoFail();
		}

		void SuspendTransaction::RefreshForkState() noexcept {
			const pid_t nCurrentProcessID = ::getpid();
			if (m_nProcessID == nCurrentProcessID) {
				return;
			}

			m_nProcessID = nCurrentProcessID;
			m_unBeginDepth = 0;
			m_bActive = false;
		}

		bool SuspendTransaction::Begin(const bool bSweepThreads) {
			RefreshForkState();

			if (!m_pSuspender || m_bActive) {
				return false;
			}

			m_unBeginDepth = m_pSuspender->GetSuspendDepth();
			m_bActive = m_pSuspender->Suspend(bSweepThreads);

			return m_bActive;
		}

		bool SuspendTransaction::End() {
			const bool bInheritedActiveState = m_bActive && (m_nProcessID != ::getpid());
			RefreshForkState();

			if (bInheritedActiveState) {
				return false;
			}

			if (!m_pSuspender || !m_bActive) {
				return false;
			}

			if ((m_pSuspender->GetSuspendDepth() > m_unBeginDepth) && !m_pSuspender->Resume()) {
				return false;
			}

			m_bActive = false;

			return true;
		}

		bool SuspendTransaction::IsActive() const noexcept {
			if (m_nProcessID != ::getpid()) {
				return false;
			}

			return m_bActive;
		}

		SuspendTransaction::operator bool() const noexcept {
			return IsActive();
		}
#endif

		void SuspendTransaction::EndNoFail() noexcept {
#if defined(__linux__)
			LinuxCancellationDisableGuard CancellationGuard;

			if (m_nProcessID != ::getpid()) {
				RefreshForkState();

				return;
			}
#endif

			while (m_pSuspender && m_bActive) {
				try {
					if (End()) {
						return;
					}
				} catch (...) {
					// Cleanup retries until End succeeds or the transaction becomes inactive.
				}

#if defined(_WIN32)
				SwitchToThread();
#elif defined(__linux__)
				std::this_thread::yield();
#endif
			}
		}

		static Suspender* GetHookSuspender() noexcept {
			// The allocation intentionally has process lifetime to avoid teardown-order races.
			auto CreateSuspender = []() noexcept -> Suspender* {
				try {
					return new Suspender();
				} catch (...) {
					return nullptr;
				}
			};
			static Suspender* const s_pSuspender = CreateSuspender();

			return s_pSuspender;
		}

