		bool PipeClient::Open(char const* const pszPipeName, const std::size_t unCapacity) {
			constexpr int kSocketType = SOCK_STREAM | SOCK_CLOEXEC;
			constexpr int kDefaultProtocol = 0;

			if (m_hPipe) {
				return false;
			}

			if (!m_unBufferSize) {
				return false;
			}

			char szValidatedPipeName[kNamedObjectNameCapacity] {};
			if (!CopyNamedObjectName(szValidatedPipeName, kNamedObjectNameCapacity, pszPipeName, unCapacity)) {
				return false;
			}

			std::unique_ptr<LinuxPipeHandle, void(*)(LinuxPipeHandle*)> pPipe(new (std::nothrow) LinuxPipeHandle(), PipeDestroy);
			if (!pPipe) {
				return false;
			}

			try {
				pPipe->m_strPath = szValidatedPipeName;
			} catch (...) {
				return false;
			}

			pPipe->m_unBufferSize = m_unBufferSize;

			sockaddr_un Address {};
			socklen_t unAddressSize {};
			if (!BuildUNIXSocketAddress(pPipe->m_strPath, &Address, &unAddressSize)) {
				return false;
			}

			const int nConnectionFD = ::socket(AF_UNIX, kSocketType, kDefaultProtocol);
			if (nConnectionFD < 0) {
				return false;
			}

			pPipe->m_nFD = nConnectionFD;
			if (::connect(nConnectionFD, reinterpret_cast<sockaddr const*>(&Address), unAddressSize) != 0) {
				return false;
			}

			m_hPipe = pPipe.release();

			return true;
		}

