		bool Fiber::Switch() {
			constexpr SIZE_T kDefaultStackSize = 0;

			if (!m_pCallBack) {
				return false;
			}

			FiberStartupData StartupData {};
			bool bConvertedThread = false;

			if (IsThreadAFiber()) {
				StartupData.m_pFiberMain = GetCurrentFiber();
			} else {
				StartupData.m_pFiberMain = ConvertThreadToFiber(nullptr);
				if (!StartupData.m_pFiberMain) {
					return false;
				}

				bConvertedThread = true;
			}

			StartupData.m_fnCallBack = m_pCallBack;
			StartupData.m_pData = m_pData;

			void* const pFiber = CreateFiber(kDefaultStackSize, FiberRoutine, &StartupData);
			if (!pFiber) {
				if (bConvertedThread) {
					// Best-effort rollback preserves the existing failure result.
					ConvertFiberToThread();
				}

				return false;
			}

			SwitchToFiber(pFiber);
			DeleteFiber(pFiber);

			if (bConvertedThread && !ConvertFiberToThread()) {
				return false;
			}

			return StartupData.m_bCallBackSucceeded;
		}

