		Page* MemoryManager::CreatePage() {
			std::unique_ptr<Page> pPage(new (std::nothrow) Page());
			if (!pPage || !pPage->GetPageAddress() || !pPage->GetPageCapacity()) {
				return nullptr;
			}

			Page* const pPageResult = pPage.get();

			try {
				m_deqPages.emplace_back(std::move(pPage));
			} catch (...) {
				return nullptr;
			}

			return pPageResult;
		}

		Storage* MemoryManager::CreateStorage(const std::size_t unRequestedTotalCapacity, const std::size_t unRequestedRegionCapacity) {
			std::unique_ptr<Storage> pStorage(new (std::nothrow) Storage(unRequestedTotalCapacity, unRequestedRegionCapacity));
			if (!pStorage || !pStorage->GetStorageCapacity()) {
				return nullptr;
			}

			Storage* const pStorageResult = pStorage.get();

			try {
				m_deqStorages.emplace_back(std::move(pStorage));
			} catch (...) {
				return nullptr;
			}

			return pStorageResult;
		}

		bool MemoryManager::DestroyPage(Page* const pPage) {
			if (!pPage) {
				return false;
			}

			for (auto itPage = m_deqPages.begin(); itPage != m_deqPages.end(); ++itPage) {
				if (itPage->get() == pPage) {
					m_deqPages.erase(itPage);
					return true;
				}
			}

			return false;
		}

		bool MemoryManager::DestroyStorage(Storage* const pStorage) {
			if (!pStorage) {
				return false;
			}

			for (auto itStorage = m_deqStorages.begin(); itStorage != m_deqStorages.end(); ++itStorage) {
				if (itStorage->get() == pStorage) {
					m_deqStorages.erase(itStorage);
					return true;
				}
			}

			return false;
		}

		std::unique_ptr<Page> MemoryManager::GetPage(void* const pAddress) {
			constexpr bool kPageAutoRestore = true;
			constexpr bool kCommitPage = false;

			if (!pAddress) {
				return nullptr;
			}

			PAGE_INFO PageInfo {};
			if (!GetPageInfo(pAddress, &PageInfo) || (PageInfo.m_unState != MEM_COMMIT)) {
				return nullptr;
			}

			std::unique_ptr<Page> pPage(new (std::nothrow) Page(PageInfo.m_pBaseAddress, kPageAutoRestore, kCommitPage));
			if (!pPage || !pPage->GetPageAddress() || !pPage->GetPageCapacity()) {
				return nullptr;
			}

			return pPage;
		}

		std::unique_ptr<Region> MemoryManager::GetRegion(void* const pAddress) {
			constexpr bool kRegionAutoRestore = true;

			if (!pAddress) {
				return nullptr;
			}

			REGION_INFO RegionInfo {};
			if (!GetRegionInfo(pAddress, &RegionInfo) || (RegionInfo.m_unState != MEM_COMMIT)) {
				return nullptr;
			}

			std::unique_ptr<Region> pRegion(new (std::nothrow) Region(RegionInfo.m_pBaseAddress, kRegionAutoRestore));
			if (!pRegion || !pRegion->GetRegionAddress() || !pRegion->GetRegionCapacity()) {
				return nullptr;
			}

			return pRegion;
		}

		std::vector<Page> MemoryManager::CollectPages(void* const pAddress, const std::size_t unSize) {
			constexpr bool kUnlimitedBounds = false;
			constexpr bool kPageAutoRestore = true;

			std::vector<Page> vecPages;

			if (!pAddress || !unSize) {
				return vecPages;
			}

			try {
				std::vector<PAGE_INFO> const vecPageInformation = GetPagesInfo(pAddress, unSize, kUnlimitedBounds);
				vecPages.reserve(vecPageInformation.size());

				for (auto const& PageInfo : vecPageInformation) {
					if (PageInfo.m_unState != MEM_COMMIT) {
						continue;
					}

					vecPages.emplace_back(PageInfo.m_pBaseAddress, kPageAutoRestore);
					if (!vecPages.back().GetPageAddress()) {
						vecPages.pop_back();
					}
				}
			} catch (...) {
				vecPages.clear();
			}

			return vecPages;
		}

		std::vector<Region> MemoryManager::CollectRegions(void* const pAddress, const std::size_t unSize) {
			constexpr bool kRegionAutoRestore = true;

			std::vector<Region> vecRegions;

			if (!pAddress || !unSize) {
				return vecRegions;
			}

			try {
				std::vector<REGION_INFO> const vecRegionInformation = GetRegionsInfo(pAddress, unSize);
				vecRegions.reserve(vecRegionInformation.size());

				for (auto const& RegionInfo : vecRegionInformation) {
					if (RegionInfo.m_unState != MEM_COMMIT) {
						continue;
					}

					vecRegions.emplace_back(RegionInfo.m_pBaseAddress, kRegionAutoRestore);
					if (!vecRegions.back().GetRegionAddress()) {
						vecRegions.pop_back();
					}
				}
			} catch (...) {
				vecRegions.clear();
			}

			return vecRegions;
		}
