		SharedServer::SharedServer(const std::size_t unSize, const bool) :
			m_szSharedName {}
		{
			constexpr char kSharedNamePrefix[] = "shared";
			constexpr mode_t kSharedPermissions = 0600;
			constexpr off_t kMappingOffset = 0;

			m_hMap = nullptr;
			m_pAddress = nullptr;

			if (!unSize || !SizeFitsFileOffset(unSize)) {
				return;
			}

			std::string const strName = MakePOSIXName(kSharedNamePrefix);
			if (strName.empty()) {
				return;
			}

			const int nNameLength = std::snprintf(m_szSharedName, sizeof(m_szSharedName), "%s", strName.c_str());
			if ((nNameLength < 0) || (static_cast<std::size_t>(nNameLength) >= sizeof(m_szSharedName))) {
				m_szSharedName[0] = '\0';
				return;
			}

			std::unique_ptr<LinuxSharedMap, void(*)(LinuxSharedMap*)> pMap(new (std::nothrow) LinuxSharedMap(), SharedMapDestroy);
			if (!pMap) {
				m_szSharedName[0] = '\0';
				return;
			}

			pMap->m_bNamed = true;
			pMap->m_strName = strName;

			const int nFD = ::shm_open(strName.c_str(), O_CREAT | O_EXCL | O_RDWR, kSharedPermissions);
			if (nFD < 0) {
				m_szSharedName[0] = '\0';
				return;
			}

			pMap->m_nFD = nFD;
			pMap->m_bOwner = true;
			pMap->m_nOwnerProcessID = ::getpid();
			if (::ftruncate(nFD, static_cast<off_t>(unSize)) != 0) {
				m_szSharedName[0] = '\0';
				return;
			}

			void* const pAddress = ::mmap(nullptr, unSize, PROT_READ | PROT_WRITE, MAP_SHARED, nFD, kMappingOffset);
			if (pAddress == MAP_FAILED) {
				m_szSharedName[0] = '\0';
				return;
			}

			pMap->m_unSize = unSize;
			pMap->m_pAddress = pAddress;

			m_hMap = pMap.release();
			m_pAddress = pAddress;
		}

		SharedServer::~SharedServer() noexcept {
			SharedMapDestroy(static_cast<LinuxSharedMap*>(m_hMap));
			m_hMap = nullptr;
			m_pAddress = nullptr;
		}

		SharedServer::SharedServer(SharedServer&& Other) noexcept :
			m_szSharedName {},
			m_hMap(Other.m_hMap),
			m_pAddress(Other.m_pAddress)
		{
			std::memcpy(m_szSharedName, Other.m_szSharedName, sizeof(m_szSharedName));

			std::memset(Other.m_szSharedName, 0, sizeof(Other.m_szSharedName));
			Other.m_hMap = nullptr;
			Other.m_pAddress = nullptr;
		}

		SharedServer& SharedServer::operator=(SharedServer&& Other) noexcept {
			if (this == &Other) {
				return *this;
			}

			SharedMapDestroy(static_cast<LinuxSharedMap*>(m_hMap));

			std::memcpy(m_szSharedName, Other.m_szSharedName, sizeof(m_szSharedName));
			m_hMap = Other.m_hMap;
			m_pAddress = Other.m_pAddress;

			std::memset(Other.m_szSharedName, 0, sizeof(Other.m_szSharedName));
			Other.m_hMap = nullptr;
			Other.m_pAddress = nullptr;

			return *this;
		}

