		SharedClient::SharedClient(char const* const pszSharedName, const std::size_t unCapacity, const bool) {
			constexpr mode_t kUnusedPermissions = 0;
			constexpr off_t kMappingOffset = 0;

			m_hMap = nullptr;
			m_pAddress = nullptr;

			char szValidatedSharedName[kNamedObjectNameCapacity] {};
			if (!CopyNamedObjectName(szValidatedSharedName, kNamedObjectNameCapacity, pszSharedName, unCapacity)) {
				return;
			}

			std::unique_ptr<LinuxSharedMap, void(*)(LinuxSharedMap*)> pMap(new (std::nothrow) LinuxSharedMap(), SharedMapDestroy);
			if (!pMap) {
				return;
			}

			try {
				pMap->m_strName = szValidatedSharedName;
			} catch (...) {
				return;
			}

			pMap->m_bNamed = true;

			const int nFD = ::shm_open(szValidatedSharedName, O_RDWR, kUnusedPermissions);
			if (nFD < 0) {
				return;
			}

			pMap->m_nFD = nFD;

			struct stat Status {};
			if ((::fstat(nFD, &Status) != 0) || !FileOffsetFitsSize(Status.st_size)) {
				return;
			}

			const std::size_t unMapSize = static_cast<std::size_t>(Status.st_size);
			void* const pAddress = ::mmap(nullptr, unMapSize, PROT_READ | PROT_WRITE, MAP_SHARED, nFD, kMappingOffset);
			if (pAddress == MAP_FAILED) {
				return;
			}

			pMap->m_unSize = unMapSize;
			pMap->m_pAddress = pAddress;

			m_hMap = pMap.release();
			m_pAddress = pAddress;
		}

		SharedClient::~SharedClient() noexcept {
			SharedMapDestroy(static_cast<LinuxSharedMap*>(m_hMap));
			m_hMap = nullptr;
			m_pAddress = nullptr;
		}

