					pRecord->m_bIsVirtual = true;
					pRecord->m_bManualProtection = bManualProtection;
					pRecord->m_pIdentityCallBack = fnCallBack;
					pRecord->m_pIdentityContextCallBack = fnContextCallBack;
					pRecord->m_pIdentityContext = pContext;
					pRecord->m_pCallBack = fnCallBack;
					pRecord->m_pPostCallBack = fnPostCallBack;
					pRecord->m_pContextCallBack = fnContextCallBack;
					pRecord->m_pContextPostCallBack = fnContextPostCallBack;
					pRecord->m_pContext = pContext;
					pRecord->m_pAddress = Segment.m_pBaseAddress;
					pRecord->m_unSize = Segment.m_unSize;

					if (!RangeIntersection(pAddress, unSize, Segment.m_pBaseAddress, Segment.m_unSize, &pRecord->m_pUserAddress, &pRecord->m_unUserSize)) {
						return false;
					}

					pRecord->m_pInstallAddress = pAddress;
					pRecord->m_unInstallSize = unSize;

					lstNewRecords.emplace_back(std::move(pRecord));
