			const std::size_t unPageSize = LinuxPageSize();
			if ((!unPageSize) || ((unPageSize & (unPageSize - 1)) != 0) ||
				(unPageSize > std::numeric_limits<std::uintptr_t>::max())) {
				return false;
			}

			const std::uintptr_t unPageSizeAddress = static_cast<std::uintptr_t>(unPageSize);
			const std::uintptr_t unRangeEndAddress = unAddress + static_cast<std::uintptr_t>(unSize);
			if (unRangeEndAddress > (std::numeric_limits<std::uintptr_t>::max() - (unPageSizeAddress - 1))) {
				return false;
			}

			const std::uintptr_t unStartAddress = AlignDown<std::uintptr_t>(unAddress, unPageSizeAddress);
			const std::uintptr_t unEndAddress = AlignUp<std::uintptr_t>(unRangeEndAddress, unPageSizeAddress);

