		ProtectedPage::ProtectedPage() {
			m_pState = CreateProtectedMemoryState(GetProtectedMemoryPageSize(), false);
		}

		ProtectedPage::ProtectedPage(void* const pAddress, const std::size_t unSize) {
			if (unSize == GetProtectedMemoryPageSize()) {
				m_pState = AcquireProtectedMemoryState(pAddress, unSize, false, false);
			}
		}

		ProtectedPage::~ProtectedPage() noexcept {
			Release();
		}

		void* ProtectedPage::Alloc(const std::size_t unSize, const std::size_t unSizeAlignment, const std::size_t unAddressAlignment) {
			return AllocProtectedMemoryBlock(GetProtectedMemoryState(m_pState), unSize, unSizeAlignment, unAddressAlignment);
		}

		void* ProtectedPage::ZeroAlloc(const std::size_t unSize, const std::size_t unSizeAlignment, const std::size_t unAddressAlignment) {
			return ZeroAllocProtectedMemoryBlock(GetProtectedMemoryState(m_pState), unSize, unSizeAlignment, unAddressAlignment);
		}

		bool ProtectedPage::DeAlloc(void* const pAddress) {
			return DeAllocProtectedMemoryBlock(GetProtectedMemoryState(m_pState), pAddress);
		}

		bool ProtectedPage::DeAllocAll() {
			return DeAllocAllProtectedMemoryBlocks(GetProtectedMemoryState(m_pState));
		}

		bool ProtectedPage::Release() {
			return ReleaseProtectedMemoryLayer(m_pState, false);
		}

