		bool ProtectedRange::IsProtected() const noexcept {
			auto* const pState = GetProtectedMemoryState(m_pState);
			ProtectedMemoryStateLock StateLock(pState);
			return StateLock.IsLocked() && pState->m_bHooked &&
				!pState->m_bProtectionError.load(std::memory_order_acquire) &&
				CheckProtectedMemoryShadowMetadataProtection(pState) &&
				IsProtectedMemoryNoAccess(pState->m_pAddress, pState->m_unProtectedSize);
		}

		bool ProtectedRange::IsCompromised() const noexcept {
			return IsProtectedMemoryCompromised(GetProtectedMemoryState(m_pState));
		}

		static void FailCloseProtectedMemoryStorageRange(void* const pAddress) noexcept {
			if (!pAddress) {
				return;
			}

			auto* const pRegistry = GetProtectedMemoryRegistryState();
			if (!pRegistry) {
				return;
			}

			ProtectedMemoryRegistryState& Registry = *pRegistry;
			ProtectedMemoryRegistryLock RegistryLock(Registry);
			if (!RegistryLock.IsLocked()) {
				return;
			}

			const std::uintptr_t unAddress = reinterpret_cast<std::uintptr_t>(pAddress);
			auto itState = Registry.m_mapStates.find(unAddress);
			if (itState == Registry.m_mapStates.end()) {
				return;
			}

			std::shared_ptr<ProtectedMemoryState> const pState = itState->second.lock();
			if (!pState) {
				return;
			}

			ProtectedMemoryStateLock StateLock(pState.get());
			if (!StateLock.IsLocked()) {
				return;
			}

			if ((pState->m_pAddress != pAddress) || !pState->m_unProtectedSize) {
				return;
			}

			pState->m_bProtectionError.store(true, std::memory_order_release);

			const bool bPayloadHidden = IsProtectedMemoryNoAccess(pState->m_pAddress, pState->m_unProtectedSize) ||
				ChangeProtectedMemoryProtection(pState->m_pAddress, pState->m_unProtectedSize, false);
			const bool bShadowHidden = CheckProtectedMemoryShadowMetadataProtection(pState.get()) ||
				ForceCloseProtectedMemoryShadowMetadata(pState.get());

			if (bPayloadHidden) {
				pState->m_bOpen = false;
				pState->m_bConfiguredProtectionApplied = false;
				pState->m_unOpenReferences = 0;
			}

			if (!bShadowHidden) {
				pState->m_bProtectionError.store(true, std::memory_order_release);
			}
		}

		template <typename TRange, typename TProtection>
		static bool RestoreProtectedMemoryStorageRangeProtection(TRange* const pRange, TProtection const PreviousProtection) noexcept {
			if (!pRange) {
				return false;
			}

			for (std::size_t unAttempt = 0; unAttempt < kProtectedMemoryStorageRollbackAttemptCount; ++unAttempt) {
				if (!pRange->SetProtection(PreviousProtection)) {
					continue;
				}

				TProtection CurrentProtection {};
				if (pRange->GetProtection(&CurrentProtection) && (CurrentProtection == PreviousProtection)) {
					return true;
				}
			}

			FailCloseProtectedMemoryStorageRange(pRange->GetRangeAddress());

			return false;
		}

		// ----------------------------------------------------------------
		// ProtectedStorage
		// ----------------------------------------------------------------

		ProtectedStorage::ProtectedStorage(const std::size_t unTotalCapacity) :
			m_unTotalCapacity(unTotalCapacity)
		{
			m_unUsedSpace = 0;
#if defined(_WIN32)
			m_unProtection = kProtectedMemoryDefaultProtection;
#elif defined(__linux__)
			m_nProtection = kProtectedMemoryDefaultProtection;
#else
#error Unsupported platform
#endif
		}

		ProtectedStorage::~ProtectedStorage() noexcept = default;

		void* ProtectedStorage::Alloc(const std::size_t unSize) {
#if defined(_WIN32)
			const bool bProtectionValid = IsProtectedMemoryProtectionValid(m_unProtection);
#elif defined(__linux__)
			const bool bProtectionValid = IsProtectedMemoryProtectionValid(m_nProtection);
#else
#error Unsupported platform
#endif
			if (!bProtectionValid || !unSize ||
				(unSize > (std::numeric_limits<std::size_t>::max() - m_unUsedSpace)) ||
				(m_unTotalCapacity && ((m_unUsedSpace + unSize) > m_unTotalCapacity))) {
				return nullptr;
			}

			try {
				std::unique_ptr<ProtectedRange> pRange(new (std::nothrow) ProtectedRange(unSize));
				if (!pRange || !pRange->IsProtected() || !pRange->GetRangeAddress()) {
					return nullptr;
				}

#if defined(_WIN32)
				const bool bProtectionSet = pRange->SetProtection(m_unProtection);
#elif defined(__linux__)
				const bool bProtectionSet = pRange->SetProtection(m_nProtection);
#else
#error Unsupported platform
#endif
				if (!bProtectionSet) {
					return nullptr;
				}

				void* const pAddress = pRange->GetRangeAddress();
				m_lstRanges.emplace_back(std::move(pRange));
				m_unUsedSpace += unSize;

				return pAddress;
			} catch (...) {
				return nullptr;
			}
		}

		void* ProtectedStorage::ZeroAlloc(const std::size_t unSize) {
			return Alloc(unSize);
		}

		bool ProtectedStorage::DeAlloc(void* const pAddress) {
			if (!pAddress) {
				return false;
			}

			for (auto itRange = m_lstRanges.begin(); itRange != m_lstRanges.end(); ++itRange) {
				std::unique_ptr<ProtectedRange> const& pRange = *itRange;
				if (!pRange || (pRange->GetRangeAddress() != pAddress)) {
					continue;
				}

				const std::size_t unRangeSize = pRange->GetRangeSize();
				if (unRangeSize > m_unUsedSpace) {
					return false;
				}

				if (!pRange->Release()) {
					return false;
				}

				m_lstRanges.erase(itRange);
				m_unUsedSpace -= unRangeSize;

				return true;
			}

			return false;
		}

		bool ProtectedStorage::DeAllocAll() {
			bool bSuccess = true;
			for (auto itRange = m_lstRanges.begin(); itRange != m_lstRanges.end();) {
				std::unique_ptr<ProtectedRange> const& pRange = *itRange;
				if (!pRange) {
					itRange = m_lstRanges.erase(itRange);
					continue;
				}

				const std::size_t unRangeSize = pRange->GetRangeSize();
				if (unRangeSize > m_unUsedSpace) {
					bSuccess = false;
					++itRange;
					continue;
				}

				if (!pRange->Release()) {
					bSuccess = false;
					++itRange;
					continue;
				}

				m_unUsedSpace -= unRangeSize;
				itRange = m_lstRanges.erase(itRange);
			}

			return bSuccess;
		}

#if defined(_WIN32)
		bool ProtectedStorage::GetProtection(DWORD* const punProtectionOut) const noexcept {
			if (!IsProtectedMemoryProtectionValid(m_unProtection) || !punProtectionOut) {
				return false;
			}

			*punProtectionOut = m_unProtection;

			return true;
		}

		bool ProtectedStorage::SetProtection(const DWORD unProtection) noexcept {
			if (!IsProtectedMemoryProtectionValid(m_unProtection) || !IsProtectedMemoryProtectionValid(unProtection)) {
				return false;
			}

			std::vector<DWORD> vecPreviousProtections;
			try {
				vecPreviousProtections.reserve(m_lstRanges.size());
				for (auto const& pRange : m_lstRanges) {
					DWORD unPreviousProtection = 0;
					if (!pRange || !pRange->GetProtection(&unPreviousProtection)) {
						return false;
					}

					vecPreviousProtections.push_back(unPreviousProtection);
				}
			} catch (...) {
				return false;
			}

			std::size_t unChangedRangeCount = 0;
			for (auto itRange = m_lstRanges.begin(); itRange != m_lstRanges.end(); ++itRange) {
				std::unique_ptr<ProtectedRange> const& pRange = *itRange;
				if (pRange->SetProtection(unProtection)) {
					++unChangedRangeCount;
					continue;
				}

				auto itRollback = itRange;
				for (std::size_t unRollbackIndex = unChangedRangeCount; unRollbackIndex > 0; --unRollbackIndex) {
					--itRollback;
					if (!RestoreProtectedMemoryStorageRangeProtection(itRollback->get(), vecPreviousProtections[unRollbackIndex - 1])) {
						m_unProtection = kProtectedMemoryStoragePoisonProtection;
					}
				}

				return false;
			}

			m_unProtection = unProtection;

			return true;
		}
#elif defined(__linux__)
		bool ProtectedStorage::GetProtection(int* const pnProtectionOut) const noexcept {
			if (!IsProtectedMemoryProtectionValid(m_nProtection) || !pnProtectionOut) {
				return false;
			}

			*pnProtectionOut = m_nProtection;

			return true;
		}

		bool ProtectedStorage::SetProtection(const int nProtection) noexcept {
			if (!IsProtectedMemoryProtectionValid(m_nProtection) || !IsProtectedMemoryProtectionValid(nProtection)) {
				return false;
			}

			std::vector<int> vecPreviousProtections;
			try {
				vecPreviousProtections.reserve(m_lstRanges.size());
				for (auto const& pRange : m_lstRanges) {
					int nPreviousProtection = 0;
					if (!pRange || !pRange->GetProtection(&nPreviousProtection)) {
						return false;
					}

					vecPreviousProtections.push_back(nPreviousProtection);
				}
			} catch (...) {
				return false;
			}

			std::size_t unChangedRangeCount = 0;
			for (auto itRange = m_lstRanges.begin(); itRange != m_lstRanges.end(); ++itRange) {
				std::unique_ptr<ProtectedRange> const& pRange = *itRange;
				if (pRange->SetProtection(nProtection)) {
					++unChangedRangeCount;
					continue;
				}

				auto itRollback = itRange;
				for (std::size_t unRollbackIndex = unChangedRangeCount; unRollbackIndex > 0; --unRollbackIndex) {
					--itRollback;
					if (!RestoreProtectedMemoryStorageRangeProtection(itRollback->get(), vecPreviousProtections[unRollbackIndex - 1])) {
						m_nProtection = kProtectedMemoryStoragePoisonProtection;
					}
				}

				return false;
			}

			m_nProtection = nProtection;

			return true;
		}
#else
#error Unsupported platform
#endif

		std::size_t ProtectedStorage::GetStorageCapacity() const noexcept {
			return m_unTotalCapacity;
		}

		std::size_t ProtectedStorage::GetDataSize() const noexcept {
			return m_unUsedSpace;
		}

		bool ProtectedStorage::IsStorageEmpty() const noexcept {
			return m_lstRanges.empty();
		}

		bool ProtectedStorage::IsProtected() const noexcept {
#if defined(_WIN32)
			const bool bProtectionValid = IsProtectedMemoryProtectionValid(m_unProtection);
#elif defined(__linux__)
			const bool bProtectionValid = IsProtectedMemoryProtectionValid(m_nProtection);
#else
#error Unsupported platform
#endif
			if (!bProtectionValid || m_lstRanges.empty()) {
				return false;
			}

			for (auto const& pRange : m_lstRanges) {
				if (!pRange || !pRange->IsProtected()) {
					return false;
				}
			}

			return true;
		}

		bool ProtectedStorage::IsCompromised() const noexcept {
			for (auto const& pRange : m_lstRanges) {
				if (pRange && pRange->IsCompromised()) {
					return true;
				}
			}

			return false;
		}

