		// ProtectedMemoryManager
		// ----------------------------------------------------------------

		ProtectedPage* ProtectedMemoryManager::CreatePage() {
			try {
				std::unique_ptr<ProtectedPage> pPage(new (std::nothrow) ProtectedPage());
				if (!pPage || !pPage->GetPageAddress() || !pPage->IsProtected()) {
					return nullptr;
				}

				auto* const pPageResult = pPage.get();
				m_deqPages.emplace_back(std::move(pPage));

				return pPageResult;
			} catch (...) {
				return nullptr;
			}
		}

		ProtectedStorage* ProtectedMemoryManager::CreateStorage(const std::size_t unTotalCapacity) {
			try {
				std::unique_ptr<ProtectedStorage> pStorage(new (std::nothrow) ProtectedStorage(unTotalCapacity));
				if (!pStorage) {
					return nullptr;
				}

				auto* const pStorageResult = pStorage.get();
				m_deqStorages.emplace_back(std::move(pStorage));

				return pStorageResult;
			} catch (...) {
				return nullptr;
			}
		}

		bool ProtectedMemoryManager::DestroyPage(ProtectedPage* const pPage) {
			if (!pPage) {
				return false;
			}

			for (auto itPage = m_deqPages.begin(); itPage != m_deqPages.end(); ++itPage) {
				if (itPage->get() == pPage) {
					if (!pPage->Release()) {
						return false;
					}

					m_deqPages.erase(itPage);
					return true;
				}
			}

			return false;
		}

		bool ProtectedMemoryManager::DestroyStorage(ProtectedStorage* const pStorage) {
			if (!pStorage) {
				return false;
			}

			for (auto itStorage = m_deqStorages.begin(); itStorage != m_deqStorages.end(); ++itStorage) {
				if (itStorage->get() == pStorage) {
					if (!pStorage->DeAllocAll()) {
						return false;
					}

					m_deqStorages.erase(itStorage);
					return true;
				}
			}

			return false;
		}

