				if (!CallTrampolineProtection.Restore()) {
					DetoursDebugBreak();
				}

				pRawCallTrampolineStorage->DeAlloc(m_pCallTrampoline);
				m_pCallTrampoline = nullptr;
				if (!TrampolineProtection.Restore()) {
					DetoursDebugBreak();
				}

				pHookStorage->DeAlloc(m_pTrampoline);
				m_pTrampoline = nullptr;
				m_unFirstInstructionSize = 0;
				if (!WrapperProtection.Restore()) {
					DetoursDebugBreak();
				}

